local config = {
  ui_story_5089_50890100_1_dialog_content = "El clima es realmente agradable hoy. Se siente bien pasear solo por la ciudad de Haojin después de tanto tiempo.",
  ui_story_5089_50890100_2_dialog_content = "Pero sentí que me observaban desde que llegué aquí...",
  ui_story_5089_50890100_3_dialog_content = "No percibo ninguna malicia, pero aún así me da escalofríos... ¿Soy demasiado extraño para los demás aquí?",
  ui_story_5089_50890100_4_dialog_content = "Ejem, perdóname, joven, pero ¿eres el enviado de Astra?",
  ui_story_5089_50890100_5_dialog_content = "Um, sí, eso es correcto. ¿Hay algo que necesitas?",
  ui_story_5089_50890100_6_dialog_content = "¡Ah, qué maravilloso! Solo soy un pequeño empresario, dirigiendo algunos restaurantes y hoteles en el Reino Ji.",
  ui_story_5089_50890100_7_dialog_content = "Me dijeron que te gusta el tofu seco, y una de mis tiendas se especializa en hacerlo. No es mucho como regalo, pero por favor acéptalo.",
  ui_story_5089_50890100_8_dialog_content = "Si el sabor es de tu agrado, solo pide y te enviaré aún más!",
  ui_story_5089_50890100_9_dialog_content = "¿Eh? ¿Cuándo dije que amo el tofu seco? Espera, todavía no sé quién eres tú—",
  ui_story_5089_50890100_10_dialog_content = "¡El estimado enviado finalmente ha llegado! ¡Qué honor es conocerte! Por favor, echa un vistazo a mis finas sedas!",
  ui_story_5089_50890100_11_dialog_content = "¡Rápido! ¡Trae el invaluable Brocado de Armonía Fénix de nuestra tienda y preséntaselo a nuestro invitado!",
  ui_story_5089_50890100_12_dialog_content = "¡Oh no, no podría tomar eso posiblemente!",
  ui_story_5089_50890100_13_dialog_content = "Perdóneme, pero mi maestro ha preparado una gran comida para usted. ¡Sería un honor tener al enviado de Astra como nuestro invitado de honor!",
  ui_story_5089_50890100_14_dialog_content = "¡Saludos, señor! La hija de mi amo está organizando una reunión de poesía en nuestra casa mañana, y ella escribió esta invitación especialmente para usted.",
  ui_story_5089_50890100_15_dialog_content = "¿Quién es ese de ahí? ¿Por qué están causando tal alboroto?",
  ui_story_5089_50890100_16_dialog_content = "¡Parece que es el enviado de las tierras occidentales!",
  ui_story_5089_50890100_17_dialog_content = "El que ganó el favor de la Doncella del Dragón, y ayudó a aliviar la inundación en Haojin y a derrotar a un dragón malvado. ¡Escucho que el enviado incluso se va a casar con el príncipe heredero pronto!",
  ui_story_5089_50890100_18_dialog_content = "¿En serio? ¡Vamos a echar un vistazo!",
  ui_story_5089_50890100_19_dialog_content = "¡Enviada! ¡Por aquí, enviada...!",
  ui_story_5089_50890100_20_dialog_content = "(E-Esto es malo! ¡Necesito salir de aquí!)",
  ui_story_5089_50890100_21_dialog_content = "Ja... Uf... Finalmente logré volver.",
  ui_story_5089_50890100_22_dialog_content = "Sé que les eché una mano antes, pero el entusiasmo de todos parece un poco exagerado.",
  ui_story_5089_50890100_23_dialog_content = "¿Tengo que pedirle a Chen'ni que me cubra cada vez que salgo ahora?",
  ui_story_5089_50890100_24_dialog_content = "Además, estoy bastante seguro de que escuché a uno de ellos decir algo totalmente ridículo justo ahora.",
  ui_story_5089_50890100_25_dialog_content = "<color=#e8d9bb>¡Chirrido-chirrido!</color>",
  ui_story_5089_50890100_26_dialog_content = "¡Oye, es el pájaro mecánico que envié para entregar un mensaje a Xuan Ji! Veamos...",
  ui_story_5089_50890100_27_dialog_content = "¿Ah?",
  ui_story_5089_50890100_28_dialog_content = "Esta es la carta que envié, pero ni siquiera ha sido abierta. ¿No pudo encontrarla?",
  ui_story_5089_50890100_29_dialog_content = "Chirrido.",
  ui_story_5089_50890100_30_dialog_content = "Eso es extraño. Durante el Festival de Primavera, dijo que iba a regresar al Reino de Ye para manejar algunos asuntos pendientes.",
  ui_story_5089_50890100_31_dialog_content = "Entonces, ¿cómo terminé en un antiguo bosque de montaña?",
  ui_story_5089_50890100_32_dialog_content = "Ahora que lo pienso, desde que llegué a Longzhou, ella ha estado manteniendo su distancia mientras investiga algo. ¿Podría ser...?",
  ui_story_5089_50890100_33_dialog_content = "Señor, un invitado está aquí para verlo.",
  ui_story_5089_50890100_34_dialog_content = "... ¿D-Dieron esas personas siguieron todo el camino hasta la Casa de Huéspedes Real?!",
  ui_story_5089_50890100_35_dialog_content = "Lo siento, pero no quiero verlos ahora. Solo di que los Caelestites tienen que hibernar durante el invierno o algo así.",
  ui_story_5089_50890100_36_dialog_content = "Pero... ¿No acaba de pasar el invierno?",
  ui_story_5089_50890100_37_dialog_content = "¡E-Entonces solo diles que todavía me estoy adaptando a la primavera y que tengo que prepararme para la hibernación del próximo año! No importa. ¡Solo encuentra una excusa!",
  ui_story_5089_50890100_38_dialog_content = "Nunca pensé que sería tan difícil conseguir una audiencia contigo, PlayerName.",
  ui_story_5089_50890100_39_dialog_content = "D-Dantang?! No, esas excusas no eran para ti—",
  ui_story_5089_50890100_40_dialog_content = "Lo se.",
  ui_story_5089_50890100_41_dialog_content = "Ya no eres solo un enviado de Astra, sino también un héroe consumado para el Reino de Ji.",
  ui_story_5089_50890100_42_dialog_content = "Las calles de Haojin están llenas de rumores sobre su próximo compromiso con el príncipe heredero también.",
  ui_story_5089_50890100_43_dialog_content = "No es de extrañar que los comerciantes del Reino de Ji estén compitiendo para establecer una buena relación contigo.",
  ui_story_5089_50890100_44_dialog_content = "¿Por qué todos en Haojin saben sobre esto?! ¿Y nadie tiene preguntas al respecto?",
  ui_story_5089_50890100_45_dialog_content = "¿Incluso los rumores más absurdos contienen un grano de verdad, no?",
  ui_story_5089_50890100_46_dialog_content = "G-Dame un respiro...",
  ui_story_5089_50890100_47_dialog_content = "Hay méritos en aceptar la propuesta del príncipe heredero, ¿sabes?",
  ui_story_5089_50890100_48_dialog_content = "Puede que sea un poco travieso, pero su corazón es puro y está lleno de admiración por tus hazañas heroicas durante el equinoccio de primavera.",
  ui_story_5089_50890100_49_dialog_content = "Después de convertirte en la consorte del príncipe heredero y mudarte al palacio real, nadie se atreverá a difundir rumores sobre ti nuevamente.",
  ui_story_5089_50890100_50_dialog_content = "¿Realmente necesitas algo, Dantang? ¿O viniste aquí seriamente solo para jugar conmigo?",
  ui_story_5089_50890100_51_dialog_content = "\"¿Jugar contigo\"? ¿Es realmente así como me ves, PlayerName?",
  ui_story_5089_50890100_52_dialog_content = "¡No! Eso no es lo que quise decir...",
  ui_story_5089_50890100_53_dialog_content = "Jeje, te atrapé. No hay necesidad de estar tan nervioso.",
  ui_story_5089_50890100_54_dialog_content = "Sin embargo, hay una razón por la que vine aquí hoy... Jiu.",
  ui_story_5089_50890100_55_dialog_content = "Si, su Alteza.",
  ui_story_5089_50890100_56_dialog_content = "¡Guau! ¿Tú también estás aquí, Jiu? ¡Totalmente no te vi allí!",
  ui_story_5089_50890100_57_dialog_content = "Su Alteza tiene asuntos importantes que discutir con el enviado. Permaneceré a su lado; el resto de ustedes están despedidos.",
  ui_story_5089_50890100_58_dialog_content = "Si, su Alteza.",
  ui_story_5089_50890100_59_dialog_content = "Haré un poco de té.",
  ui_story_5089_50890100_60_dialog_content = "E-Está bien, puedo—",
  ui_story_5089_50890100_61_dialog_content = "También he traído algo de comida ligera del palacio para su disfrute, así que por favor sírvanse. Si ya no me necesitan, entonces me retiraré ahora.",
  ui_story_5089_50890100_62_dialog_content = "¿Eh? ¿Quieres decir que no vas a comer con nosotros, Jiu?",
  ui_story_5089_50890100_63_dialog_content = "¿Ves, Jiu? PlayerName desea tu compañía, ahora por favor siéntate.",
  ui_story_5089_50890100_64_dialog_content = "... Eso sería una violación de etiqueta, Su Alteza. Si me necesita, estaré en la puerta.",
  ui_story_5089_50890100_65_dialog_content = "...",
  ui_story_5089_50890100_66_dialog_content = "... ¿De qué se trataba eso?",
  ui_story_5089_50890100_67_dialog_content = "Jiu no es muy conversador para empezar, pero la distancia entre nosotros se siente aún más fuerte de lo habitual hoy.",
  ui_story_5089_50890100_68_dialog_content = "Si acaso, preferiría que ella discutiera conmigo.",
  ui_story_5089_50890100_69_dialog_content = "?",
  ui_story_5089_50890100_70_dialog_content = "Pero no hablemos de eso por ahora. La razón por la que vine aquí hoy fue para despedirme de ti.",
  ui_story_5089_50890100_71_dialog_content = "¿Despedida...? ¿Vas a algún lugar?",
  ui_story_5089_50890100_72_dialog_content = "Mi tío, o más bien el actual rey del Reino de Ye, me ha convocado de vuelta al reino.",
  ui_story_5089_50890100_73_dialog_content = "¡Eso es genial! Dantang, ¡finalmente puedes irte a casa ahora!",
  ui_story_5089_50890100_74_dialog_content = "Pero, ¿es realmente tan simple? Después de todo, viniste al Reino Ji como... Um, como un estudiante de intercambio.",
  ui_story_5089_50890100_75_dialog_content = "No hay nada que ocultar. ¿Es realmente tan difícil decir la palabra \"rehén\"?",
  ui_story_5089_50890100_76_dialog_content = "Tus preocupaciones, sin embargo, son perfectamente válidas. Como rehén político, regresar a casa de la cual fui exiliado nunca será un asunto sencillo.",
  ui_story_5089_50890100_77_dialog_content = "En la superficie, parece que los reinos de Ji y Ye están negociando nuevos términos.",
  ui_story_5089_50890100_78_dialog_content = "¿Pero debajo de la superficie?",
  ui_story_5089_50890100_79_dialog_content = "Mi maestro ya me ha asegurado que el Reino de Ji no obstruirá mi viaje a casa.",
  ui_story_5089_50890100_80_dialog_content = "\"Los comerciantes, aunque impulsados por el beneficio, de ninguna manera son ingratos\". Esas fueron más o menos las palabras del rey.",
  ui_story_5089_50890100_81_dialog_content = "¿Qué significa eso incluso...?",
  ui_story_5089_50890100_82_dialog_content = "Después del tumulto del Festival de Primavera, se construyó un templo dedicado a la Doncella Dragón dentro del palacio, y se esculpió una estatua dorada en su honor.",
  ui_story_5089_50890100_83_dialog_content = "La familia Lin se está reagrupando y fortaleciéndose día tras día, y tú te conviertes en un ciudadano amado y honrado del Reino de Ji.",
  ui_story_5089_50890100_84_dialog_content = "Yo mismo no estuve exento de recibir las generosas recompensas del reino.",
  ui_story_5089_50890100_85_dialog_content = "Pero hay una persona que, a pesar de sus esfuerzos, aún no ha recibido ninguna recompensa.",
  ui_story_5089_50890100_86_dialog_content = "¿Te refieres a Xuan Ji, verdad? Últimamente no he podido contactar con ella en absoluto... ¿Sabes qué le pasa?",
  ui_story_5089_50890100_87_dialog_content = "Este es el segundo asunto que quería discutir contigo.",
  ui_story_5089_50890100_88_dialog_content = "Recibimos un decreto real del Reino de Ye. Por orden del rey, la Ministra Armilla debe ser arrestada y encarcelada tras la conclusión del Festival de Primavera.",
  ui_story_5089_50890100_89_dialog_content = "Se le acusa de traicionar al reino a través de su uso de maquinaria crítica.",
  ui_story_5089_50890100_90_dialog_content = "¡¿Qué?!",
  ui_story_5089_50890100_91_dialog_content = "Y por esta razón, he decidido tomar medidas inmediatas y regresar al Reino de Ye mañana.",
  ui_story_5089_50890100_92_dialog_content = "Solo desearía poder hacer el viaje aún más pronto. Por el bien de la Ministra Armilla, debo investigar estas acusaciones y descubrir la verdad.",
  ui_story_5089_50890100_93_dialog_content = "PlayerName—",
  ui_story_5089_50890100_94_dialog_content = "¡Yo también iré!",
  ui_story_5089_50890100_95_dialog_content = "Muy bien.",
  ui_story_5089_50890100_96_dialog_content = "Cuando dijiste que te ibas, ya quería pedirte que me llevaras contigo.",
  ui_story_5089_50890100_97_dialog_content = "No soy una deidad, y no vine a Longzhou solo para sentarme aquí y aceptar ofrendas, incluso la verdadera deidad no lo hizo.",
  ui_story_5089_50890100_98_dialog_content = "No hay nada que hacer para mí aquí en Haojin, así que ahora es un buen momento para irme.",
  ui_story_5089_50890100_99_dialog_content = "Y además, Xuan Ji también es mi amigo. No importa lo que digas, encontraré una manera de acompañarte. Espera, ¿qué acabas de decir?",
  ui_story_5089_50890100_100_dialog_content = "Muy bien.",
  ui_story_5089_50890100_101_dialog_content = "... Pensé que dirías que esto no tiene nada que ver conmigo, y me dirías que me quedara aquí.",
  ui_story_5089_50890100_102_dialog_content = "Nadie puede sobrevivir en aislamiento. Aquellos con muchos aliados prosperan, mientras que aquellos con pocos perecen.",
  ui_story_5089_50890100_103_dialog_content = "Tus enseñanzas aún resuenan en mis oídos. No me atrevo a olvidarlas.",
  ui_story_5089_50890100_104_dialog_content = "¿D-De verdad dije algo tan genial para ti?",
  ui_story_5089_50890100_105_dialog_content = "Jeje. Si me disculpas, debo regresar al palacio para hacer nuestras preparaciones finales. Hasta mañana, PlayerName.",
  ui_story_5089_50890100_106_dialog_content = "También debería empacar mis cosas...",
  ui_story_5089_50890100_107_dialog_content = "¿Se van tan pronto?",
  ui_story_5089_50890100_108_dialog_content = "¡Vaya! ¿Chen'ni? ¿Qué estás haciendo aquí de nuevo?!",
  ui_story_5089_50890100_109_dialog_content = "Oh, alrededor de cuando deseabas que pudiera usar mi poder para mantenerte oculto.",
  ui_story_5089_50890100_110_dialog_content = "¡Ent-Entonces has estado aquí todo este tiempo!",
  ui_story_5089_50890100_111_dialog_content = "... Lo que significa que también escuchaste todo eso, ¿verdad? Mañana me dirijo al Reino de Ye, así que no podré jugar contigo por un tiempo.",
  ui_story_5089_50890100_112_dialog_content = "¡Está bien! También vendré; si alguien se interpone en nuestro camino, ¡haré lo que mejor sé hacer!",
  ui_story_5089_50890100_113_dialog_content = "\"¡Golpea a los demonios y envíalos volando en todas direcciones!\"",
  ui_story_5089_50890100_114_dialog_content = "No, no, no. Eso no está en la Danza del Dragón, ¿por qué insistes en recordar eso?!",
  ui_story_5089_50890100_115_dialog_content = "¿Realmente importa? Después de todo, las leyendas sobre deidades y héroes siempre han cambiado a lo largo de los años.",
  ui_story_5089_50890100_116_dialog_content = "¡Y gracias a ti, he decidido tomar lecciones de artes marciales y estar a la altura de mi nueva leyenda!",
  ui_story_5089_50890100_117_dialog_content = "Bien, pero solo recuerda no andarte con rodeos. No estaré allí para controlarte, así que tendrás que hacerlo tú mismo.",
  ui_story_5089_50890100_118_dialog_content = "Entonces, ¿realmente no quieres que vaya contigo al Reino Ye? Porque si solo haces un deseo...",
  ui_story_5089_50890100_119_dialog_content = "Si lo hiciera, ¿seguirías siendo mi amigo?",
  ui_story_5089_50890100_120_dialog_content = "...",
  ui_story_5089_50890100_121_dialog_content = "Quiero seguir siendo amigos contigo mientras esté aquí, Chen'ni.",
  ui_story_5089_50890100_122_dialog_content = "Esto significa que nunca trataré a la Divinidad del Dragón Benevolente Todopoderoso como un recurso para ser explotado.",
  ui_story_5089_50890100_123_dialog_content = "<color=#e8d9bb>De repente, Chen'ni extiende la mano y arranca una hoja de un árbol fuera de la ventana, luego la entrega.</color>",
  ui_story_5089_50890100_124_dialog_content = "¿Qué es esto?",
  ui_story_5089_50890100_125_dialog_content = "Un regalo de despedida.",
  ui_story_5089_50890100_126_dialog_content = "Es una tradición Aurorian, ¿verdad?",
  ui_story_5089_50890100_127_dialog_content = "Estaré aquí esperando cuando vuelvas, PlayerName. ¡Nos divertiremos mucho cuando lo hagas!",
  ui_story_5089_50890100_128_dialog_content = "Estoy bastante seguro de que los Aurorians usan una rama de sauce para—Eh, ¿Chen'ni?",
  ui_story_5089_50890100_129_dialog_content = "Se fue sin decir otra palabra... Supongo que solo guardaré estos por ahora y los secaré más tarde.",
  ui_story_5089_50890100_130_dialog_content = "Este también es un buen momento para despedirse de los demás.",
  ui_story_5089_50890100_131_dialog_content = "<color=#e8d9bb>El día siguiente</color>",
  ui_story_5089_50890100_132_dialog_content = "Este es el lugar donde se supone que debo encontrarme con Dantang, ¿verdad?",
  ui_story_5089_50890100_133_dialog_content = "¡PlayerName! ¡PlayerName! ¡Finalmente estás aquí! ¡He estado esperando mucho tiempo, sabes!",
  ui_story_5089_50890100_134_dialog_content = "Príncipe Heredero... ¿Qué haces aquí? ¿Y qué es esa caja grande allá?",
  ui_story_5089_50890100_135_dialog_content = "Estoy aquí para despedirte, por supuesto. Incluso preparé algunos regalos de despedida.",
  ui_story_5089_50890100_136_dialog_content = "¡Cuidadosamente escogí a mano cada uno de estos tesoros invaluables solo para ti!",
  ui_story_5089_50890100_137_dialog_content = "¿Ves? Esta es la muñeca que solía llevar a todos lados cuando era niño. Y aquí está la linterna que hice yo mismo durante el festival.",
  ui_story_5089_50890100_138_dialog_content = "¡Oh, y mi libro de cuentos favorito! El maestro no me dejaba leerlo, así que tuve que pedirle a muchas personas que me ayudaran a comprarlo!",
  ui_story_5089_50890100_139_dialog_content = "Lo que me recuerda... Dantang y el Asesor Principal me contaron todo.",
  ui_story_5089_50890100_140_dialog_content = "Nunca pedí tu opinión antes de decidir que te convertirías en mi consorte. Fue un error de mi parte, y lamento haberte puesto en una posición tan difícil.",
  ui_story_5089_50890100_141_dialog_content = "Su Alteza...",
  ui_story_5089_50890100_142_dialog_content = "El barco está a punto de zarpar, PlayerName.",
  ui_story_5089_50890100_143_dialog_content = "Ah, está bien. De todos modos, ya que estos son todos muestras de tu sinceridad, estaré encantado de aceptarlos.",
  ui_story_5089_50890100_144_dialog_content = "¡Espléndido!",
  ui_story_5089_50890100_145_dialog_content = "¡Guardias, vayan a traer el resto de ello!",
  ui_story_5089_50890100_146_dialog_content = "¡E-Espera...! ¿Qué pasa con esas cajas?!",
  ui_story_5089_50890100_147_dialog_content = "Oh, solo unas pocas cosas menores para tu viaje. Solo tuve tiempo para preparar esta caja, así que dejé el resto con mis hombres.",
  ui_story_5089_50890100_148_dialog_content = "¡Pero mi sinceridad es totalmente real! ¡Por favor creeme!",
  ui_story_5089_50890100_149_dialog_content = "Ahora que he llegado a entender las formas del mundo, me doy cuenta de lo imprudente que era antes.",
  ui_story_5089_50890100_150_dialog_content = "¡Ahora veo que el cortejo siempre debe tener lugar antes del matrimonio!",
  ui_story_5089_50890100_151_dialog_content = "... ¿Lo siento?",
  ui_story_5089_50890100_152_dialog_content = "Levanta el ancla—",
  ui_story_5089_50890100_153_dialog_content = "Zarpar—",
  ui_story_5089_50890100_154_dialog_content = "<color=#e8d9bb>Mientras el barco se aleja lentamente, el príncipe saluda y grita desde la orilla.</color>",
  ui_story_5089_50890100_155_dialog_content = "¡Buen viaje! Y ten la seguridad de que continuaré cortejándote con regalos hasta que aceptes ser mi consorte.",
  ui_story_5089_50890100_156_dialog_content = "...",
  ui_story_5089_50890100_157_dialog_content = "¡Sabía que salir de Haojin era la decisión correcta!",
  ui_story_5089_50890100_158_dialog_content = "Incluso yo estoy sorprendido por el afecto del príncipe hacia ti, PlayerName. Nunca lo he visto perseguir algo con tal determinación unidireccional.",
  ui_story_5089_50890100_159_dialog_content = "Pero no puedo aceptar todos estos regalos, incluso si solo son un montón de juguetes...",
  ui_story_5089_50890100_160_dialog_content = "Si realmente no puedes aceptarlos, siempre puedo organizar para que sean devueltos una vez que lleguemos al Reino Ye.",
  ui_story_5089_50890100_161_dialog_content = "Ese tendrá que ser el plan. Salvar a Xuan Ji tiene precedencia sobre todo lo demás.",
  ui_story_5089_50890100_162_dialog_content = "Correcto. Finalmente es hora de irse... No, espera.",
  ui_story_5089_50890100_163_dialog_content = "Finalmente es hora de volver al Reino de Ye.",
  ui_story_5089_50890201_1_dialog_content = "Su Alteza, PlayerName, por favor prepárese para desembarcar.",
  ui_story_5089_50890201_2_dialog_content = "Pero acabamos de cruzar la frontera entre los dos reinos, ¿no es así? ¿Realmente estamos allí?",
  ui_story_5089_50890201_3_dialog_content = "Aún no, no. A diferencia del Reino de Ji y sus numerosos canales, el Reino de Ye está situado en una vasta llanura central. Los barcos solo pueden llevarnos hasta aquí.",
  ui_story_5089_50890201_4_dialog_content = "Oye, recuerdo este puerto... Este es Tongli Town, ¿no es así?",
  ui_story_5089_50890201_5_dialog_content = "Sí, Su Alteza. Ya he reservado la posada para la noche. Descansaremos allí y continuaremos nuestro viaje mañana.",
  ui_story_5089_50890201_6_dialog_content = "Una vez que los carruajes estén asegurados, viajaremos directamente a la capital por tierra.",
  ui_story_5089_50890201_7_dialog_content = "¡Eso es impresionante, Jiu! ¿Cómo pudiste hacer todo eso mientras aún estamos en el agua?",
  ui_story_5089_50890201_8_dialog_content = "El barco viene equipado con un pequeño bote de remos. Lo usé para llegar a la orilla y organizar todo con anticipación.",
  ui_story_5089_50890201_9_dialog_content = "Dada la naturaleza repentina e inesperada de nuestro viaje, nadie ha sido notificado para recibirnos en este punto.",
  ui_story_5089_50890201_10_dialog_content = "Ya es suficientemente delictivo que Su Alteza deba alojarse en una posada tan humilde, así que al menos debemos garantizar la seguridad de los alrededores.",
  ui_story_5089_50890201_11_dialog_content = "Dijiste que nos estamos acercando, pero no veo ninguna señal de tierra...",
  ui_story_5089_50890201_12_dialog_content = "Remaste todo ese camino tú solo... No es de extrañar que estés completamente empapado.",
  ui_story_5089_50890201_13_dialog_content = "Deberías cambiarte a algo seco antes de que te resfríes.",
  ui_story_5089_50890201_14_dialog_content = "Aprecio tu preocupación, pero no soy tan frágil. Una vida de entrenamiento en artes marciales me mantiene en relativamente buena salud.",
  ui_story_5089_50890201_15_dialog_content = "Desembarqué para explorar el área y asegurar su seguridad, pero dejar a Su Alteza por mi propio asunto sería una negligencia de deber.",
  ui_story_5089_50890201_16_dialog_content = "Por otra parte, es impropio de mi parte presentar tal espectáculo alrededor de Su Alteza. Perdóneme, me mantendré fuera de la vista.",
  ui_story_5089_50890201_17_dialog_content = "Espera, eso no es lo que quise decir—",
  ui_story_5089_50890201_18_dialog_content = "Está bien, PlayerName. Solo déjala ir.",
  ui_story_5089_50890201_19_dialog_content = "Este es el tiempo más largo que la he visto mostrarse en bastante tiempo.",
  ui_story_5089_50890201_20_dialog_content = "Incluso en el palacio, cuando estoy ocupado revisando cartas y documentos, a menudo rellena mi té y refrigerios sin que me dé cuenta.",
  ui_story_5089_50890201_21_dialog_content = "O cuando regreso de reuniones con otras personas, siempre encuentro mi habitación perfectamente ordenada y limpia.",
  ui_story_5089_50890201_22_dialog_content = "Ha estado haciendo incluso más de lo habitual sin que nadie la note en absoluto.",
  ui_story_5089_50890201_23_dialog_content = "(¿L-Los elfos zapateros?)",
  ui_story_5089_50890201_24_dialog_content = "Entonces, ¿qué pasó exactamente entre ustedes dos?",
  ui_story_5089_50890201_25_dialog_content = "PlayerName, ¿todavía recuerdas al grupo de personas responsables del caos en Haojin hace algún tiempo?",
  ui_story_5089_50890201_26_dialog_content = "¿Te refieres a los tipos que se llamaban a sí mismos los Fate Riders?",
  ui_story_5089_50890201_27_dialog_content = "Sí. Con la ayuda de la Divinidad del Dragón Benevolente Todopoderoso, la Oficina de Inspección pudo detener a un gran número de los Jinetes del Destino escondidos dentro del Reino Ji.",
  ui_story_5089_50890201_28_dialog_content = "Entre ellos había docenas de personas que ocupaban cargos oficiales dentro de la corte del reino.",
  ui_story_5089_50890201_29_dialog_content = "Aunque en su mayoría eran funcionarios de nivel inferior, con el tiempo, lograron establecer una poderosa red entre ellos...",
  ui_story_5089_50890201_30_dialog_content = "Suficientemente poderosos para influir enormemente en la corte, e incluso en el mismo rey. De hecho, se podría decir que estas personas habían obtenido el poder para sacudir un reino entero hasta su núcleo.",
  ui_story_5089_50890201_31_dialog_content = "Afortunadamente, logramos capturar a todos y cada uno de ellos, y ahora el rey y sus asesores están más vigilantes que nunca. Estos traidores no podrán actuar con impunidad nunca más.",
  ui_story_5089_50890201_32_dialog_content = "Pero incluso así, PlayerName... ¿Realmente crees que su red estaba solo restringida al Reino Ji?",
  ui_story_5089_50890201_33_dialog_content = "Te refieres a...",
  ui_story_5089_50890201_34_dialog_content = "En la noche del tumulto en Haojin, intentaba buscarte, pero fui interceptado tan pronto como salí de las puertas del palacio.",
  ui_story_5089_50890201_35_dialog_content = "¡Esta es la primera vez que lo escucho! No te lastimaron, ¿verdad? ¿Por qué no le dijiste a nadie?!",
  ui_story_5089_50890201_36_dialog_content = "Porque los que me interceptaron eran espías del Reino Ye.",
  ui_story_5089_50890201_37_dialog_content = "¡¿Qué?!",
  ui_story_5089_50890201_38_dialog_content = "El actual emperador del Imperio Zhao es joven, y los ocho reyes tienen cada uno sus propias intenciones.",
  ui_story_5089_50890201_39_dialog_content = "Aunque el espionaje entre ellos es bastante común, no es algo que se pueda discutir abiertamente.",
  ui_story_5089_50890201_40_dialog_content = "Y aunque los espías del Reino Ye me respetaban como su princesa, aún solo responden a un hombre: mi tío.",
  ui_story_5089_50890201_41_dialog_content = "Así que me bloquearon, y así ayudaron a los Jinetes del Destino en sus planes...",
  ui_story_5089_50890201_42_dialog_content = "¿Es el Rey de Ye realmente el único que puede controlarlos?",
  ui_story_5089_50890201_43_dialog_content = "Mi tío no era muy conocido antes de tomar el trono y ha sido un gobernante ejemplar. Nombra a las personas en función de sus talentos, se preocupa profundamente por sus súbditos y se comporta con el porte de un verdadero rey.",
  ui_story_5089_50890201_44_dialog_content = "Lo que me lleva a suponer que esto es obra de los Jinetes del Destino!",
  ui_story_5089_50890201_45_dialog_content = "Ya veo. No es de extrañar que tengas tanta prisa por volver.",
  ui_story_5089_50890201_46_dialog_content = "Al evitar tanto como sea posible a los Jinetes del Destino del Reino Ye, eres libre para moverte e investigar asuntos, que luego puedes informar al rey.",
  ui_story_5089_50890201_47_dialog_content = "Y entonces, lógicamente, podríamos rescatar a Xuan Ji, quien fue encarcelado por ayudarnos!",
  ui_story_5089_50890201_48_dialog_content = "Me conoces demasiado bien, PlayerName.",
  ui_story_5089_50890201_49_dialog_content = "Pero, ¿qué tiene todo esto que ver con Jiu?",
  ui_story_5089_50890201_50_dialog_content = "Pensé que lo sabías.",
  ui_story_5089_50890201_51_dialog_content = "Jiu no es otro que el líder de los espías del Reino Ye.",
  ui_story_5089_50890201_52_dialog_content = "¿¡Qué?! ¿No es ella tu guardia personal?",
  ui_story_5089_50890201_53_dialog_content = "Jiu originalmente era una servidora de confianza bajo el mando directo de mi tío. Se le asignó a mí como guardia justo antes de que me enviaran al Reino de Ji como rehén.",
  ui_story_5089_50890201_54_dialog_content = "Mi tío le ha mostrado un gran favor. Ella nunca desobedecería ninguna orden que viniera de él.",
  ui_story_5089_50890201_55_dialog_content = "Y porque mi tío le ordenó protegerme, ella está dispuesta a arriesgar su vida para hacerlo.",
  ui_story_5089_50890201_56_dialog_content = "Por preocupación por mi seguridad, él le ha pedido que le escriba todos los meses con actualizaciones. Independientemente de la temporada o circunstancia, ella nunca ha perdido una fecha límite.",
  ui_story_5089_50890201_57_dialog_content = "Eso es...",
  ui_story_5089_50890201_58_dialog_content = "Entiendo la preocupación de mi tío, pero desde otra perspectiva, también podría considerarse vigilancia.",
  ui_story_5089_50890201_59_dialog_content = "Espera, ¿eso significa que los Fate Riders aún están rastreando nuestras acciones?! ¿Es Jiu...",
  ui_story_5089_50890201_60_dialog_content = "Puedes dejar tus dudas a un lado.",
  ui_story_5089_50890201_61_dialog_content = "Después de todo, lo has visto por ti mismo, ¿no es así? Jiu se niega a mentirme sobre cualquier cosa a mí o a mi tío.",
  ui_story_5089_50890201_62_dialog_content = "Ella nunca desobedecería sus órdenes, pero comprende completamente la importancia de nuestro viaje. Por esa razón, solo puede mirar hacia otro lado, permanecer en silencio y no hacer preguntas.",
  ui_story_5089_50890201_63_dialog_content = "Mientras cumpla con sus deberes como guardia y se mantenga alejada de mí, no tendrá que informar nada que no sepa.",
  ui_story_5089_50890201_64_dialog_content = "Ella ya está haciendo todo lo posible por nosotros.",
  ui_story_5089_50890201_65_dialog_content = "Sin embargo, no puedo negar mi alegría después de ver a mi obstinado guardia vacilar ligeramente.",
  ui_story_5089_50890201_66_dialog_content = "Al menos, los cinco años que pasamos juntos en el Reino de Ji no fueron completamente desperdiciados.",
  ui_story_5089_50890201_67_dialog_content = "Dantang.",
  ui_story_5089_50890201_68_dialog_content = "¿Sí? Déjame adivinar: no crees que debería disfrutar viéndola luchar, ¿verdad?",
  ui_story_5089_50890201_69_dialog_content = "Lo has tenido realmente difícil en el Reino Ji todos estos años, ¿no es así?",
  ui_story_5089_50890201_70_dialog_content = "¿Eh...?",
  ui_story_5089_50890201_71_dialog_content = "Er, bueno... Quiero decir...",
  ui_story_5089_50890201_72_dialog_content = "Sé que el Rey de Ji, el Príncipe Heredero y el Asesor Principal son todas buenas personas, pero no son tu familia.",
  ui_story_5089_50890201_73_dialog_content = "Suspiro...",
  ui_story_5089_50890201_74_dialog_content = "¿Q-Qué es? ¿Dije algo malo?",
  ui_story_5089_50890201_75_dialog_content = "Para nada. De hecho, si fueras un comandante de ejército, algo me dice que serías excelente en ataques sorpresa.",
  ui_story_5089_50890201_76_dialog_content = "¿Eh? ¿Por qué de repente estamos hablando de eso?",
  ui_story_5089_50890201_77_dialog_content = "Si me disculpas, necesito retocar mi maquillaje antes de desembarcar.",
  ui_story_5089_50890201_78_dialog_content = "Eh, está bien...",
  ui_story_5089_50890201_79_dialog_content = "Graznido...",
  ui_story_5089_50890201_80_dialog_content = "Graznido...",
  ui_story_5089_50890201_81_dialog_content = "¡La madera podrida nunca puede ser tallada!",
  ui_story_5089_50890201_82_dialog_content = "¡Y un árbol de hierro nunca florecerá!",
  ui_story_5089_50890201_83_dialog_content = "Oye, ¿a quién llamas \"madera podrida\"?! Espera... ¿Graznido? ¿Farfullar? ¿Qué están haciendo ustedes dos aquí?",
  ui_story_5089_50890201_84_dialog_content = "¡Entrégame algunos melones dorados y guiaré tu camino!",
  ui_story_5089_50890201_85_dialog_content = "¡Ofrece algunas dátiles de plata y disiparé todas tus dudas!",
  ui_story_5089_50890201_86_dialog_content = "Lamento decepcionar, pero no tengo ninguna de esas cosas.",
  ui_story_5089_50890201_87_dialog_content = "Si tienes hambre, solo pide comida a tu maestro. Él también debería estar por aquí, ¿verdad? Estoy bien consciente de su tendencia a aparecer de la nada.",
  ui_story_5089_50890201_88_dialog_content = "¡Tianxian! ¿Tú también estás aquí, verdad?",
  ui_story_5089_50890201_89_dialog_content = "¡Ya no tenemos un maestro!",
  ui_story_5089_50890201_90_dialog_content = "¡Las aguas se lo han llevado!",
  ui_story_5089_50890201_91_dialog_content = "Por ahí!",
  ui_story_5089_50890201_92_dialog_content = "¡¿Qué...?!",
  ui_story_5089_50890201_93_dialog_content = "Glub, glub... Ayuda... Yo... No puedo nadar... Glub, glub, glub...",
  ui_story_5089_50890201_94_dialog_content = "¿Qué está haciendo en el agua?! Ah, esto no es bueno...",
  ui_story_5089_50890201_95_dialog_content = "¡Tengo que salvarlo!",
  ui_story_5089_50890202_1_dialog_content = "¡Achuu!",
  ui_story_5089_50890202_2_dialog_content = "Gracias a Dios, vivo para ver otro día.",
  ui_story_5089_50890202_3_dialog_content = "¿Qué diablos estabas haciendo, ahogándote en un lugar como este? ¿No me digas que recibiste otra invitación al Palacio del Dragón?!",
  ui_story_5089_50890202_4_dialog_content = "No... En realidad es mucho menos complicado que eso.",
  ui_story_5089_50890202_5_dialog_content = "Me había cansado de vagar por el Reino Ji, así que pensé en visitar nuevas tierras. Pero como sabes, a menudo me quedo corto de fondos.",
  ui_story_5089_50890202_6_dialog_content = "Incapaz de pagar el pasaje en un barco más grande, no tuve más opción que viajar con una caravana más pequeña de comerciantes. Después de innumerables paradas en el camino, finalmente llegamos al Reino de Ye.",
  ui_story_5089_50890202_8_dialog_content = "Qué vista tan rara, dado que la corte organiza una ceremonia anual para desterrar a estos monstruos de sus tierras. Las tierras fronterizas entre los reinos de Ji y Ye ni siquiera están cerca del océano.",
  ui_story_5089_50890202_10_dialog_content = "Y así comenzaron a perseguirme sin pensarlo dos veces. Mientras corría por mi vida, perdí de vista mi entorno y finalmente me sumergí en el mar.",
  ui_story_5089_50890202_11_dialog_content = "Pero gracias a todos ustedes, mi vida se salva una vez más. Si tan solo tuviera algo de valor para ofrecer como muestra de mi gratitud...",
  ui_story_5089_50890202_12_dialog_content = "¡Parece que no tengo más opción que pagarte con mi cuerpo!",
  ui_story_5089_50890202_13_dialog_content = "¡N-No hay necesidad de eso!",
  ui_story_5089_50890202_14_dialog_content = "¿No tienes algo mejor que hacer ahora mismo?!",
  ui_story_5089_50890202_15_dialog_content = "Dime, ¿todavía recuerdas mi nombre?",
  ui_story_5089_50890202_16_dialog_content = "Uh, ¿sí? Es Tianxian, ¿no es así?",
  ui_story_5089_50890202_17_dialog_content = "¡Correcto! Y si lo desglosaras a su interpretación más literal, significa \"el holgazán más grande del mundo\"!",
  ui_story_5089_50890202_18_dialog_content = "Así que por favor, no te apresures a rechazarme. Antes de partir, adiviné mi propia fortuna. Aunque presagiaba una gran desgracia en mi viaje, también insinuaba la llegada de un benefactor amable y rico.",
  ui_story_5089_50890202_19_dialog_content = "En cuanto a quién podría ser eso... Ven, extiende tus manos para mí.",
  ui_story_5089_50890202_20_dialog_content = "¿Así?",
  ui_story_5089_50890202_21_dialog_content = "<color=#e8d9bb>¡Estrépito!</color>",
  ui_story_5089_50890202_22_dialog_content = "Eh... ¿Por qué tiraste todos tus palos de adivinación en mis manos?",
  ui_story_5089_50890202_23_dialog_content = "Oh querido, los hexagramas del Dragón Yin y la Rata Yin. Esto no augura nada bueno para nosotros.",
  ui_story_5089_50890202_24_dialog_content = "El dragón ascendente y la rata saltarina son normalmente signos auspiciosos, pero en este caso es exactamente lo contrario. Juntos, significan que una terrible amenaza se oculta ante nosotros, y que los villanos están tramando algo nefasto mientras hablamos. En resumen, nos enfrentamos a un desastre inminente.",
  ui_story_5089_50890202_25_dialog_content = "Bajo circunstancias normales, estaría corriendo por mi vida ahora mismo. Sin embargo, no podía dejar a mis salvadores solos para enfrentar este desastre.",
  ui_story_5089_50890202_26_dialog_content = "Ah, bueno, no se puede evitar. Permíteme unirme a ti en tus viajes para que podamos enfrentar juntos esta terrible amenaza.",
  ui_story_5089_50890202_27_dialog_content = "Siempre sospecho de cualquier cosa que dices, pero esta situación completa parece especialmente sospechosa.",
  ui_story_5089_50890202_28_dialog_content = "¿Cómo es eso? Tú fuiste el que me rescató de una tumba de agua, ¿no es así?",
  ui_story_5089_50890202_29_dialog_content = "Sí, pero tu fortuna decía que un \"benefactor rico\" te rescataría.",
  ui_story_5089_50890202_30_dialog_content = "No es por presumir ni nada, ¡pero nunca he sido rico ni un solo día en mi vida!",
  ui_story_5089_50890202_31_dialog_content = "Hmm, qué extraño. Mis adivinaciones indicaban que ya serías lo suficientemente rico como para rivalizar con una nación entera.",
  ui_story_5089_50890202_32_dialog_content = "Sí, quizás en mis sueños...",
  ui_story_5089_50890202_33_dialog_content = "El barco ya ha atracado, PlayerName. Un barquero vendrá en breve para llevar tus pertenencias, así que siéntete libre de desembarcar en cualquier momento.",
  ui_story_5089_50890202_34_dialog_content = "¿Un barquero? ¡Eso no servirá en absoluto! Como parte de la devolución de la deuda de mi vida contigo, permíteme llevar esta caja—",
  ui_story_5089_50890202_35_dialog_content = "¡Urgh! ¿Por qué es tan pesado...?!",
  ui_story_5089_50890202_36_dialog_content = "<color=#828282>¡Golpe!</color>",
  ui_story_5089_50890202_37_dialog_content = "<color=#e8d9bb>La caja cae con un estruendo sordo, golpeando su tapa. Para sorpresa de todos, la caja está llena hasta el borde con deslumbrantes tesoros dorados.</color>",
  ui_story_5089_50890202_38_dialog_content = "PlayerName, es hora de desembarcar—",
  ui_story_5089_50890202_39_dialog_content = "...",
  ui_story_5089_50890202_40_dialog_content = "...",
  ui_story_5089_50890202_41_dialog_content = "...",
  ui_story_5089_50890202_42_dialog_content = "N-Nada de esto está dañado, ¿espero? Oh querido, oh cielos arriba... ¡Nunca podría reemplazar nada de esto si lo rompiera!",
  ui_story_5089_50890202_43_dialog_content = "Eh, chicos? Estoy bastante seguro de que algo anda mal con mis ojos.",
  ui_story_5089_50890202_44_dialog_content = "La caja que me dio el príncipe... ¿Por qué parece que está llena de oro? Jajaja...",
  ui_story_5089_50890202_45_dialog_content = "... Jiu.",
  ui_story_5089_50890202_46_dialog_content = "<color=#e8d9bb>Jiu aparece de repente al llamado de Dantang. Sin decir otra palabra, inspecciona cada una de las cajas que les dio el príncipe heredero.</color>",
  ui_story_5089_50890202_47_dialog_content = "Mi inspección está completa, Lady Dantang. Aparte de dos cajas llenas de juguetes y algunos casos de magatama y piedras preciosas, todo lo demás es oro.",
  ui_story_5089_50890301_1_dialog_content = "Hemos estado caminando durante siglos... ¿Cómo es que aún no hemos llegado? ¿Está realmente tan lejos la posada del muelle...?",
  ui_story_5089_50890301_2_dialog_content = "¿No eres tú el que insistió en tomar caminos secundarios por miedo a ser robado? No tienes a nadie a quien culpar sino a ti mismo por invitar al dios de la riqueza a tu casa, amigo mío.",
  ui_story_5089_50890301_3_dialog_content = "¡No te equivoques! ¡Solo tengo miedo de ser robado porque tengo la obligación de devolver todas estas cosas! ¡Cualquiera reaccionaría de la misma manera!",
  ui_story_5089_50890301_4_dialog_content = "El príncipe incluso dijo que estas cajas eran solo \"cosas menores\" para nuestro viaje...",
  ui_story_5089_50890301_5_dialog_content = "Para el príncipe heredero del Reino de Ji, el oro y la plata son solo objetos triviales.",
  ui_story_5089_50890301_6_dialog_content = "Pero para cualquier otra persona... Tú podrías comprar fácilmente una ciudad entera en el Reino de Ye con tanto oro, PlayerName.",
  ui_story_5089_50890301_7_dialog_content = "Pero no hay necesidad de preocuparse. Con Jiu a nuestro lado, ningún bandido ordinario podría siquiera esperar acercarse a nosotros.",
  ui_story_5089_50890301_8_dialog_content = "Casi llegamos a la posada. Está justo al final de esta calle.",
  ui_story_5089_50890301_9_dialog_content = "Por fin, un descanso muy necesario. Esta parte del viaje ha sido tan estresante... ¿Eh? ¿Hay algo mal, Dantang?",
  ui_story_5089_50890301_10_dialog_content = "No, es solo que... Recuerdo haber pasado por aquí en mi camino al Reino de Ji hace años.",
  ui_story_5089_50890301_11_dialog_content = "Tongli Town... Un asentamiento costero que limita con una de las regiones productoras de grano más grandes del Reino Ye. Puede que no se compare con una ciudad mayor, pero ciertamente estaba bulliciosa en ese momento.",
  ui_story_5089_50890301_12_dialog_content = "Sin embargo, de alguna manera, se siente mucho más desolado esta vez.",
  ui_story_5089_50890301_13_dialog_content = "Entonces parece que no has estado aquí por muchos años, mujer joven.",
  ui_story_5089_50890301_14_dialog_content = "Por favor, ilumíname, amable señor.",
  ui_story_5089_50890301_15_dialog_content = "¿Iluminarte, eh? ¿Qué puedo enseñarte que todos no sepan ya?",
  ui_story_5089_50890301_16_dialog_content = "En los últimos años, la ciudad ha construido muchos talleres grandes, ofreciendo generosos salarios mensuales y atrayendo a todos los jóvenes para trabajar en ellos.",
  ui_story_5089_50890301_17_dialog_content = "Si no fuera tan viejo y decrépito, me encantaría trabajar en un lugar donde no esté a merced de los elementos.",
  ui_story_5089_50890301_18_dialog_content = "Entiendo. May ¿Puedo preguntar cuánto cuesta este arroz, amable señor?",
  ui_story_5089_50890301_19_dialog_content = "¿Estás buscando comprar algo? Debería advertirte, el precio de los granos ha estado subiendo durante los últimos dos meses, y hoy está un poco más alto. Por esta cantidad de arroz—",
  ui_story_5089_50890301_20_dialog_content = "... Ya veo. Gracias.",
  ui_story_5089_50890301_21_dialog_content = "¿Hay algo malo con esa bolsa de arroz?",
  ui_story_5089_50890301_22_dialog_content = "Cuando estábamos de vuelta en Haojin, pregunté sobre el precio del arroz, y parecía coincidir con el precio aquí. Eso no debería ser un problema, ¿verdad?",
  ui_story_5089_50890301_23_dialog_content = "El costo del arroz en un pueblo pequeño como este es sorprendentemente similar al de Haojin, una de las ciudades más ricas del Imperio Zhao.",
  ui_story_5089_50890301_24_dialog_content = "Decir que no es un problema no podría estar más lejos de la verdad. ¿Pero cómo podría ser esto...?",
  ui_story_5089_50890301_25_dialog_content = "<color=#e8d9bb>¡Wham!</color>",
  ui_story_5089_50890301_26_dialog_content = "¡Oh, lo siento por eso! No fue mi intención chocar contigo... ¿Eh? ¿Qué es eso en tus brazos...?",
  ui_story_5089_50890301_27_dialog_content = "¡...!",
  ui_story_5089_50890301_28_dialog_content = "¡S-Señor! ¡Tienes que detener a ese niño!",
  ui_story_5089_50890301_29_dialog_content = "¡Se está escapando con tu equipaje!",
  ui_story_5089_50890301_30_dialog_content = "!",
  ui_story_5089_50890301_31_dialog_content = "—!",
  ui_story_5089_50890301_32_dialog_content = "Deja de resistirte.",
  ui_story_5089_50890301_33_dialog_content = "¡Hrngh! ¡Déjame ir! Déjame... ¡IR!",
  ui_story_5089_50890301_34_dialog_content = "<color=#e8d9bb>El niñito muerde ferozmente la mano de Jiu, pero esta última permanece completamente impasible, su expresión es dura e insensible.</color>",
  ui_story_5089_50890301_35_dialog_content = "Devuelve lo que has robado.",
  ui_story_5089_50890301_36_dialog_content = "<color=#e8d9bb>Con los ojos rojos e hinchados, el chico muerde aún más fuerte.</color>",
  ui_story_5089_50890301_37_dialog_content = "Jiu!",
  ui_story_5089_50890301_38_dialog_content = "<color=#e8d9bb>En ese momentáneo lapsus de concentración, el chico se escapa del agarre de Jiu como un pez.</color>",
  ui_story_5089_50890301_39_dialog_content = "¡Pffft!",
  ui_story_5089_50890301_40_dialog_content = "¡Oye, tú—",
  ui_story_5089_50890301_41_dialog_content = "¡Ayuda! ¡Sálvame! ¡Esas personas están tratando de secuestrarme!",
  ui_story_5089_50890301_42_dialog_content = "¿Qué? ¿Quién es lo suficientemente estúpido para intentar secuestrar a un niño a plena luz del día?!",
  ui_story_5089_50890301_43_dialog_content = "¡Esos tipos de allí, los que llevan esa ropa extraña! ¡Sabía que eran problemas en cuanto los vi!",
  ui_story_5089_50890301_44_dialog_content = "¡Llama a los guardias del pueblo! ¡Arrestar a esos criminales!",
  ui_story_5089_50890301_45_dialog_content = "¿Q-Qué es todo esto ahora? ¡Por favor no seas precipitado! Te aseguro que todos estamos del mismo lado, así que hablemos de las cosas con calma y racionalidad!",
  ui_story_5089_50890301_46_dialog_content = "¡Nadie está de tu lado, delincuente!",
  ui_story_5089_50890301_47_dialog_content = "¡Argh, hay demasiada gente aquí! ¡Ese niño se está escapando!",
  ui_story_5089_50890301_48_dialog_content = "¡Aléjate de la princesa!",
  ui_story_5089_50890301_49_dialog_content = "Está bien, Jiu. Son solo ciudadanos ordinarios preocupados por su propia seguridad.",
  ui_story_5089_50890301_50_dialog_content = "Pero que si...",
  ui_story_5089_50890301_51_dialog_content = "Eres más rápido sin mí, así que toma PlayerName y ve a buscar a ese niño. Yo me encargaré del resto de los aldeanos.",
  ui_story_5089_50890301_52_dialog_content = "No puedo hacer eso, Su Alteza. Mis órdenes son protegerle.",
  ui_story_5089_50890301_53_dialog_content = "Entonces considéralo una orden de mi parte. Ahora ve.",
  ui_story_5089_50890301_54_dialog_content = "... Sí, su Alteza.",
  ui_story_5089_50890301_55_dialog_content = "Por favor, quédate cerca de mí, PlayerName.",
  ui_story_5089_50890301_56_dialog_content = "¿Cómo logró ese niño escaparse tan rápido?",
  ui_story_5089_50890301_57_dialog_content = "Suspiro... Tenía la sensación de que algo así sucedería tan pronto como vi ese montón de oro.",
  ui_story_5089_50890301_58_dialog_content = "Aun así, me sorprende que la persona que me robó fuera solo un niño.",
  ui_story_5089_50890301_59_dialog_content = "Estaba vestido con trapos, eso sí. Estoy seguro de que también ha tenido que lidiar con su parte de dificultades.",
  ui_story_5089_50890301_60_dialog_content = "...",
  ui_story_5089_50890301_61_dialog_content = "No vas a hablar conmigo a menos que sea absolutamente necesario, ¿verdad?",
  ui_story_5089_50890301_62_dialog_content = "...",
  ui_story_5089_50890301_63_dialog_content = "Sé que solo soy un extraño, y todavía tengo mucho que aprender sobre Longzhou. Sería arrogante de mi parte decir que entiendo tu situación.",
  ui_story_5089_50890301_64_dialog_content = "Pero he conocido a muchas personas diferentes a lo largo de mis viajes.",
  ui_story_5089_50890301_65_dialog_content = "Algunos de ellos sacrificaron voluntariamente todo por sus creencias, y se convirtieron en faros para el amanecer venidero.",
  ui_story_5089_50890301_66_dialog_content = "Algunas personas estaban dispuestas a destruir todo por sus sueños, incluso si eso significaba caer en el abismo más oscuro.",
  ui_story_5089_50890301_67_dialog_content = "No tengo derecho a juzgar sus aciertos o errores, y definitivamente no estoy calificado para definir la vida de otras personas en pocas palabras. Supongo que eso es lo que estoy tratando de decir.",
  ui_story_5089_50890301_68_dialog_content = "Es que solo hay una forma de no lograr nada, y es no haciendo nada en absoluto.",
  ui_story_5089_50890301_69_dialog_content = "Soy un guerrero bajo el mando del Rey de Ye, y un guardia encargado de la protección de la Princesa Dantang.",
  ui_story_5089_50890301_70_dialog_content = "Mi deber es obedecer las órdenes y cumplir con mis responsabilidades sin dudarlo.",
  ui_story_5089_50890301_71_dialog_content = "No necesito cambiar nada.",
  ui_story_5089_50890301_72_dialog_content = "Entonces permíteme preguntarte algo. ¿Qué harías si el rey y Dantang te dieran órdenes contradictorias?",
  ui_story_5089_50890301_73_dialog_content = "Tanto el rey como la princesa son gobernantes benevolentes que llevan la difícil situación de sus súbditos en sus corazones. Se dedican completamente a los intereses del Reino de Ye.",
  ui_story_5089_50890301_74_dialog_content = "Esa no es una respuesta muy convincente, ¿sabes?",
  ui_story_5089_50890301_75_dialog_content = "Yo...",
  ui_story_5089_50890301_76_dialog_content = "¿Todavía no hay señales de ese niño, huh? Quizás debería intentar sentir su ubicación.",
  ui_story_5089_50890301_77_dialog_content = "¡Escaneo psíquico!",
  ui_story_5089_50890301_78_dialog_content = "¡Ahí! Está en un callejón al sur de nosotros—¿Eh?",
  ui_story_5089_50890301_79_dialog_content = "Pffffft—",
  ui_story_5089_50890301_80_dialog_content = "Ese niño...",
  ui_story_5089_50890301_81_dialog_content = "(¿Eh? Creo que acabo de tropezar con algo...)",
  ui_story_5089_50890301_82_dialog_content = "<color=#e8d9bb>¡Estrépito, estrépito!</color>",
  ui_story_5089_50890301_83_dialog_content = "<color=#e8d9bb>Un manojo de postes de bambú cae estrepitosamente.</color>",
  ui_story_5089_50890301_84_dialog_content = "¿¡Una trampa?!",
  ui_story_5089_50890301_85_dialog_content = "(¡T-Tengo que salir del camino!)",
  ui_story_5089_50890301_86_dialog_content = "<color=#e8d9bb>Como si anticipara el próximo movimiento del intruso, los ladrillos de piedra justo debajo de la trampa se derrumbaron en un agujero bien oculto.</color>",
  ui_story_5089_50890301_87_dialog_content = "<color=#e8d9bb>¡Sploosh!</color>",
  ui_story_5089_50890301_88_dialog_content = "<color=#e8d9bb>Un balde de madera lleno de agua cae del cielo—</color>",
  ui_story_5089_50890301_89_dialog_content = "¡Ahhhh!",
  ui_story_5089_50890301_90_dialog_content = "Cuidado.",
  ui_story_5089_50890301_91_dialog_content = "<color=#e8d9bb>Jiu se lanza hacia adelante como una ráfaga de viento invisible.</color>",
  ui_story_5089_50890301_92_dialog_content = "<color=#e8d9bb>Ágilmente, golpea el cubo con la punta de su espada sin desenvainar, desviándolo de su objetivo previsto.</color>",
  ui_story_5089_50890301_93_dialog_content = "<color=#e8d9bb>Con un ligero golpe, aterriza con gracia a los pies del chico sin derramar ni una sola gota de agua.</color>",
  ui_story_5089_50890301_94_dialog_content = "<color=#e8d9bb>Al mismo tiempo, los postes de bambú en cascada flotan en el aire por un breve momento antes de dividirse en innumerables pedazos y caer sin causar daño al suelo..</color>",
  ui_story_5089_50890301_95_dialog_content = "<color=#e8d9bb>En algún momento, habían sido cortados limpiamente por la mitad.</color>",
  ui_story_5089_50890301_96_dialog_content = "E-Eso... fue increíble.",
  ui_story_5089_50890301_97_dialog_content = "¿Cómo ella...",
  ui_story_5089_50890301_98_dialog_content = "Devuelve lo que has robado. No lo diré de nuevo.",
  ui_story_5089_50890301_99_dialog_content = "... ¡No sé de qué estás hablando!",
  ui_story_5089_50890301_100_dialog_content = "Detener—",
  ui_story_5089_50890301_101_dialog_content = "Espera, Jiu.",
  ui_story_5089_50890301_102_dialog_content = "Pasó por muchas dificultades para establecer estas trampas, e incluso se quedó aquí cuando no tenía que hacerlo. Probablemente haya una buena razón para eso.",
  ui_story_5089_50890301_103_dialog_content = "Los artículos robados deben estar escondidos en la casa de al lado.",
  ui_story_5089_50890301_104_dialog_content = "!",
  ui_story_5089_50890301_105_dialog_content = "¡Oye, basta ya! Soy yo quien robó tus cosas, ¡así que ven y atrápame!",
  ui_story_5089_50890301_106_dialog_content = "Lo sabía.",
  ui_story_5089_50890301_107_dialog_content = "No entraré todavía, pero ¿estarías dispuesto a calmarte y hablar con nosotros a cambio?",
  ui_story_5089_50890301_108_dialog_content = "No somos malas personas, lo prometo. De hecho, si estás pasando por momentos difíciles, incluso podríamos ser capaces de ayudar.",
  ui_story_5089_50890301_109_dialog_content = "... En realidad, yo...",
  ui_story_5089_50890301_110_dialog_content = "¡Paso atrás!",
  ui_story_5089_50890301_111_dialog_content = "¡¿Qué...?!",
  ui_story_5089_50890301_112_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5089_50890301_113_dialog_content = "<color=#e8d9bb>Jiu saca su espada más rápido de lo que cualquiera puede ver.</color>",
  ui_story_5089_50890301_114_dialog_content = "<color=#828282>¡Ding!</color>",
  ui_story_5089_50890301_115_dialog_content = "<color=#e8d9bb>Con un ademán, ella desvía varios cables de metal potentes y extremadamente finos.</color>",
  ui_story_5089_50890301_116_dialog_content = "Ahí tienes.",
  ui_story_5089_50890301_117_dialog_content = "¿Quiénes son—",
  ui_story_5089_50890301_118_dialog_content = "<color=#e8d9bb>Sin responder, la figura misteriosa desata otro despiadado ataque de alambre!</color>",
  ui_story_5089_50890302_1_dialog_content = "¡Ahora es tu oportunidad, Jiu! ¡Derríbalo!",
  ui_story_5089_50890302_2_dialog_content = "Hmph.",
  ui_story_5089_50890302_3_dialog_content = "<color=#e8d9bb>Ahora tendido en el suelo, el asesino de repente levanta su brazo y lanza un ataque furtivo con sus cables!</color>",
  ui_story_5089_50890302_4_dialog_content = "¡Urgh!",
  ui_story_5089_50890302_5_dialog_content = "<color=#e8d9bb>Goteo.</color>",
  ui_story_5089_50890302_6_dialog_content = "<color=#e8d9bb>Una sola gota de sangre carmesí cae silenciosamente al suelo sucio.</color>",
  ui_story_5089_50890302_7_dialog_content = "Jiu...!",
  ui_story_5089_50890302_8_dialog_content = "<color=#e8d9bb>Jiu se encuentra frente a su atacante, su alambre atrapado en sus manos desnudas.</color>",
  ui_story_5089_50890302_9_dialog_content = "Mis disculpas por asustarte, Señor PlayerName.",
  ui_story_5089_50890302_10_dialog_content = "<color=#e8d9bb>De repente, ella junta sus manos y tira con todas sus fuerzas.</color>",
  ui_story_5089_50890302_11_dialog_content = "<color=#e8d9bb>El asesino, que intentó escapar saltando, es derribado por un alambre de metal rojo sangre y cae pesadamente al suelo.</color>",
  ui_story_5089_50890302_12_dialog_content = "Un momento mientras lo atrapo.",
  ui_story_5089_50890302_13_dialog_content = "Maldición... Si tan solo fuera alguien más que ese demonio enmascarado...",
  ui_story_5089_50890302_14_dialog_content = "Ven en paz, y tu vida puede ser perdonada.",
  ui_story_5089_50890302_15_dialog_content = "Espada de Hielo... Puede que solo sea un explorador, pero ambos respondemos directamente al rey. Eso significa que estamos del mismo lado, ¿no es así?",
  ui_story_5089_50890302_16_dialog_content = "Simplemente estoy tratando de llevar a cabo mi misión. ¿Realmente tienes la intención de impedirme cumplir las órdenes de nuestro rey?",
  ui_story_5089_50890302_17_dialog_content = "...",
  ui_story_5089_50890302_18_dialog_content = "¡Has vuelto, Jiu! ¿Cómo están tus heridas? Ese asesino justo ahora...",
  ui_story_5089_50890302_19_dialog_content = "Perdóname, yo... yo lo dejé escapar.",
  ui_story_5089_50890302_20_dialog_content = "Mientras estés bien, entonces está bien... Espera, no, ¡no está bien en absoluto!",
  ui_story_5089_50890302_21_dialog_content = "¿¡Por qué acabas de usar tu mano para bloquear su ataque!? ¿¡No sientes dolor o algo así!? ¡Aquí, déjame ver tus heridas!",
  ui_story_5089_50890302_22_dialog_content = "Son solo rasguños, PlayerName, nada más. Puedo atenderlos yo mismo.",
  ui_story_5089_50890302_23_dialog_content = "¿Otra vez? Ugh... No importa. Haz lo que quieras, voy a ocuparme de los niños.",
  ui_story_5089_50890302_24_dialog_content = "\"¿Niños\"?",
  ui_story_5089_50890302_25_dialog_content = "Así es, esos dos niños de antes. Están en esa casa de allí.",
  ui_story_5089_50890302_26_dialog_content = "¡Waaaaaah! ¡Estoy tan asustado!",
  ui_story_5089_50890302_27_dialog_content = "J-Solo deja de llorar ya, ¿lo harías? ¡Aquí, te traje algunas cosas realmente bonitas hoy!",
  ui_story_5089_50890302_28_dialog_content = "¿Ves? ¡Muchos juguetes lindos y una bonita linterna, solo para ti!",
  ui_story_5089_50890302_29_dialog_content = "¡Y mira todos estos libros de cuentos! ¿Quieres que te lea uno? Vamos, no llores...",
  ui_story_5089_50890302_30_dialog_content = "¡Waaaaaaaaah!",
  ui_story_5089_50890302_31_dialog_content = "Y eso es lo que pasó. El niño nunca robó ninguno del oro del príncipe. Todo lo que quería era una caja llena de juguetes.",
  ui_story_5089_50890302_32_dialog_content = "¿A quién le importa tu oro apestoso?",
  ui_story_5089_50890302_33_dialog_content = "¡Waaaaaah! ¡Otra persona aterradora!",
  ui_story_5089_50890302_34_dialog_content = "Oh, genial. ¡Mira lo que has hecho! ¡Solo sal de aquí ya! Ya, ya, no llores! Te conseguiré lo que quieras, ¡lo prometo!",
  ui_story_5089_50890302_35_dialog_content = "...",
  ui_story_5089_50890302_36_dialog_content = "¿Jiu?",
  ui_story_5089_50890302_37_dialog_content = "<color=#e8d9bb>Jiu se agacha frente a la pequeña niña, levanta torpemente su mano y coloca su máscara sobre la cabeza de la niña.</color>",
  ui_story_5089_50890302_38_dialog_content = "¡¿Q-Qué crees que estás haciendo?! Si le pones un dedo encima—",
  ui_story_5089_50890302_39_dialog_content = "El viento está aquí, la lluvia está aquí, el Rey Dragón golpea su tambor.",
  ui_story_5089_50890302_40_dialog_content = "Debajo de esta máscara, encontrarás un lugar para esconderte, mi pequeño.",
  ui_story_5089_50890302_41_dialog_content = "Y comeremos un melón bajo el sol cuando haya pasado la tormenta.",
  ui_story_5089_50890302_42_dialog_content = "<color=#e8d9bb>Mientras Jiu recita suavemente la canción de cuna, los sollozos de la niña oculta detrás de la máscara disminuyen gradualmente.</color>",
  ui_story_5089_50890302_43_dialog_content = "(No tenía idea de que Jiu pudiera ser tan amable.)",
  ui_story_5089_50890302_44_dialog_content = "PlayerName! Jiu! Gracias a Dios que finalmente te he encontrado!",
  ui_story_5089_50890302_45_dialog_content = "¿Oh? ¿Qué está sucediendo aquí? ¿Por qué Jiu decidió quitarse la máscara?",
  ui_story_5089_50890302_46_dialog_content = "¡Su Alteza! Solo estaba...",
  ui_story_5089_50890302_47_dialog_content = "Eh, discúlpame...",
  ui_story_5089_50890302_48_dialog_content = "¿Ah?",
  ui_story_5089_50890302_49_dialog_content = "¿P-Podrías cantar esa canción una vez más?",
  ui_story_5089_50890302_50_dialog_content = "Es como... La que mi mamá solía cantar.",
  ui_story_5089_50890302_51_dialog_content = "Por supuesto.",
  ui_story_5089_50890302_52_dialog_content = "¿De verdad? ¿Entonces pueden venir mis amigos a escuchar también?",
  ui_story_5089_50890302_53_dialog_content = "¿Tus amigos...?",
  ui_story_5089_50890302_54_dialog_content = "¡Hermano mayor Ergou! ¡Ve a llamar a los demás!",
  ui_story_5089_50890302_55_dialog_content = "Supongo que después de todo no son tan malos. Solo un segundo, iré a buscarlos.",
  ui_story_5089_50890302_56_dialog_content = "¿Qué está pasando, Xiaohua? ¿Por qué nos llamaste?",
  ui_story_5089_50890302_57_dialog_content = "¿Realmente importa? No es como si tuviéramos algo mejor que hacer.",
  ui_story_5089_50890302_58_dialog_content = "¿Qué hacen todos estos adultos aquí...?",
  ui_story_5089_50890302_59_dialog_content = "¿Por qué hay tantos niños aquí?",
  ui_story_5089_50890302_60_dialog_content = "El posadero tuvo la amabilidad de informarme sobre la situación aquí en el pueblo. Permíteme explicar.",
  ui_story_5089_50890302_61_dialog_content = "Recuerda lo que dijo aquel caballero mayor sobre los talleres de la ciudad, y cómo la mayoría de la gente capaz del pueblo se fue a trabajar en ellos? Por lucrativos que sean estos trabajos, aún requieren que los trabajadores dejen sus hogares muy atrás.",
  ui_story_5089_50890302_62_dialog_content = "Como tal, muchos niños han quedado al cuidado de sus abuelos, quienes no se puede esperar que los vigilen a todas horas del día.",
  ui_story_5089_50890302_63_dialog_content = "Sin supervisión, estos niños tienden a reunirse y correr descontrolados.",
  ui_story_5089_50890302_64_dialog_content = "¿Entonces no están realmente relacionados por sangre? Pensé que esos dos eran hermano y hermana, así que yo...",
  ui_story_5089_50890302_65_dialog_content = "Xiaohua todavía es mi hermana. Mis padres murieron temprano, pero su familia me ha estado alimentando todo este tiempo.",
  ui_story_5089_50890302_66_dialog_content = "Así que por supuesto, acepté cuidar de ella cuando me dijeron que se iban a trabajar hace unos días.",
  ui_story_5089_50890302_67_dialog_content = "Pero Xiaohua realmente extraña a sus padres. Ha estado llorando estos últimos días, por eso yo...",
  ui_story_5089_50890302_68_dialog_content = "¿Querías animarla con algunos juguetes?",
  ui_story_5089_50890302_69_dialog_content = "Sí. Pero ahora que me has atrapado, aceptaré cualquier golpiza o regaño que tengas para mí.",
  ui_story_5089_50890302_70_dialog_content = "Aunque robar está mal, ¿cómo podría regañarte después de saber todo esto?",
  ui_story_5089_50890302_71_dialog_content = "Ah, ¿qué deberíamos hacer con estos niños? Ahora que han rodeado a Jiu, parece que está totalmente atrapada.",
  ui_story_5089_50890302_72_dialog_content = "Entonces deberías apresurarte a ayudarla de inmediato, PlayerName.",
  ui_story_5089_50890302_73_dialog_content = "Pero, ¿qué debo hacer?",
  ui_story_5089_50890302_74_dialog_content = "Pedirle a Jiu que cante para tanta gente es un poco excesivo, incluso para ella. Deberíamos intentar aligerar la carga para ella.",
  ui_story_5089_50890302_75_dialog_content = "Ven, vamos a buscar mi pipa en la posada.",
  ui_story_5089_50890302_76_dialog_content = "Me dijeron hace mucho que eres bastante hábil en el piano, pero nunca te he escuchado tocar. ¿Estarías dispuesto a unirte a mí para un dueto hoy?",
  ui_story_5089_50890302_77_dialog_content = "Me encantaría, pero no veo un piano aquí.",
  ui_story_5089_50890302_78_dialog_content = "Oh, eso no debería ser un problema.",
  ui_story_5089_50890302_79_dialog_content = "Los músicos del pasado podían improvisar una melodía con objetos cotidianos. No veo ninguna razón por la que un Caelestite no pudiera hacer lo mismo, especialmente cuando tenemos todas estas tazas.",
  ui_story_5089_50890302_80_dialog_content = "¿Ves? Podemos producir todo tipo de notas llenándolas con diferentes cantidades de agua y golpeándolas así.",
  ui_story_5089_50890302_81_dialog_content = "Supongo que podría intentarlo.",
  ui_story_5089_50890302_82_dialog_content = "Jiu, ¿todavía recuerdas lo que te dije cuando visitamos por primera vez Twin Pavilions Bay?",
  ui_story_5089_50890302_83_dialog_content = "Si, algún día, pudiera hacer un dueto con el pianista, espero que vengas y realices un baile con tu espada.",
  ui_story_5089_50890302_84_dialog_content = "P-P-Pero hay tanta gente...",
  ui_story_5089_50890302_85_dialog_content = "No estás solo, Jiu. También estamos contigo.",
  ui_story_5089_50890302_86_dialog_content = "Si es demasiado pedir, no te obligaré. Solo es que la actuación de hoy puede ser algo deficiente sin tu ayuda.",
  ui_story_5089_50890302_87_dialog_content = "E-Entendido...",
  ui_story_5089_50890302_88_dialog_content = "Qué vergonzoso.",
  ui_story_5089_50890302_89_dialog_content = "Jeje, apenas lo creo. Solo mira cuán brillantemente brillan los ojos de los niños, Jiu!",
  ui_story_5089_50890302_90_dialog_content = "¡Para ellos, tu danza de la espada es la mejor del mundo!",
  ui_story_5089_50890302_91_dialog_content = "Me halagas, Su Alteza. Solo estoy haciendo lo mejor para evitar hacerme aún más el tonto.",
  ui_story_5089_50890302_92_dialog_content = "Vaya, ¡sólo mira esta espléndida actuación! ¿Hay algo que pueda hacer para contribuir?",
  ui_story_5089_50890302_93_dialog_content = "¿Quizás una canción jubilosa para animar a todos?",
  ui_story_5089_50890302_94_dialog_content = "¿Oh? ¿Qué canciones conoces?",
  ui_story_5089_50890302_95_dialog_content = "Ejem, déjame ver...",
  ui_story_5089_50890302_96_dialog_content = "¡De sur a norte, te traemos nuestro maravilloso espectáculo!",
  ui_story_5089_50890302_97_dialog_content = "Ya seas príncipe o mendigo, no importa. ¡Sin embargo, tu cambio sobrante significaría mucho!",
  ui_story_5089_50890302_98_dialog_content = "<color=#e8d9bb>Ding.</color>",
  ui_story_5089_50890302_99_dialog_content = "<color=#e8d9bb>Sorprendentemente, varios habitantes del pueblo desprevenidos le lanzan un par de monedas.</color>",
  ui_story_5089_50890302_100_dialog_content = "¡Li Tianxian!",
  ui_story_5089_50890302_101_dialog_content = "¡E-Es todo parte del espectáculo, Su Alteza! ¡Recuerde concentrarse en la música!",
  ui_story_5089_50890302_102_dialog_content = "<color=#e8d9bb>Una tormenta inminente y un variopinto grupo de improbables artistas, cada uno con sus propias preocupaciones.</color>",
  ui_story_5089_50890302_103_dialog_content = "<color=#e8d9bb>Lejos de una actuación perfecta, su espectáculo es más una coincidencia caprichosa.</color>",
  ui_story_5089_50890302_104_dialog_content = "<color=#e8d9bb>Pero al menos, este momento—</color>",
  ui_story_5089_50890302_105_dialog_content = "<color=#e8d9bb>Merece una canción propia.</color>",
  ui_story_5089_50890401_1_dialog_content = "¿Qué estás volteando en tus manos, PlayerName?",
  ui_story_5089_50890401_2_dialog_content = "¿Te refieres a esto? Es solo una figurita de bronce. Er Gou me la devolvió antes de que nos separáramos antes.",
  ui_story_5089_50890401_3_dialog_content = "Xiaohua no quería más juguetes después de que obtuvo esa máscara de Jiu, así que Ergou entregó todo lo que robó.",
  ui_story_5089_50890401_4_dialog_content = "Y como disculpa, también me dio esto.",
  ui_story_5089_50890401_5_dialog_content = "Dijo que una señora amable se lo dio mientras pasaba por la ciudad. Dice que se llama una muñeca Moheluo.",
  ui_story_5089_50890401_6_dialog_content = "Había un montón de gente siguiéndola también. Vestían completamente de negro y apenas dijeron una palabra todo el tiempo, ¡fue tan espeluznante!",
  ui_story_5089_50890401_7_dialog_content = "Pero ella era una buena persona, sin duda alguna. ¡Incluso nos invitó a uno de los posadas más grandes para cenar, y nos dio toda la carne que podíamos comer!",
  ui_story_5089_50890401_8_dialog_content = "Ella también es bastante inteligente. Todas las trampas que colocamos en el callejón se hicieron usando sus diseños.",
  ui_story_5089_50890401_9_dialog_content = "Dijo que son los fundamentos de las técnicas de trampas, y que podríamos volvernos más inteligentes al entenderlas.",
  ui_story_5089_50890401_10_dialog_content = "¿Mencionó ella su nombre en algún momento?",
  ui_story_5089_50890401_11_dialog_content = "No... Ella y sus seguidores solo se quedaron en la ciudad por un día, y se fueron igual de rápido. ¡Pero eso me recuerda!",
  ui_story_5089_50890401_12_dialog_content = "¡Tenía una extraña costumbre de llevar un enorme paraguas a donde quiera que fuera, aunque nunca había llovido mientras ella estaba aquí!",
  ui_story_5089_50890401_13_dialog_content = "Eso suena como alguien que conocemos, ¿no es así?",
  ui_story_5089_50890401_14_dialog_content = "Es cierto que esta ruta es la forma más rápida de regresar al Reino de Ji. ¿Quizás la Ministra Armilla realmente pasó por aquí?",
  ui_story_5089_50890401_15_dialog_content = "Aun así, que juegue con niños y los invite a cenas lujosas, todo mientras lleva sus armas a plena luz del día...",
  ui_story_5089_50890401_16_dialog_content = "Parece que el delincuente más buscado en todo el Reino de Ye en realidad está viviendo una vida bastante despreocupada.",
  ui_story_5089_50890401_17_dialog_content = "Pero con todas esas personas vestidas de negro siguiéndola, probablemente no puede moverse tan libremente como le gustaría.",
  ui_story_5089_50890401_18_dialog_content = "Perdóneme PlayerName, pero ¿puedo ver esa figurita por un momento?",
  ui_story_5089_50890401_19_dialog_content = "Seguro. He estado tratando de sentirlo para obtener información útil, pero no he encontrado nada.",
  ui_story_5089_50890401_20_dialog_content = "Parece que nuestras mentes piensan igual. Si hay información por descubrir, bien podría estar oculta dentro de esta muñeca...",
  ui_story_5089_50890401_21_dialog_content = "<color=#e8d9bb>Tarde en la noche</color>",
  ui_story_5089_50890401_22_dialog_content = "*bostezo*",
  ui_story_5089_50890401_23_dialog_content = "Uf, mi garganta está tan seca. Necesito agua...",
  ui_story_5089_50890401_24_dialog_content = "Ah, la tetera está vacía... Mejor voy a revisar el pasillo.",
  ui_story_5089_50890401_25_dialog_content = "¿Eh? La luz sigue encendida allí. ¿No es esa la habitación de Dantang?",
  ui_story_5089_50890401_26_dialog_content = "¿Eres tú ahí fuera, PlayerName?",
  ui_story_5089_50890401_27_dialog_content = "¿Eh? ¿Puedes verme o algo?",
  ui_story_5089_50890401_28_dialog_content = "No, pero podría decirlo por el sonido de tus pasos. Por favor, entra.",
  ui_story_5089_50890401_29_dialog_content = "Esa muñeca otra vez... ¿Todavía la estás estudiando?",
  ui_story_5089_50890401_30_dialog_content = "Sí. Ya sea que ella quisiera dejar esto atrás o no, estoy seguro de que esta muñeca tiene algún conocimiento sobre Ministress Armilla.",
  ui_story_5089_50890401_31_dialog_content = "Entonces, ¿qué es exactamente una muñeca Moheluo?",
  ui_story_5089_50890401_32_dialog_content = "Es un tipo de juguete que era popular en el pasado. Sin embargo, generalmente se talla de arcilla o madera, no de metal.",
  ui_story_5089_50890401_33_dialog_content = "Y aún así, este está hecho de bronce, ¿verdad?",
  ui_story_5089_50890401_34_dialog_content = "Correcto, y resulta que la Ministra Armilla es muy hábil con el bronce. De hecho, su primera fama provino de un conjunto de marionetas mecánicas musicales que ella diseñó y elaboró personalmente.",
  ui_story_5089_50890401_35_dialog_content = "Tocó música junto a estos maniquíes, y no fue hasta que terminó el espectáculo que su audiencia se dio cuenta de que algo estaba mal. Fue entonces cuando se dieron cuenta de que todos los músicos eran marionetas mecánicas.",
  ui_story_5089_50890401_36_dialog_content = "Me impresiona que Xuan Ji pueda crear marionetas tan increíbles... Entonces, ¿por qué esta es tan tosca y fea?",
  ui_story_5089_50890401_37_dialog_content = "Ese es otro punto extraño que deseo mencionar.",
  ui_story_5089_50890401_38_dialog_content = "Las muñecas Moheluo normalmente se fabrican a semejanza de un niño lindo y adorable, pero esta está arrugada y grotesca.",
  ui_story_5089_50890401_39_dialog_content = "Además, está destinado a sostener una hoja o flor de loto en su mano.",
  ui_story_5089_50890401_40_dialog_content = "Aunque esta figurina está efectivamente sosteniendo una flor, una inspección más cercana revela que es una magnolia.",
  ui_story_5089_50890401_41_dialog_content = "Una especie prospera bajo el agua mientras que la otra teme la inundación. Son tan incompatibles como el agua y el fuego.",
  ui_story_5089_50890401_42_dialog_content = "Esta muñeca se parece a una muñeca Moheluo en muchos aspectos, y sin embargo, no podría ser más diferente. Solo puedo describirla como un sustituto, o incluso una falsificación.",
  ui_story_5089_50890401_43_dialog_content = "Un sustituto o una falsificación, huh...",
  ui_story_5089_50890401_44_dialog_content = "En el pasado, también había una obra con el mismo nombre exacto.",
  ui_story_5089_50890401_45_dialog_content = "La mayoría de las personas no están muy familiarizadas con la obra en sí, pero una de sus líneas es extremadamente conocida y reconocida por todos.",
  ui_story_5089_50890401_46_dialog_content = "¿Qué línea es esa?",
  ui_story_5089_50890401_47_dialog_content = "\"Puedes pintar el pelaje de un tigro, pero no su alma. Puedes ver el rostro de una persona, pero no su corazón.\"",
  ui_story_5089_50890401_48_dialog_content = "<color=#e8d9bb>¡Chasquido!</color>",
  ui_story_5089_50890401_49_dialog_content = "!",
  ui_story_5089_50890401_50_dialog_content = "¡¿Quién va allí?!",
  ui_story_5089_50890402_1_dialog_content = "¿Huyendo ante la derrota? Al menos, hoy he tomado su medida.",
  ui_story_5089_50890402_2_dialog_content = "¿Eran esos Fate Riders justo ahora? ¿O eran ellos...",
  ui_story_5089_50890402_3_dialog_content = "No estoy seguro.",
  ui_story_5089_50890402_4_dialog_content = "Pero tal como están las cosas, no hay distinción entre ellos y los espías del Reino Ye.",
  ui_story_5089_50890402_5_dialog_content = "Afortunadamente, no eran muchos y sus artes marciales eran mediocres.",
  ui_story_5089_50890402_6_dialog_content = "Realmente sobresalieron en hacer una retirada apresurada, lo que me lleva a suponer que solo eran exploradores recopilando información.",
  ui_story_5089_50890402_7_dialog_content = "Pero eso significa que hemos sido expuestos, ¿no es así? ¿No deberíamos irnos de inmediato?",
  ui_story_5089_50890402_8_dialog_content = "Dime, PlayerName, ¿has notado algo extraño?",
  ui_story_5089_50890402_9_dialog_content = "¿Qué haces tú... ¡Espera!",
  ui_story_5089_50890402_10_dialog_content = "Hicimos tal conmoción hace un momento... ¡Pero Jiu no está a la vista!",
  ui_story_5089_50890402_11_dialog_content = "¿Por qué esos chicos aún no han vuelto? No fueron asesinados, ¿verdad?",
  ui_story_5089_50890402_12_dialog_content = "Hmph, si no podían manejar algo tan pequeño, entonces merecían morir.",
  ui_story_5089_50890402_13_dialog_content = "*suspiro* Supongo que esa es nuestra suerte en la vida. Olvídalos, y voy al baño.",
  ui_story_5089_50890402_14_dialog_content = "No te muevas.",
  ui_story_5089_50890402_15_dialog_content = "!",
  ui_story_5089_50890402_16_dialog_content = "A-Bien, me has atrapado. No me moveré.",
  ui_story_5089_50890402_17_dialog_content = "Si pudiste infiltrarte en nuestro campamento y tomarme como rehén de esta manera, entonces definitivamente no soy rival para ti.",
  ui_story_5089_50890402_18_dialog_content = "Entonces, ¿podrías por favor mover tu espada un poco más lejos de mi cuello? Después de todo, no podré responder a ninguna pregunta si tu mano llega a resbalar.",
  ui_story_5089_50890402_19_dialog_content = "¿Por qué estás aquí? ¿Cuáles son tus órdenes?",
  ui_story_5089_50890402_20_dialog_content = "¿Hay una razón específica por la que tú...?",
  ui_story_5089_50890402_21_dialog_content = "Suficiente. Responde la pregunta.",
  ui_story_5089_50890402_22_dialog_content = "C-Como desee. Simplemente estamos siguiendo la orden de nuestro amo para traer a su desobediente hija de vuelta a su casa.",
  ui_story_5089_50890402_23_dialog_content = "Solo estamos ayudando con pequeños asuntos familiares, eso es todo. No hemos hecho nada ilegal.",
  ui_story_5089_50890402_24_dialog_content = "¿Ayudar con un \"asunto familiar pequeño\" suele requerir tantos guerreros?",
  ui_story_5089_50890402_25_dialog_content = "¿Puedes culparnos? La casa de nuestro maestro es grandiosa, y su hija está protegida por uno de los soldados más formidables del reino.",
  ui_story_5089_50890402_26_dialog_content = "Nuestro amo personalmente la asignó a su amada hija, pero parece que se ha vuelto rebelde junto con su cargo.",
  ui_story_5089_50890402_27_dialog_content = "Nuestro maestro está bastante decepcionado con ambos.",
  ui_story_5089_50890402_28_dialog_content = "...",
  ui_story_5089_50890402_29_dialog_content = "Como dije, es un asunto familiar pequeño, y es mejor dejarlo en sus manos.",
  ui_story_5089_50890402_30_dialog_content = "A pesar de su ira, nuestro maestro nunca lastimaría a su hija de ninguna manera.",
  ui_story_5089_50890402_31_dialog_content = "Incluso si ella continúa siendo irrazonable, no le sucederá nada malo. En el peor de los casos, será confinada en su casa y obligada a escribir los edictos de su familia una y otra vez.",
  ui_story_5089_50890402_32_dialog_content = "Por otro lado, su guardia amenazó los planes de nuestro maestro al abandonar sus deberes.",
  ui_story_5089_50890402_33_dialog_content = "Solo puedo imaginar su dolor después de pasar todos esos años, solo para criar a un traidor ingrato. ¿Qué opinas de eso—",
  ui_story_5089_50890402_34_dialog_content = "¿Hola? ¿Todavía estás ahí?",
  ui_story_5089_50890402_35_dialog_content = "Je.",
  ui_story_5089_50890402_36_dialog_content = "¿Qué te tomó tanto tiempo?",
  ui_story_5089_50890402_37_dialog_content = "Lo siento, me detuve a charlar con un viejo amigo hace un momento.",
  ui_story_5089_50890402_38_dialog_content = "Hazme un favor y pasa un mensaje a nuestros espías cuando regresen.",
  ui_story_5089_50890402_39_dialog_content = "Diles que tendremos a la princesa en casa para el final de mañana.",
  ui_story_5089_50890402_40_dialog_content = "Y si ese demonio enmascarado se interpone en nuestro camino, considéralo un acto de alta traición...",
  ui_story_5089_50890402_41_dialog_content = "Castigable con la muerte.",
  ui_story_5089_50890402_42_dialog_content = "... ¿Su Alteza? PlayerName? ¿Por qué están ambos afuera?",
  ui_story_5089_50890402_43_dialog_content = "¿Dónde estabas, Jiu? Acabamos de llegar—",
  ui_story_5089_50890402_44_dialog_content = "PlayerName.",
  ui_story_5089_50890402_45_dialog_content = "Es tarde. Deberíamos retirarnos a nuestras habitaciones por el resto de la noche.",
  ui_story_5089_50890402_46_dialog_content = "Todavía tengo mucho que considerar, si no te importa.",
  ui_story_5089_50890402_47_dialog_content = "...Okey.",
  ui_story_5089_50890402_48_dialog_content = "Buenas noches, Dantang. Tú también, Jiu.",
  ui_story_5089_50890402_49_dialog_content = "Buenas noches, PlayerName.",
  ui_story_5089_50890402_50_dialog_content = "...",
  ui_story_5089_50890402_51_dialog_content = "<color=#e8d9bb>El día siguiente</color>",
  ui_story_5089_50890402_52_dialog_content = "¿Maestro Li? May ¿Puedo molestarte por un momento?",
  ui_story_5089_50890402_53_dialog_content = "Nngh... ¿Sigo soñando? ¿Ha salido el sol por el oeste hoy?",
  ui_story_5089_50890402_54_dialog_content = "¿Qué le ha poseído para hablarme tan cortésmente hoy, Su Alteza?",
  ui_story_5089_50890402_55_dialog_content = "... Necesito que realices una adivinación para mí.",
  ui_story_5089_50890402_56_dialog_content = "Vaya, qué verdaderamente rara ocurrencia.",
  ui_story_5089_50890402_57_dialog_content = "¿Qué será hoy, Su Alteza? ¿Las maquinaciones del destino? ¿Un pronóstico de fortunas? ¿O quizás algo más urgente, como las perspectivas de matrimonio?",
  ui_story_5089_50890402_58_dialog_content = "Yo... Simplemente quería preguntar sobre el camino adelante.",
  ui_story_5089_50890402_59_dialog_content = "Tengo un cierto asunto entre manos, pero no sé cómo proceder con él... O si incluso puedo hacerlo, para el caso.",
  ui_story_5089_50890402_60_dialog_content = "¡Ciertamente, Su Alteza! Ahora, si quiere, por favor extienda su mano y podemos comenzar.",
  ui_story_5089_50890402_61_dialog_content = "Muy bien.",
  ui_story_5089_50890402_62_dialog_content = "<color=#e8d9bb>¡Estrépito!</color>",
  ui_story_5089_50890402_63_dialog_content = "<color=#e8d9bb>Dos palos de adivinación caen en las manos de Dantang. Pero antes de que pueda echar un vistazo más de cerca—</color>",
  ui_story_5089_50890402_64_dialog_content = "<color=#e8d9bb>Tianxian derrama el resto de sus palillos de adivinación.</color>",
  ui_story_5089_50890402_65_dialog_content = "¿Q-Qué significa esto, Maestro Li?",
  ui_story_5089_50890402_66_dialog_content = "Ugh, escucharte decir eso se siente tan antinatural. Por favor, llámame Tianxian o Lying Li si lo prefieres.",
  ui_story_5089_50890402_67_dialog_content = "Ahora bien, mis palos de adivinación pueden no parecerte mucho, pero he confiado en ellos para recorrer el mundo durante mucho tiempo.",
  ui_story_5089_50890402_68_dialog_content = "Hay quienes creen en mis talentos. Con su fe, puedo ayudarles a evitar todo tipo de caos y calamidad.",
  ui_story_5089_50890402_69_dialog_content = "También están aquellos que no creen, aquellos que se ríen de mis profecías y simplemente siguen con su día.",
  ui_story_5089_50890402_70_dialog_content = "Pero que me pidas ayuda y la dudes en el mismo aliento, que busques mi guía pero te niegues a seguirla de buena fe...",
  ui_story_5089_50890402_71_dialog_content = "Esto no es diferente a escupir sobre mi arte.",
  ui_story_5089_50890402_72_dialog_content = "... ¿No crees que tal vez estás exagerando un poco?",
  ui_story_5089_50890402_73_dialog_content = "Difícilmente lo creo.",
  ui_story_5089_50890402_74_dialog_content = "Si me permites ser tan audaz para preguntar, Lady Dantang, cuando los dos primeros palos cayeron en tu mano, ya estabas esperando un cierto resultado, ¿no es así?",
  ui_story_5089_50890402_75_dialog_content = "...",
  ui_story_5089_50890402_76_dialog_content = "Puedo ver que no me equivoco. La honorable Princesa Zhuohua no es de las que se resigna a su destino.",
  ui_story_5089_50890402_77_dialog_content = "Y ya que has tomado una decisión, no tiene sentido seguir jugando.",
  ui_story_5089_50890402_78_dialog_content = "Sin embargo, debo pedirte que me ayudes a poner mis palos de adivinación de nuevo en su lugar. Es una cortesía profesional, ¿entiendes?",
  ui_story_5089_50890402_79_dialog_content = "Maestro Li.",
  ui_story_5089_50890402_80_dialog_content = "No hay necesidad del honorífico. ¿No fui claro sobre eso justo ahora?",
  ui_story_5089_50890402_81_dialog_content = "Todavía tengo un favor más que pedirte.",
  ui_story_5089_50890402_82_dialog_content = "... Mis disculpas. Permítame retractarme de mi declaración anterior.",
  ui_story_5089_50890402_83_dialog_content = "Ven, extiende tu mano una vez más. Me aseguraré de que tu fortuna te diga que dejes este asunto en paz.",
  ui_story_5089_50890402_84_dialog_content = "Eso no será necesario. Después de todo, soy la Princesa Zhuohua.",
  ui_story_5089_50890402_85_dialog_content = "Mi incredulidad en el destino es conocida por todos.",
  ui_story_5089_50890402_86_dialog_content = "Ah, sí, supongo que acabo de decir eso.",
  ui_story_5089_50890402_87_dialog_content = "¡Realmente debería dejar de hacerme esto a mí mismo!",
  ui_story_5089_50890402_88_dialog_content = "*Suspiro* Muy bien, entonces... Después de todo, todavía te debo un agradecimiento por salvar mi vida.",
  ui_story_5089_50890402_89_dialog_content = "Adelante, nombra tu favor.",
  ui_story_5089_50890402_90_dialog_content = "Hola Dantang, encontré un servicio de escolta armada como pediste.",
  ui_story_5089_50890402_91_dialog_content = "Acordaron devolver el oro del príncipe heredero a la capital del Reino Ji.",
  ui_story_5089_50890402_92_dialog_content = "Entonces, ¿qué sigue para nosotros? ¿Deberíamos irnos también?",
  ui_story_5089_50890402_93_dialog_content = "No solo aún.",
  ui_story_5089_50890402_94_dialog_content = "El posadero acaba de traer dos paquetes frescos de té, y saben bastante excelentes. No haría daño pasar unos minutos más disfrutando de nuestro té, ¿verdad?",
  ui_story_5089_50890402_95_dialog_content = "Supongo que no, pero ¿realmente podemos permitirnos tomarlo con calma así?",
  ui_story_5089_50890402_96_dialog_content = "No te preocupes, esto no tomará mucho tiempo.",
  ui_story_5089_50890402_97_dialog_content = "¿Estás ahí, Jiu?",
  ui_story_5089_50890402_98_dialog_content = "... Sí, su Alteza.",
  ui_story_5089_50890402_99_dialog_content = "Ven y toma una taza de té con nosotros. Tengo algo que decirte una vez que terminemos aquí.",
  ui_story_5089_50890402_100_dialog_content = "Como desees.",
  ui_story_5089_50890402_101_dialog_content = "¡Este té realmente es delicioso! Tiene un sabor ligero pero refrescante y un aroma frutal que otros tés normalmente no tienen.",
  ui_story_5089_50890402_102_dialog_content = "Oh, eso es porque agregué un poco de \"polvo escalofriante de sangre\", que se hace de una fruta ligeramente tóxica.",
  ui_story_5089_50890402_103_dialog_content = "... ¿Eh?",
  ui_story_5089_50890402_104_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5089_50890402_105_dialog_content = "<color=#e8d9bb>De repente, Jiu cae de rodillas.</color>",
  ui_story_5089_50890402_106_dialog_content = "J-Jiu...!",
  ui_story_5089_50890402_107_dialog_content = "No te preocupes, este tipo de droga solo paraliza las extremidades sin dañar el cuerpo en sí. Se desvanecerá naturalmente después de un tiempo.",
  ui_story_5089_50890402_108_dialog_content = "Curiosamente, sus efectos son más rápidos y potentes en aquellos con gran fuerza interior y destreza en las artes marciales.",
  ui_story_5089_50890402_109_dialog_content = "Oh, eso explica por qué aún no siento nada... ¡Espera, ese no es el punto!",
  ui_story_5089_50890402_110_dialog_content = "¿Por qué harías algo así, Dantang?!",
  ui_story_5089_50890402_111_dialog_content = "Porque estamos fuera de tiempo.",
  ui_story_5089_50890402_112_dialog_content = "Su Alteza, Graznido y Farfullar me han informado que ya han llegado bastantes personas a la posada.",
  ui_story_5089_50890402_113_dialog_content = "Y parece que nuestros nuevos invitados no vienen en paz.",
  ui_story_5089_50890402_114_dialog_content = "Tianxian, ¿tú tampoco... Espera, quién diablos eres tú?!",
  ui_story_5089_50890402_115_dialog_content = "Claramente, soy la única e inigualable señorita Jiu. Ya sea en reposo o en el camino, eso no cambia.",
  ui_story_5089_50890402_116_dialog_content = "¡Este no es el momento de reinventarte, Tianxian!",
  ui_story_5089_50890402_117_dialog_content = "Tampoco es el momento de hacer tal alboroto innecesario, ¿no estás de acuerdo?",
  ui_story_5089_50890402_118_dialog_content = "¿Realmente puedes culparme? ¡Esto es completamente ridículo!",
  ui_story_5089_50890402_119_dialog_content = "Eso es suficiente, mi amigo. Ahora ayúdame a esconder a la señorita Jiu en ese armario de allí, y rápido.",
  ui_story_5089_50890402_120_dialog_content = "Uh, seguro... ¡Whoa!",
  ui_story_5089_50890402_121_dialog_content = "Jiu, ¿qué estás...",
  ui_story_5089_50890402_122_dialog_content = "<color=#e8d9bb>El cuerpo de Jiu se balancea ligeramente mientras resiste los efectos de la medicina con todas sus fuerzas. Casi se puede escuchar el sonido de sus huesos temblando desde dentro.</color>",
  ui_story_5089_50890402_123_dialog_content = "<color=#e8d9bb>De repente, las heridas en sus manos se abrieron, empapando su ropa con sangre fresca.</color>",
  ui_story_5089_50890402_124_dialog_content = "<color=#e8d9bb>Ella mueve forzadamente su cuerpo rígido lo suficiente para agarrar el borde de la falda de Dantang.</color>",
  ui_story_5089_50890402_125_dialog_content = "...",
  ui_story_5089_50890402_126_dialog_content = "<color=#e8d9bb>Dantang retrocede, quitando su falda de la mano ensangrentada de Jiu.</color>",
  ui_story_5089_50890402_127_dialog_content = "Día y noche durante los últimos cinco años, has estado a mi lado. Estoy eternamente agradecido por todo lo que has hecho por mí, Jiu.",
  ui_story_5089_50890402_128_dialog_content = "Eres una buena persona, así como el servidor más leal que alguien podría pedir.",
  ui_story_5089_50890402_129_dialog_content = "Pero ya no hay forma de mantener nuestra paz.",
  ui_story_5089_50890402_130_dialog_content = "Sé que no deseas hacerme daño, pero tampoco desobedecerías las órdenes de mi tío.",
  ui_story_5089_50890402_131_dialog_content = "Como una sola persona, no puedes caminar dos caminos opuestos, o servir como una espada en las manos de dos personas diferentes con objetivos opuestos.",
  ui_story_5089_50890402_132_dialog_content = "Princesa... Dantang...",
  ui_story_5089_50890402_133_dialog_content = "En verdad, no tengo derecho a darte órdenes hasta que tomes tu decisión.",
  ui_story_5089_50890402_134_dialog_content = "Solo ten en cuenta que si te niegas a hacerlo, alguien como yo eventualmente intervendrá y te quitará ese derecho.",
  ui_story_5089_50890402_135_dialog_content = "Al renunciar a tu libertad de elección, naturalmente te convertirás en un títere a merced de los demás.",
  ui_story_5089_50890402_136_dialog_content = "Tu situación actual debería ser prueba de eso.",
  ui_story_5089_50890402_137_dialog_content = "Jiu.",
  ui_story_5089_50890402_138_dialog_content = "A partir de este momento, quedas relevado de tu deber como guardián de la Princesa Zhuohua.",
  ui_story_5089_50890402_139_dialog_content = "!",
  ui_story_5089_50890402_140_dialog_content = "Ni quiero ni necesito que seas como eres ahora.",
  ui_story_5089_50890402_141_dialog_content = "Me niego a vivir bajo tu protección o, peor aún, tu vigilancia.",
  ui_story_5089_50890402_142_dialog_content = "Lo que quiero es...",
  ui_story_5089_50890402_143_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5089_50890402_144_dialog_content = "<color=#e8d9bb>Las últimas palabras de Dantang fueron ahogadas por un ruido fuerte afuera.</color>",
  ui_story_5089_50890402_145_dialog_content = "¡Adentro vas!",
  ui_story_5089_50890402_146_dialog_content = "?",
  ui_story_5089_50890402_147_dialog_content = "<color=#e8d9bb>También me empujaron al guardarropa.</color>",
  ui_story_5089_50890402_148_dialog_content = "Perdóname por tomar egoístamente las cosas en mis propias manos, PlayerName.",
  ui_story_5089_50890402_149_dialog_content = "Estoy dejando Jiu y todo lo demás en tus manos ahora.",
  ui_story_5089_50890402_150_dialog_content = "¡Espera, Dantang!",
  ui_story_5089_50890402_151_dialog_content = "<color=#e8d9bb>Las puertas del ropero se cierran con un movimiento suave.</color>",
  ui_story_5089_50890402_152_dialog_content = "<color=#e8d9bb>Al siguiente momento, la puerta de la habitación se abre de repente.</color>",
  ui_story_5089_50890402_153_dialog_content = "Ah, finalmente. Conseguir una audiencia contigo no ha sido muy fácil, Princesa Zhuohua.",
  ui_story_5089_50890402_154_dialog_content = "(¡Esa voz!)",
  ui_story_5089_50890402_155_dialog_content = "Zhui Hu...",
  ui_story_5089_50890402_156_dialog_content = "Parece que la Ministra Armilla tenía razón: estás muy vivo y bien.",
  ui_story_5089_50890402_157_dialog_content = "Pero por supuesto. Después de todo, no podría morir antes de crear la Bestia Mecánica más poderosa del mundo.",
  ui_story_5089_50890402_158_dialog_content = "No tuve la oportunidad de preguntarte antes, pero los rumores de tu afiliación con los Fate Riders eran claramente ciertos.",
  ui_story_5089_50890402_159_dialog_content = "Sí, pero ¿no es eso perfectamente normal? Cualquiera dispuesto a apoyar mi oficio merece ser llamado mi maestro.",
  ui_story_5089_50890402_160_dialog_content = "Aun así, no ha sido fácil obtener la Llama Zhuyin una vez más. He estado ocupado desarrollando un nuevo sistema de poder para el último Stinger.",
  ui_story_5089_50890402_161_dialog_content = "Pero estos hombres insistieron en arrastrarme aquí para conocerte.",
  ui_story_5089_50890402_162_dialog_content = "Sin embargo, me prometieron algo agradable por mis problemas.",
  ui_story_5089_50890402_163_dialog_content = "Dijeron que si tú o tu guardia nos resistían de alguna manera, podría probar mi arma más nueva en ti.",
  ui_story_5089_50890402_164_dialog_content = "Ahora bien, ¿te importaría poner un poco de lucha? Incluso la más pequeña servirá, jejeje.",
  ui_story_5089_50890402_165_dialog_content = "No veo ninguna razón para hacerlo.",
  ui_story_5089_50890402_166_dialog_content = "Soy la Princesa Zhuohua del Reino de Ye, y aparte de ti, el resto de estos soldados son los leales sirvientes de mi tío.",
  ui_story_5089_50890402_167_dialog_content = "Como tal, nunca me harían daño de ninguna manera. Simplemente han venido a darme la bienvenida a casa, ¿verdad Jiu?",
  ui_story_5089_50890402_168_dialog_content = "*asiente*",
  ui_story_5089_50890402_169_dialog_content = "Una pena, pero hazlo a tu manera entonces. Todavía hay mucho que hacer en mi taller, así que ¡manos a la obra!",
  ui_story_5089_50890402_170_dialog_content = "... Espera. Había dos personas más viajando con la princesa.",
  ui_story_5089_50890402_171_dialog_content = "Sí, pero ese farsante de la adivinación huyó en el momento en que vio a tus hombres acercándose.",
  ui_story_5089_50890402_172_dialog_content = "En cuanto al Caelestite, es incapaz de lograr algo por sí mismo, especialmente en una tierra extranjera. ¿Por qué te preocupas tanto por ellos?",
  ui_story_5089_50890402_173_dialog_content = "Las órdenes de mi tío eran escoltarme de regreso a la capital, y a nadie más. ¿Estoy equivocado?",
  ui_story_5089_50890402_174_dialog_content = "No, Su Alteza... Por aquí, por favor.",
  ui_story_5089_50890402_175_dialog_content = "<color=#e8d9bb>La habitación vuelve al silencio.</color>",
  ui_story_5089_50890402_176_dialog_content = "<color=#e8d9bb>Pero esta vez, solo quedamos Jiu y yo.</color>",
  ui_story_5089_50890501_1_dialog_content = "... ¿Qué estaban pensando esos dos?!",
  ui_story_5089_50890501_2_dialog_content = "¡Solo estaba hablando de luchar por más tiempo, y ahora está entrando directamente en su trampa!",
  ui_story_5089_50890501_3_dialog_content = "¿Cómo se supone que debemos mantenernos a salvo cuando alguien como Zhui Hu está involucrado?!",
  ui_story_5089_50890501_4_dialog_content = "¡Nada de esto tiene sentido! Tú también lo crees, ¿no es así, Jiu?",
  ui_story_5089_50890501_5_dialog_content = "Yo... no sé.",
  ui_story_5089_50890501_6_dialog_content = "Parece que la princesa Dantang ya no confía en mí.",
  ui_story_5089_50890501_7_dialog_content = "Quizás ella tenía razón. Quizás he fallado en mis deberes.",
  ui_story_5089_50890501_8_dialog_content = "Pero ahora que ya no soy su guardia, no sé qué debe hacerse...",
  ui_story_5089_50890501_9_dialog_content = "¿De qué estás hablando? Todavía hay una cosa que absolutamente tiene que hacerse, ¿recuerdas?",
  ui_story_5089_50890501_10_dialog_content = "¿Qué?",
  ui_story_5089_50890501_11_dialog_content = "Dantang dijo que nos quedamos sin tiempo.",
  ui_story_5089_50890501_12_dialog_content = "Pero ella no tenía prisa cuando estábamos en el barco. Incluso dijo que podía entender tu vacilación.",
  ui_story_5089_50890501_13_dialog_content = "Pero después de anoche, ocurrió algo que la hizo cambiar su actitud.",
  ui_story_5089_50890501_14_dialog_content = "Sea lo que sea, debe tener algo que ver con esa muñeca.",
  ui_story_5089_50890501_15_dialog_content = "No solo eso, sino que dijo que me deja el resto a mí, aunque no explicó nada...",
  ui_story_5089_50890501_16_dialog_content = "Mi suposición es que necesitamos seguir buscando pistas que nos lleven a Xuan Ji. Una vez que la encontremos, estoy seguro de que entenderemos las cosas mucho mejor.",
  ui_story_5089_50890501_17_dialog_content = "Puedes discutir con Dantang todo lo que quieras una vez que lo hagamos, Jiu.",
  ui_story_5089_50890501_18_dialog_content = "¿Discutir... con Su Alteza? ¡J-Jamás haría algo tan presuntuoso!",
  ui_story_5089_50890501_19_dialog_content = "Pero ella claramente ya no es tu maestra, ¿verdad?",
  ui_story_5089_50890501_20_dialog_content = "Aún así...",
  ui_story_5089_50890501_21_dialog_content = "Sea cual sea la situación, ella tomó esta decisión por su cuenta sin consultar a ninguno de nosotros.",
  ui_story_5089_50890501_22_dialog_content = "Para ser honesto, incluso yo estoy un poco molesto con ella.",
  ui_story_5089_50890501_23_dialog_content = "No solo me dejó en un lugar del que casi no sé nada...",
  ui_story_5089_50890501_24_dialog_content = "Ella también me puso en una situación en la que tuve que ver a mis amigos arriesgar sus vidas por mí.",
  ui_story_5089_50890501_25_dialog_content = "Entonces, una vez que todo este lío esté resuelto, vamos a darle una pieza de nuestras mentes.",
  ui_story_5089_50890501_26_dialog_content = "Tendremos una agradable y larga conversación con la princesa sobre cómo tratar adecuadamente a sus amigos.",
  ui_story_5089_50890501_27_dialog_content = "PlayerName...",
  ui_story_5089_50890501_28_dialog_content = "Pero antes de hacer eso, ¿podrías prestarme tu apoyo por favor?",
  ui_story_5089_50890501_29_dialog_content = "Después de todo, solo hay tanto que puedo hacer por mi cuenta.",
  ui_story_5089_50890501_30_dialog_content = "Fui criado bajo el mando del Rey de Ye. Manejar una espada y seguir órdenes es todo lo que sé.",
  ui_story_5089_50890501_31_dialog_content = "Pero si mis habilidades pueden ser bien utilizadas, PlayerName, entonces por favor comándame como creas conveniente.",
  ui_story_5089_50890501_32_dialog_content = "Uh seguro, pero comencemos cambiando un poco esa mentalidad...",
  ui_story_5089_50890501_33_dialog_content = "Solo recuerda que somos amigos y siempre nos ayudamos mutuamente. Bastante simple, ¿verdad?",
  ui_story_5089_50890501_34_dialog_content = "... Nunca he tenido un amigo antes.",
  ui_story_5089_50890501_35_dialog_content = "No dejaría que Dantang te escuche decir eso, ¡o ella estará más enfadada que nosotros!",
  ui_story_5089_50890501_36_dialog_content = "¡Su Alteza Lady Dantang nació en una línea de sangre alta y noble! ¿Cómo podría ser amiga de alguien como yo?! Yo—",
  ui_story_5089_50890501_37_dialog_content = "Está bien, lo entiendo. La medicina aún no ha dejado de hacer efecto, así que solo dame tu mano y tómalo con calma.",
  ui_story_5089_50890501_38_dialog_content = "Vamos, nos dirigimos juntos a la capital.",
  ui_story_5089_50890502_1_dialog_content = "Rugido—",
  ui_story_5089_50890502_2_dialog_content = "Los espíritus malvados han sido purgados, PlayerName.",
  ui_story_5089_50890502_3_dialog_content = "No estamos tan lejos de la ciudad, ¿verdad?",
  ui_story_5089_50890502_4_dialog_content = "Hay muchos otros pueblos por aquí también, y la capital real está a menos de media hora de distancia.",
  ui_story_5089_50890502_6_dialog_content = "Bueno...",
  ui_story_5089_50890502_8_dialog_content = "Esperemos que sea solo una coincidencia. No tenemos tiempo para lidiar con más problemas ahora mismo... Sigamos adelante.",
  ui_story_5089_50890502_9_dialog_content = "Entendido.",
  ui_story_5089_50890502_10_dialog_content = "¿Hay algo por allí?",
  ui_story_5089_50890502_11_dialog_content = "?",
  ui_story_5089_50890502_12_dialog_content = "Lo siento, simplemente parece que tu mirada sigue desviándose hacia allá.",
  ui_story_5089_50890502_13_dialog_content = "Es el pueblo donde viví cuando era joven.",
  ui_story_5089_50890502_14_dialog_content = "¿Tu ciudad natal, eh? ¿Querías volver y echar un vistazo?",
  ui_story_5089_50890502_15_dialog_content = "No es necesario. Perdí a mi familia hace mucho tiempo y no estoy muy familiarizado con los otros aldeanos.",
  ui_story_5089_50890502_16_dialog_content = "Además, las dos cabañas restantes apenas pueden llamarse hogares ya.",
  ui_story_5089_50890502_17_dialog_content = "Tenemos asuntos más importantes a la mano.",
  ui_story_5089_50890502_18_dialog_content = "Mira allá, PlayerName. Ante ti está la capital del Reino Ye: la Ciudad de Jingliang.",
  ui_story_5089_50890502_19_dialog_content = "...",
  ui_story_5089_50890502_20_dialog_content = "(Pensé que después de ver el oro y el magatama del palacio del Reino de Ji, no me sorprendería nada más en Longzhou.)",
  ui_story_5089_50890502_21_dialog_content = "(Pero en la ciudad de Jingliang, máquinas con forma de dragón expulsan nubes de niebla desde los tejados, mientras que los fénix de cobre entregan mensajes por toda la ciudad.)",
  ui_story_5089_50890502_22_dialog_content = "<color=#e8d9bb>Las calles son amplias y bulliciosas mientras el humo y el fuego brotan de innumerables talleres.</color>",
  ui_story_5089_50890502_23_dialog_content = "<color=#e8d9bb>En lugar de adornos opulentos y belleza natural extravagante, la ciudad de Jingliang se caracteriza por tonos metálicos y la energía pulsante de la ingeniosa artesanía.</color>",
  ui_story_5089_50890502_24_dialog_content = "<color=#e8d9bb>*Retumbar*</color>",
  ui_story_5089_50890502_25_dialog_content = "¡¿Q-Qué fue eso?!",
  ui_story_5089_50890502_26_dialog_content = "Solo el sonido de un Transportador Huolong.",
  ui_story_5089_50890502_27_dialog_content = "PlayerName, ¿has notado algo inusual en las calles aquí?",
  ui_story_5089_50890502_28_dialog_content = "¿Estás hablando de las dos pistas de metal incrustadas en el suelo, verdad? Las he estado viendo de vez en cuando.",
  ui_story_5089_50890502_29_dialog_content = "Son realmente similares a algo que he visto antes...",
  ui_story_5089_50890502_30_dialog_content = "El Portador Huolong fue diseñado para la corte real hace muchos años por un gran inventor conocido como Señor Houfeng.",
  ui_story_5089_50890502_31_dialog_content = "Al combinar tanto las Artes de Fuerza de Agua como de Llama como su fuente de energía, el Transportista Huolong es capaz de transportar grandes cantidades de carga sin perder su movilidad.",
  ui_story_5089_50890502_32_dialog_content = "Sus principales inconvenientes son su excesivo consumo de energía y su limitación a pistas muy específicas.",
  ui_story_5089_50890502_33_dialog_content = "Como tal, la corte real se encarga de la mayoría de su planificación e infraestructura, mientras que los propietarios de los talleres más grandes apoyan su construcción a través de la financiación.",
  ui_story_5089_50890502_34_dialog_content = "A cambio de ayudar con las pistas del Transportista Huolong, los dueños de los talleres también tienen prioridad al transportar bienes y materiales.",
  ui_story_5089_50890502_35_dialog_content = "Justo como pensaba... ¿Es un tren de vapor, no es así?!",
  ui_story_5089_50890502_36_dialog_content = "¿Un \"tren de vapor\"? ¿Qué es eso?",
  ui_story_5089_50890502_37_dialog_content = "Piénsalo como la versión propia de Astra del Portador Huolong. ¡Estoy impresionado de que el Señor Houfeng haya podido inventar algo así también!",
  ui_story_5089_50890502_38_dialog_content = "La princesa Dantang dijo algo similar en el pasado.",
  ui_story_5089_50890502_39_dialog_content = "Ella cree que con sus creaciones, sus talentos deben rivalizar con los de Lady Xuan Ji.",
  ui_story_5089_50890502_40_dialog_content = "En un momento, dijeron que estaba desarrollando algún tipo de cometa gigante que podía transportar personas hacia y desde tierras lejanas.",
  ui_story_5089_50890502_41_dialog_content = "Desafortunadamente, debido a las luchas políticas dentro del reino, desapareció sin dejar rastro y su investigación finalmente se detuvo.",
  ui_story_5089_50890502_42_dialog_content = "Es una lástima. Estoy seguro de que habría sido tan impresionante como su Portador Huolong, si no más.",
  ui_story_5089_50890502_43_dialog_content = "Parece que sabes mucho sobre esto, Jiu. ¿No pensé que estuvieras interesado en este tipo de cosas?",
  ui_story_5089_50890502_44_dialog_content = "Es solo porque Su Alteza me habló tanto de eso.",
  ui_story_5089_50890502_45_dialog_content = "También lamentó ser demasiado joven e ingenua en aquel momento, de lo contrario, habría encontrado una forma de retener a un inventor tan talentoso.",
  ui_story_5089_50890502_46_dialog_content = "Je, eso definitivamente suena como Dantang.",
  ui_story_5089_50890502_47_dialog_content = "Bien, Jiu, hagamos nuestro mejor esfuerzo para encontrar una manera de hacerlo.",
  ui_story_5089_50890502_48_dialog_content = "Necesitamos evitar que el Reino Ye pierda a un brillante inventor como Xuan Ji y a su diligente Princesa Zhuohua.",
  ui_story_5089_50890502_49_dialog_content = "Primero, debemos averiguar una forma de encontrarnos con ellos...",
  ui_story_5089_50890502_50_dialog_content = "Los criminales que los guardias personales del rey detienen normalmente son retenidos en la Prisión del Cielo en el borde exterior del palacio.",
  ui_story_5089_50890502_51_dialog_content = "Aunque esté protegida por una legión de soldados, incluso si caigo, estoy seguro de que tendrás éxito en rescatar a Lady Xuan Ji de su encarcelamiento, PlayerName.",
  ui_story_5089_50890502_52_dialog_content = "¡¿P-Por qué estamos comenzando con la estrategia más agresiva?!",
  ui_story_5089_50890502_53_dialog_content = "PlayerName, cuando pediste mi ayuda, ¿no querías que me convirtiera en tu espada?",
  ui_story_5089_50890502_54_dialog_content = "¡No intento convertirme en enemigo del tribunal, Jiu! ¡Y ciertamente no planeo enviarte a morir!",
  ui_story_5089_50890502_55_dialog_content = "Tiene que haber otra manera. Vamos a revisar esa Prisión del Cielo primero.",
  ui_story_5089_50890502_56_dialog_content = "Si lastiman a Xuan Ji de alguna manera... Ese será el momento en que utilizaremos nuestro último recurso.",
  ui_story_5089_50890502_57_dialog_content = "He querido preguntar, Jiu. ¿Muchas personas te reconocen aquí en la ciudad de Jingliang?",
  ui_story_5089_50890502_58_dialog_content = "Quizás. Como guardia del rey, le serví principalmente en las sombras y solo interactué con mis compañeros guardias según fuera necesario.",
  ui_story_5089_50890502_59_dialog_content = "Algunas personas pueden reconocerme por mi máscara, pero no mucho más. De hecho, puede que ni siquiera sepan si soy un hombre o una mujer.",
  ui_story_5089_50890502_60_dialog_content = "Después de todo, solo se refieren a mí como \"el demonio enmascarado\" cuando hablan a mis espaldas.",
  ui_story_5089_50890502_61_dialog_content = "Pero si crees que ayudará, PlayerName...",
  ui_story_5089_50890502_62_dialog_content = "Supongo que esto tendrá que hacer.",
  ui_story_5089_50890502_63_dialog_content = "Uh, seguro... Por alguna razón, sin embargo, siento que te destacas aún más ahora.",
  ui_story_5089_50890502_64_dialog_content = "Como pensé, mi cara realmente es una vista insoportable... Voy a buscar algo para cubrirla de inmediato.",
  ui_story_5089_50890502_65_dialog_content = "¡E-Eso no es lo que quise decir! ¿De dónde sacaste esa idea de todos modos?! La verdad es que, en realidad te ves muy... Uh...",
  ui_story_5089_50890502_66_dialog_content = "¡Realmente hermoso!",
  ui_story_5089_50890502_67_dialog_content = "?",
  ui_story_5089_50890502_68_dialog_content = "Eh, no importa. No hay tiempo que perder, así que sigamos adelante.",
  ui_story_5089_50890502_69_dialog_content = "Este lugar está bajo la jurisdicción del palacio real. Si no tienes ningún negocio aquí, entonces vete de inmediato.",
  ui_story_5089_50890502_70_dialog_content = "Supongo que el enfoque directo es imposible después de todo.",
  ui_story_5089_50890502_71_dialog_content = "Entonces permítame infiltrarme en las instalaciones...",
  ui_story_5089_50890502_72_dialog_content = "¡V-Vamos a guardar eso para el final!",
  ui_story_5089_50890502_73_dialog_content = "Es cierto, todavía tengo el pájaro mecánico de Xuan Ji conmigo. Tal vez pueda usarlo para comunicarme con ella si podemos distraer a los soldados.",
  ui_story_5089_50890502_74_dialog_content = "Entonces permíteme distraer a los soldados—",
  ui_story_5089_50890502_75_dialog_content = "¡Esperar—UH oh!",
  ui_story_5089_50890502_76_dialog_content = "<color=#e8d9bb>Para su sorpresa, el pájaro mecánico de repente cobra vida y emprende el vuelo.</color>",
  ui_story_5089_50890502_77_dialog_content = "<color=#e8d9bb>Como si siguiera un programa predeterminado, se dirige directamente a las puertas del palacio en busca de Xuan Ji...</color>",
  ui_story_5089_50890502_78_dialog_content = "Estamos acabados... ¿Eh?",
  ui_story_5089_50890502_79_dialog_content = "<color=#e8d9bb>Un rayo de luz dorada destella desde un origen desconocido.</color>",
  ui_story_5089_50890502_80_dialog_content = "<color=#e8d9bb>Los dos soldados, aparentemente ajenos a ello, permiten que el pájaro mecánico pase por las puertas.</color>",
  ui_story_5089_50890502_81_dialog_content = "... ¿Todavía necesitas que distraiga a los soldados?",
  ui_story_5089_50890502_82_dialog_content = "Bueno...",
  ui_story_5089_50890502_83_dialog_content = "<color=#e8d9bb>De repente, se puede escuchar un ruido débil más allá de las puertas del palacio.</color>",
  ui_story_5089_50890502_84_dialog_content = "Perdóname, pero ¿puedo preguntar si un distinguido invitado está esperando afuera?",
  ui_story_5089_50890502_85_dialog_content = "Eh, ¿quién eres tú?",
  ui_story_5089_50890502_86_dialog_content = "Solo una humilde sirvienta, señor. Ahora, por favor sígame.",
  ui_story_5089_50890502_87_dialog_content = "La señora Xuan Ji te ha estado esperando.",
  ui_story_5089_50890502_88_dialog_content = "Bienvenido, PlayerName. No nos hemos visto desde la primavera pasada, ¿verdad?",
  ui_story_5089_50890502_89_dialog_content = "Y tú también, Jiu. ¿Has estado bien?",
  ui_story_5089_50890502_90_dialog_content = "¡Es el verdadero Xuan Ji! ¿Estás bien? No te lastimaron, ¿verdad?!",
  ui_story_5089_50890502_91_dialog_content = "Por supuesto que no—Uf, estos rieles son una molestia. Solo un momento, por favor.",
  ui_story_5089_50890502_92_dialog_content = "... ¿Eh?",
  ui_story_5089_50890502_93_dialog_content = "¡Ven, toma asiento! ¿Aún no has almorzado, verdad? Si no, llegaste en el momento perfecto!",
  ui_story_5089_50890502_94_dialog_content = "Fixit, Crafty, vayan a ver qué tienen hoy en las cocinas del palacio.",
  ui_story_5089_50890502_95_dialog_content = "Gané una apuesta contra Jie Gaoqing, y él prometió traerme un pescado fresco hoy.",
  ui_story_5089_50890502_96_dialog_content = "Dile a los cocineros que lo cocinen al vapor y lo sirvan con salsa de frijoles negros.",
  ui_story_5089_50890502_97_dialog_content = "Como desees.",
  ui_story_5089_50890502_98_dialog_content = "Uh, Xuan Ji...? ¿Qué está pasando aquí?",
  ui_story_5089_50890502_99_dialog_content = "Oh no te preocupes, la comida del palacio es perfectamente deliciosa. Solo es difícil conseguir algo tan fresco por aquí, eso es todo.",
  ui_story_5089_50890502_100_dialog_content = "...",
  ui_story_5089_50890502_101_dialog_content = "De repente, siento que nuestra determinación para sacarte de la prisión fue una broma total.",
  ui_story_5089_50890502_102_dialog_content = "¿Te arrestaron en primer lugar? ¿Es esto siquiera una prisión, para el caso?!",
  ui_story_5089_50890502_103_dialog_content = "¡Jajaja, por supuesto que lo es! ¿No puedes ver lo vacía que está mi calabaza de vino?",
  ui_story_5089_50890502_104_dialog_content = "Pero recuerda, una vez fui un estimado miembro de la corte real. Todavía tengo muchos amigos en el interior, incluyendo algunos colegas que se preocupan profundamente por mi seguridad.",
  ui_story_5089_50890502_105_dialog_content = "Además, no importa cuánto pueda resentirme el rey, castigarme sin condenarme formalmente primero no sería correcto.",
  ui_story_5089_50890502_106_dialog_content = "Desafortunadamente, como todavía estoy detenido como delincuente, no me proporcionarán nada más fuerte que el té simple. ¡Espero que no te importe!",
  ui_story_5089_50890502_107_dialog_content = "Señorita Jiu, PlayerName.",
  ui_story_5089_50890502_108_dialog_content = "El viaje hasta aquí debe haber sido bastante difícil. Permíteme levantar esta taza de té en tu honor.",
  ui_story_5089_50890502_109_dialog_content = "Gracias por tu amable consideración.",
  ui_story_5089_50890502_110_dialog_content = "Nunca esperé que el mayor tesoro de mi viaje a Astra no fuera la Llama Zhuyin, sino los amigos que hice en el camino.",
  ui_story_5089_50890502_111_dialog_content = "N-No hay necesidad de ser tan formal, Xuan Ji...",
  ui_story_5089_50890502_112_dialog_content = "¡Pero eso me recuerda! ¿Sabes quién tiene la Llama Zhuyin ahora? Porque Dantang es—",
  ui_story_5089_50890502_113_dialog_content = "Shh.",
  ui_story_5089_50890502_114_dialog_content = "No olvides, ahora solo soy un prisionero. No tiene sentido contarme sobre el mundo más allá de mi celda.",
  ui_story_5089_50890502_115_dialog_content = "Y además, tengo todo lo que podría desear aquí. Es tan cómodo que casi podría olvidarme de los problemas de mi vida.",
  ui_story_5089_50890502_116_dialog_content = "¿Por qué me importaría cualquier otra cosa?",
  ui_story_5089_50890502_117_dialog_content = "Mentiroso.",
  ui_story_5089_50890502_118_dialog_content = "¿Oh?",
  ui_story_5089_50890502_119_dialog_content = "No hay ni una sola pieza de maquinaria aquí, ¿verdad?",
  ui_story_5089_50890502_120_dialog_content = "¿Quién en su sano juicio creería que el famoso Xuan Ji encontraría este lugar siquiera remotamente cómodo?",
  ui_story_5089_50890502_121_dialog_content = "Jajaja, tan directo como siempre, PlayerName.",
  ui_story_5089_50890502_122_dialog_content = "Entonces por favor escucha atentamente.",
  ui_story_5089_50890502_123_dialog_content = "El rey personalmente ordenó mi captura, y ahora mi destino está completamente en sus manos.",
  ui_story_5089_50890502_124_dialog_content = "Incluso si lograra escapar gracias a la superior habilidad marcial de la señorita Jiu, mi nombre aún estaría manchado y mis palabras nunca serían aceptadas.",
  ui_story_5089_50890502_125_dialog_content = "Pero tú debes saber algo sobre todo esto, ¿verdad? ¿Qué debemos hacer ahora?",
  ui_story_5089_50890502_126_dialog_content = "Ahora no es el momento de considerar \"qué hacer\".",
  ui_story_5089_50890502_127_dialog_content = "Aunque no es mi lugar comentar sobre asuntos externos, sí serví como estratega durante un tiempo, por lo que puedo compartir algunas de mis experiencias contigo.",
  ui_story_5089_50890502_128_dialog_content = "Por ejemplo, si deseas lograr algo pero careces de la fuerza y visión para hacerlo, debes confiar en la estrategia y tácticas para avanzar.",
  ui_story_5089_50890502_129_dialog_content = "La mejor opción siempre será moverse con propósito y ganar impulso.",
  ui_story_5089_50890502_130_dialog_content = "Muévete con el flujo de tus circunstancias, y los cielos guiarán tu camino.",
  ui_story_5089_50890502_131_dialog_content = "Pero recuerda, primero debes ampliar tus horizontes para discernir la dirección de la ola inminente.",
  ui_story_5089_50890502_132_dialog_content = "Solo entonces podrás ganar impulso cuando se presente la oportunidad.",
  ui_story_5089_50890502_133_dialog_content = "Al igual que una criatura de relojería, incluso el más mínimo giro de un engranaje puede poner en movimiento todo el cuerpo.",
  ui_story_5089_50890502_134_dialog_content = "E incluso las acciones más simples requieren la coordinación de varias partes.",
  ui_story_5089_50890502_135_dialog_content = "Nunca sabes qué pequeño componente podría fallar, causando el colapso de toda la máquina.",
  ui_story_5089_50890502_136_dialog_content = "Pero... No sé ni dónde buscar.",
  ui_story_5089_50890502_137_dialog_content = "Entonces, comencemos echando un vistazo a nuestro alrededor, ¿de acuerdo?",
  ui_story_5089_50890502_138_dialog_content = "Por ejemplo, ahora mismo solo son ustedes dos los que están frente a mí. ¿No parece ya una parte deliberada del plan de alguien más?",
  ui_story_5089_50890502_139_dialog_content = "!",
  ui_story_5089_50890502_140_dialog_content = "Además, conocemos a la Srta. Jiu aquí desde hace bastante tiempo...",
  ui_story_5089_50890502_141_dialog_content = "Pero, ¿sabes realmente de dónde vino ella?",
  ui_story_5089_50890502_142_dialog_content = "Señora Xuan Ji, los platos están listos.",
  ui_story_5089_50890502_143_dialog_content = "Los guardias del rey aparecieron de repente justo ahora, afirmando que desean llevarte para interrogarte.",
  ui_story_5089_50890502_144_dialog_content = "Crafty está obstaculizándolos mientras hablamos, pero me temo que no podrá mantenerlos alejados por mucho más tiempo...",
  ui_story_5089_50890502_145_dialog_content = "Entiendo.",
  ui_story_5089_50890502_146_dialog_content = "Un interrogatorio justo cuando estábamos a punto de almorzar. ¡Su timing no podría ser más terrible!",
  ui_story_5089_50890502_147_dialog_content = "Gracias a ellos, PlayerName y la señorita Jiu tienen que perderse nuestro delicioso pescado al vapor.",
  ui_story_5089_50890502_148_dialog_content = "Ah, pero supongo que así es la vida de un prisionero.",
  ui_story_5089_50890502_149_dialog_content = "... ¿Por qué no vienes simplemente con nosotros, Xuan Ji?",
  ui_story_5089_50890502_150_dialog_content = "Lo vimos con nuestros propios ojos antes. Los guardias del rey también están en liga con Zhui Hu, y ellos—",
  ui_story_5089_50890502_151_dialog_content = "Fixit, por favor, ve a nuestros invitados fuera.",
  ui_story_5089_50890502_152_dialog_content = "Xuan Ji!",
  ui_story_5089_50890502_153_dialog_content = "Eso es suficiente, ahora vete. Cada uno tenemos nuestros propios asuntos que atender, ¿no es así?",
  ui_story_5089_50890502_154_dialog_content = "Tengo completa confianza en ti, PlayerName.",
  ui_story_5089_50890502_155_dialog_content = "Definitivamente encontrarás tu impulso pronto.",
  ui_story_5089_50890601_1_dialog_content = "<color=#e8d9bb>Fixit se va después de escoltarnos fuera de la ciudad en un carruaje.</color>",
  ui_story_5089_50890601_2_dialog_content = "Parece que solo somos nosotros dos de nuevo, Jiu.",
  ui_story_5089_50890601_3_dialog_content = "Xuan Ji dijo tanto, pero ¿qué significaba todo eso...?",
  ui_story_5089_50890601_4_dialog_content = "<color=#e8d9bb>Gruñido-</color>",
  ui_story_5089_50890601_5_dialog_content = "...",
  ui_story_5089_50890601_6_dialog_content = "Ahora que lo pienso, no hemos comido nada hoy.",
  ui_story_5089_50890601_7_dialog_content = "Voy a preguntar si alguno de los aldeanos estaría dispuesto a alimentarnos a cambio de un pago.",
  ui_story_5089_50890601_8_dialog_content = "Por favor espera aquí, PlayerName.",
  ui_story_5089_50890601_9_dialog_content = "Okey... ¿Eh?",
  ui_story_5089_50890601_10_dialog_content = "¿Realmente hay un pueblo por aquí?",
  ui_story_5089_50890601_11_dialog_content = "El arroz ha estado vendiendo a precios más altos últimamente, lo cual es poco probable por estas partes, así que vendí todo mi arroz a algunos comerciantes que pasaban del Reino Ji.",
  ui_story_5089_50890601_12_dialog_content = "Lamentablemente, solo tengo un poco de gachas hechas con el arroz integral añejo de nuestra familia. No es mucho, pero espero que sea de tu agrado...",
  ui_story_5089_50890601_13_dialog_content = "¡No nos importa en absoluto! No hemos comido en todo el día, así que la comida es una bendición.",
  ui_story_5089_50890601_14_dialog_content = "Perdón, ¿pero hay alguna razón por la que no estás comiendo? ¿Te gustaría algo más para acompañar tu gachas?",
  ui_story_5089_50890601_15_dialog_content = "No, gracias. No necesito comida en este momento.",
  ui_story_5089_50890601_16_dialog_content = "¡Ahora, ahora, eso no servirá! Tu cuerpo no podrá seguir el ritmo sin una comida decente, ¿sabes?",
  ui_story_5089_50890601_17_dialog_content = "Como dije, no necesito sustento ahora. He pasado días sin comida durante la misión, lo cual nunca ha afectado mi esgrima.",
  ui_story_5089_50890601_18_dialog_content = "Además, preferiría no asustar a nadie con mi apariencia.",
  ui_story_5089_50890601_19_dialog_content = "Sobre eso...",
  ui_story_5089_50890601_20_dialog_content = "Tu máscara y tu forma de hablar son un poco familiares... ¡Espera! Jiu-mei... ¿Eres tú?",
  ui_story_5089_50890601_21_dialog_content = "\"¿Jiu-mei\"?",
  ui_story_5089_50890601_22_dialog_content = "...Sí.",
  ui_story_5089_50890601_23_dialog_content = "Ha pasado algún tiempo, tío Li.",
  ui_story_5089_50890601_24_dialog_content = "¡Santo cielo! ¡No puedo creer que todavía estás vivo!",
  ui_story_5089_50890601_25_dialog_content = "¡Después de que tus padres murieron tan trágicamente ese año, incluso las autoridades estaban convencidas de que habías muerto junto a ellos!",
  ui_story_5089_50890601_26_dialog_content = "¡Eras solo un niño en aquel entonces! Vaya, cómo has crecido, Jiu-mei!",
  ui_story_5089_50890601_27_dialog_content = "¿Cómo has estado todos estos años, mi chica...?",
  ui_story_5089_50890601_28_dialog_content = "He estado bien, tío Li. Un hombre amable me acogió y me dio una buena vida.",
  ui_story_5089_50890601_29_dialog_content = "¡Bueno, bueno! Escuchar eso hace que mi corazón se llene de alegría!",
  ui_story_5089_50890601_30_dialog_content = "¡Ven, siéntate y toma un poco de gachas! Espera aquí mientras el Tío Li te trae algunos vegetales encurtidos!",
  ui_story_5089_50890601_31_dialog_content = "Este debe ser tu ciudad natal, ¿verdad, Jiu?",
  ui_story_5089_50890601_32_dialog_content = "En cierto modo, sí.",
  ui_story_5089_50890601_33_dialog_content = "Mi familia originalmente vivía en un pueblo aún más remoto. Nos mudamos aquí para evitar un desastre.",
  ui_story_5089_50890601_34_dialog_content = "¿Un desastre?",
  ui_story_5089_50890601_35_dialog_content = "Sí. No tenía ni diez años entonces, así que no recuerdo muchos detalles.",
  ui_story_5089_50890601_36_dialog_content = "Creo que a cierto noble le gustó mi rostro y quería comprarme para mantenerme como servidor.",
  ui_story_5089_50890601_37_dialog_content = "Pero cuando mis padres se negaron, él y sus hombres comenzaron a acosarnos en cada momento. Finalmente, huyimos a este lugar.",
  ui_story_5089_50890601_38_dialog_content = "Después de eso, mis padres me obligaron a usar una máscara y me hicieron decirle a todos que parecía un demonio, indigno de ser visto por los demás.",
  ui_story_5089_50890601_39_dialog_content = "Eso es increíble...",
  ui_story_5089_50890601_40_dialog_content = "No me importó usarlo. Después de todo, mi rostro causó sufrimiento a mi familia, y nunca he sido de los que hablan con los demás.",
  ui_story_5089_50890601_41_dialog_content = "Si acaso, mis padres sintieron más remordimiento que yo.",
  ui_story_5089_50890601_42_dialog_content = "Siempre que los otros niños del pueblo me llamaban monstruo, mi madre me sostenía y me cantaba.",
  ui_story_5089_50890601_43_dialog_content = "Y mi papá me daba los melones dulces que él mismo no podía soportar comer.",
  ui_story_5089_50890601_44_dialog_content = "Entonces esa canción de cuna que cantaste antes... Fue hecha solo para ti, ¿no es así? Tus padres realmente debieron amarte mucho.",
  ui_story_5089_50890601_45_dialog_content = "¿Puedo preguntar qué les pasó a ellos?",
  ui_story_5089_50890601_46_dialog_content = "Hay una montaña justo al oeste de este pueblo. Lo notaste antes, ¿no PlayerName?",
  ui_story_5089_50890601_47_dialog_content = "Uh... ¿Cuál de nuevo?",
  ui_story_5089_50890601_48_dialog_content = "Ven. Hablaremos afuera.",
  ui_story_5089_50890601_49_dialog_content = "Jiu-mei... ¿Tú y tu amigo se van tan pronto?",
  ui_story_5089_50890601_50_dialog_content = "Sí, Tío Li. Nos gustaría visitar la mina por ahí.",
  ui_story_5089_50890601_51_dialog_content = "Muy bien, pero debes saber que la mina se agotó hace solo unos años, y los trabajadores también se han ido todos.",
  ui_story_5089_50890601_52_dialog_content = "Se construyó un gran taller en ese terreno después, pero parece que no se produjo nada notable allí.",
  ui_story_5089_50890601_53_dialog_content = "Uno de los hombres más jóvenes de nuestro pueblo fue allí en busca de trabajo, pero no había ni una sola alma allí. Por lo que sabemos, el lugar ha estado abandonado durante algún tiempo.",
  ui_story_5089_50890601_54_dialog_content = "Una cosa más, Jiu-mei...",
  ui_story_5089_50890601_55_dialog_content = "¿Si?",
  ui_story_5089_50890601_56_dialog_content = "No es nada terriblemente importante... Es solo que todos hemos estado luchando durante los últimos años.",
  ui_story_5089_50890601_57_dialog_content = "Pero tuviste la suerte de encontrar una buena vida, así que por favor... Vive bien y sé feliz.",
  ui_story_5089_50890601_58_dialog_content = "Si tus padres pudieran verte ahora, estoy seguro de que también estarían muy contentos contigo.",
  ui_story_5089_50890601_59_dialog_content = "... Entendido.",
  ui_story_5089_50890601_60_dialog_content = "¿Es esa la montaña que mencionaste antes, Jiu?",
  ui_story_5089_50890601_61_dialog_content = "Sí. Antes de que nuestro rey ascendiera al trono, todas estas tierras, incluyendo la mía, eran su dominio.",
  ui_story_5089_50890601_62_dialog_content = "Estableció un campo de trabajo al pie de la montaña, donde pondría a trabajar a los refugiados y prisioneros.",
  ui_story_5089_50890601_63_dialog_content = "Un día, dos de los sirvientes del rey estaban escoltando a un reo condenado a muerte al campo de trabajo, pero se volvieron perezosos y decidieron alojarse en nuestra casa cercana.",
  ui_story_5089_50890601_64_dialog_content = "Mis padres fueron obligados a servirles todo el día e intercambiar nuestras preciadas reservas de grano por su vino. Incluso tuvieron que entregar comida a ese prisionero.",
  ui_story_5089_50890601_65_dialog_content = "En su estupor ebrio, insistieron en ver mi verdadero rostro. Forzaron la remoción de mi máscara y amenazaron con hacerme daño.",
  ui_story_5089_50890601_66_dialog_content = "Fue entonces cuando un misterioso transeúnte derribó la pesada valla detrás de mis atacantes, atrapándolos y matándolos en el proceso.",
  ui_story_5089_50890601_67_dialog_content = "Se mantuvo oculto en las sombras todo el tiempo, probablemente para evitar ser implicado en sus muertes. Pero no tuve tiempo para pensar en él o en sus acciones.",
  ui_story_5089_50890601_68_dialog_content = "Todo lo que sabía era que había causado problemas a mis padres de nuevo, así que volví para buscarlos...",
  ui_story_5089_50890601_69_dialog_content = "Pero cuando volví, todo lo que encontré fueron sus cuerpos yaciendo en un charco de sangre.",
  ui_story_5089_50890601_70_dialog_content = "Junto a ellos había un tazón de gachas humeantes derramado. El prisionero ya había roto sus cadenas y escapado hace mucho tiempo.",
  ui_story_5089_50890601_71_dialog_content = "A veces, me pregunto si hay algo de verdad en el dicho, \"El destino hace tontos a todos nosotros.\"",
  ui_story_5089_50890601_72_dialog_content = "Nunca he tenido miedo. Incluso cuando otros me llamaban monstruo o demonio, o me sometían a insultos y lesiones, nunca les tuve miedo.",
  ui_story_5089_50890601_73_dialog_content = "Pero ese día, cuando vi los cuerpos sin vida de mis padres... Ese fue el día que realmente sentí miedo.",
  ui_story_5089_50890601_74_dialog_content = "Pero solo esa vez, mi mamá no pudo estar allí para cantarme su canción.",
  ui_story_5089_50890601_75_dialog_content = "Perdóname, he dicho demasiado. De ahora en adelante, yo—",
  ui_story_5089_50890601_76_dialog_content = "Jiu!",
  ui_story_5089_50890601_77_dialog_content = "?",
  ui_story_5089_50890601_78_dialog_content = "No tienes que contarme ninguna de estas cosas, especialmente si no quieres.",
  ui_story_5089_50890601_79_dialog_content = "No tiene nada que ver con si quiero o no contarte.",
  ui_story_5089_50890601_80_dialog_content = "Todavía no entiendo el significado de las palabras de Lady Xuan Ji, pero sé que cada palabra que dice lleva su propia importancia.",
  ui_story_5089_50890601_81_dialog_content = "Y dado que mencionó mis orígenes, pensé que era apropiado compartirlos contigo.",
  ui_story_5089_50890601_82_dialog_content = "Los detalles de mi vida son triviales en el mejor de los casos, pero les agradezco a todos por escucharlos, PlayerName.",
  ui_story_5089_50890601_83_dialog_content = "... ¿Cómo podrías decir eso sobre ti mismo, Jiu?",
  ui_story_5089_50890601_84_dialog_content = "Si realmente no te importaba...",
  ui_story_5089_50890601_85_dialog_content = "¡No habrías recordado algo tan pequeño como ese tazón de gachas derramadas en el suelo!",
  ui_story_5089_50890601_86_dialog_content = "¿Estás enojado, PlayerName?",
  ui_story_5089_50890601_87_dialog_content = "¡Me sorprende que pudieras decirlo!",
  ui_story_5089_50890601_88_dialog_content = "¡Sí, claro que estoy enfadado!",
  ui_story_5089_50890601_89_dialog_content = "Perdóname... Sé que no es la historia más agradable para escuchar.",
  ui_story_5089_50890601_90_dialog_content = "Pero si es un consuelo... Mi venganza llegó poco después.",
  ui_story_5089_50890601_91_dialog_content = "Después de encontrar a mis padres así, tomé la daga de uno de los oficiales muertos y cacé al prisionero durante un día y una noche.",
  ui_story_5089_50890601_92_dialog_content = "Para mi sorpresa, viajó directamente al campo de trabajo de la mina e intentó asesinar a nuestro señor, el hombre que más tarde se convertiría en el Rey de Ye.",
  ui_story_5089_50890601_93_dialog_content = "Para cuando lo alcancé, la justicia ya había sido servida.",
  ui_story_5089_50890601_94_dialog_content = "Su Alteza preguntó mis razones para estar allí. Después de conocer la desaparición de mi familia, me acogió y me otorgó el nombre Jiu.",
  ui_story_5089_50890601_95_dialog_content = "No solo se vengó por mí, sino que también me permitió instalarme en su mansión. Allí, me enseñó a leer y escribir, y me fortaleció a través del entrenamiento en artes marciales.",
  ui_story_5089_50890601_96_dialog_content = "Por esta razón, le debo mi vida y haré cualquier cosa para devolverle su amabilidad.",
  ui_story_5089_50890601_97_dialog_content = "Más allá de esta deuda de gratitud, no tengo otra razón para empuñar mi espada... O para seguir viviendo, en todo caso.",
  ui_story_5089_50890601_98_dialog_content = "De eso no es de lo que estoy hablando, Jiu.",
  ui_story_5089_50890601_99_dialog_content = "Todo lo que haces es hablar sobre venganza y gratitud.",
  ui_story_5089_50890601_100_dialog_content = "¿Pero qué hay de tus propios sentimientos? ¿Qué hay de las cosas que quieres hacer?",
  ui_story_5089_50890601_101_dialog_content = "Ya sea que estuvieras recibiendo un golpe por mí antes, sugiriendo despreocupadamente asaltar la prisión, o pensando que tus sentimientos no importan... Siempre es lo mismo contigo.",
  ui_story_5089_50890601_102_dialog_content = "¿Por qué sigues dando por sentado tus sacrificios, como si no importaran?!",
  ui_story_5089_50890601_103_dialog_content = "Puedes ser fuerte pero aún así estás hecho de carne y sangre. Puedes lastimarte, sentir dolor, estar triste y, si no tienes cuidado, podrías morir realmente.",
  ui_story_5089_50890601_104_dialog_content = "No es que no reconozca eso. Es solo que por el bien de mis misiones...",
  ui_story_5089_50890601_105_dialog_content = "Está bien, lo entiendo. Creo que estoy empezando a entender cómo hablar contigo.",
  ui_story_5089_50890601_106_dialog_content = "Y ahora que he experimentado personalmente lo terco que puedes ser, siento que también le debo una disculpa a Dantang.",
  ui_story_5089_50890601_107_dialog_content = "Déjame poner esto de una manera que puedas entender.",
  ui_story_5089_50890601_108_dialog_content = "?",
  ui_story_5089_50890601_109_dialog_content = "Francamente, tu imprudencia y disposición para sacrificarte siempre me asustan.",
  ui_story_5089_50890601_110_dialog_content = "Los Caelestites son una raza amable y pacífica. No queremos ver derramamiento de sangre, y especialmente no queremos ver a nuestros amigos lastimados.",
  ui_story_5089_50890601_111_dialog_content = "Quiero devolverte a Dantang sano y salvo.",
  ui_story_5089_50890601_112_dialog_content = "Entonces, si las órdenes son lo único que escucharás, entonces tengo una orden solo para ti.",
  ui_story_5089_50890601_113_dialog_content = "\"No importa tu situación, siempre valora tu vida y protégete a ti mismo primero.\"",
  ui_story_5089_50890601_114_dialog_content = "Yo...",
  ui_story_5089_50890601_115_dialog_content = "No estoy buscando excusas tampoco. Un simple sí será suficiente.",
  ui_story_5089_50890601_116_dialog_content = "Sí. Recordaré tus órdenes.",
  ui_story_5089_50890601_117_dialog_content = "¿Pero hay un límite de tiempo para estos pedidos?",
  ui_story_5089_50890601_118_dialog_content = "Realmente no lo entiendes, ¿verdad?",
  ui_story_5089_50890601_119_dialog_content = "No importa. Si realmente necesitas un límite de tiempo, entonces...",
  ui_story_5089_50890601_120_dialog_content = "Tus órdenes no terminarán hasta el día en que puedas blandir tu espada sin hacerlo por gratitud o venganza. ¿Qué te parece eso?",
  ui_story_5089_50890601_121_dialog_content = "Oh...",
  ui_story_5089_50890601_122_dialog_content = "No voy a cambiar ninguna parte de tus órdenes, si eso es lo que estás a punto de preguntar.",
  ui_story_5089_50890601_123_dialog_content = "No, es solo que mi maestro me dijo lo mismo una vez.",
  ui_story_5089_50890601_124_dialog_content = "¿Tu \"maestro\"?",
  ui_story_5089_50890601_125_dialog_content = "El mejor espadachín del mundo y el hombre que me enseñó el camino de la espada.",
  ui_story_5089_50890601_126_dialog_content = "Aunque se negó a aceptar a alguien tan terco como yo como un discípulo formal, aún me enseñó muchas cosas.",
  ui_story_5089_50890601_127_dialog_content = "Pero había una cosa que no me enseñaría: el Filo Atronador, una técnica de la que se rumorea tiene el poder de partir montañas y mares.",
  ui_story_5089_50890601_128_dialog_content = "Afirmó que no era una técnica de espada real, por lo que no podía enseñármela.",
  ui_story_5089_50890601_129_dialog_content = "Solo cuando pueda manejar mi espada ni por venganza ni por gratitud, seré digno de aprenderla.",
  ui_story_5089_50890601_130_dialog_content = "Eso es raro. No veo ninguna otra pista por aquí—¡Urk!",
  ui_story_5089_50890601_131_dialog_content = "Perdóname, PlayerName, pero no estamos solos.",
  ui_story_5089_50890601_132_dialog_content = "Mmf... ¿Ese es Zhui Hu?!",
  ui_story_5089_50890601_133_dialog_content = "¿Qué podría estar haciendo ella aquí...? Vamos Jiu, ¡sigámosla!",
  ui_story_5089_50890601_134_dialog_content = "Ella entró en ese taller, ¿verdad? Vamos—",
  ui_story_5089_50890601_135_dialog_content = "Crujir—",
  ui_story_5089_50890601_136_dialog_content = "¡Cuidado, Jiu! ¡Hay bestias mecánicas vigilando el taller!",
  ui_story_5089_50890602_1_dialog_content = "¿Por qué un taller abandonado necesitaría tanta protección?",
  ui_story_5089_50890602_2_dialog_content = "Hay muchas señales de actividad reciente. No solo eso, sino que Zhui Hu también apareció aquí.",
  ui_story_5089_50890602_3_dialog_content = "Si tuviera que adivinar, probablemente esta es una fortaleza del Jinete del Destino.",
  ui_story_5089_50890602_4_dialog_content = "Entonces tendremos que ser extremadamente cuidadosos. Aparte de su enorme e intrincado interior, parte del taller también se encuentra ubicado profundamente bajo tierra.",
  ui_story_5089_50890602_5_dialog_content = "Una vez dentro, no podemos permitirnos perder el camino.",
  ui_story_5089_50890602_6_dialog_content = "Entonces somos afortunados porque tengo mucha experiencia con edificios como este. Las habilidades psíquicas pueden ser bastante útiles para explorar adelante.",
  ui_story_5089_50890602_7_dialog_content = "Escaneo Psíquico—",
  ui_story_5089_50890602_8_dialog_content = "¡Guau! ¡Hay tantas armas almacenadas aquí!",
  ui_story_5089_50890602_9_dialog_content = "¿Qué planean hacer los Fate Riders con ellos? ¿Eh?",
  ui_story_5089_50890602_10_dialog_content = "Parece que alguien está encerrado en esa habitación de allí.",
  ui_story_5089_50890602_11_dialog_content = "!",
  ui_story_5089_50890602_12_dialog_content = "<color=#e8d9bb>En el momento en que pusieron un pie en la habitación, un hedor fétido asalta sus sentidos.</color>",
  ui_story_5089_50890602_13_dialog_content = "<color=#e8d9bb>Una figura acurrucada tiembla en la esquina de la habitación, alejándose desesperadamente de ellos.</color>",
  ui_story_5089_50890602_14_dialog_content = "Solo mira este lugar. Deben haberlo mantenido aquí durante mucho tiempo.",
  ui_story_5089_50890602_15_dialog_content = "¿Quién eres? ¿Qué estás haciendo aquí?",
  ui_story_5089_50890602_16_dialog_content = "Ahh—Ahh—",
  ui_story_5089_50890602_17_dialog_content = "Urgh... Jaja... Woooo—",
  ui_story_5089_50890602_18_dialog_content = "Parece que el pobre ya está demasiado lejos. Ya no obtendremos nada de él.",
  ui_story_5089_50890602_19_dialog_content = "Sigamos investigando el taller. Tal vez encontremos una manera de salvarlo...",
  ui_story_5089_50890602_20_dialog_content = "Jiu? ¿Por qué sigues ahí parado?",
  ui_story_5089_50890602_21_dialog_content = "No... Esto no puede ser... ¿Por qué estás tú...",
  ui_story_5089_50890602_22_dialog_content = "¡¿Por qué estás aquí, mi rey?!",
  ui_story_5089_50890602_23_dialog_content = "Espera... ¿Ese es el Rey de Ye?!",
  ui_story_5089_50890700_1_dialog_content = "<color=#e8d9bb>El día siguiente</color>",
  ui_story_5089_50890700_2_dialog_content = "... ¿Princesa?",
  ui_story_5089_50890700_3_dialog_content = "¿Hmm? ¿Sí?",
  ui_story_5089_50890700_4_dialog_content = "Me pediste que preguntara sobre esas dos princesas, ¿no? ¿Fang Ze y Shao Qin?",
  ui_story_5089_50890700_5_dialog_content = "Ah, sí. Dime, ¿qué has aprendido sobre mis hermanas?",
  ui_story_5089_50890700_6_dialog_content = "Parece que el rey los envió a venerar a los antepasados reales hace algún tiempo. Como tal, se quedarán en una de las villas imperiales en lugar de regresar a la Ciudad de Jingliang.",
  ui_story_5089_50890700_7_dialog_content = "Debí saberlo...",
  ui_story_5089_50890700_8_dialog_content = "¿Has estado parado en un aturdimiento aquí todo el tiempo? Apenas has tocado tu desayuno... Dejar que todos estos platos deliciosos se enfríen es un desperdicio.",
  ui_story_5089_50890700_9_dialog_content = "Perdóname, pero no tengo mucho apetito.",
  ui_story_5089_50890700_10_dialog_content = "No importa cuán grandes sean nuestras penas, descuidar nuestros cuerpos no resolverá nada. ¿No estás de acuerdo?",
  ui_story_5089_50890700_11_dialog_content = "Y además, preocuparte no te ayudará ahora que estamos atrapados en el palacio. Todo lo que podemos hacer es depositar nuestras esperanzas en PlayerName y la señorita Jiu.",
  ui_story_5089_50890700_12_dialog_content = "Tu sirvienta nos dijo que nuestros amigos están bien, ¿verdad?",
  ui_story_5089_50890700_13_dialog_content = "¿O estás diciendo que no crees en ellos?",
  ui_story_5089_50890700_14_dialog_content = "Por supuesto que creo en ellos. Tú, por otro lado...",
  ui_story_5089_50890700_15_dialog_content = "Esperaba que huyeras a la primera oportunidad, y sin embargo, aquí estás.",
  ui_story_5089_50890700_16_dialog_content = "Ven ahora, ¿por qué alguna vez elegiría irme? El palacio me ofrece mucha comida y un lugar cálido para dormir. ¡Si acaso, estos son algunos de los mejores días de mi vida!",
  ui_story_5089_50890700_17_dialog_content = "No podía soportar separarme de una vida tan maravillosa, así que realicé una adivinación para ver cuánto tiempo más podría quedarme aquí. ¿Puedes adivinar qué vi, Su Alteza?",
  ui_story_5089_50890700_18_dialog_content = "Mi adivinación reveló que todavía me necesitas aquí.",
  ui_story_5089_50890700_19_dialog_content = "Hacer que te hagas pasar por Jiu ya es pedir demasiado. ¿Cómo podría imponerte aún más?",
  ui_story_5089_50890700_20_dialog_content = "Una vez que se resuelva este asunto, todavía tengo que ofrecerte una recompensa adecuada—",
  ui_story_5089_50890700_21_dialog_content = "<color=#e8d9bb>¡¡Boom—!!</color>",
  ui_story_5089_50890700_22_dialog_content = "¡¿Q-Qué fue eso?!",
  ui_story_5089_50890700_23_dialog_content = "¡Su Alteza! Un intruso ha irrumpido en el palacio! Por favor, apresúrese a—¡Nngh!",
  ui_story_5089_50890700_24_dialog_content = "¿Por qué dejaste inconsciente a ese pobre hombre, Tianxian?",
  ui_story_5089_50890700_25_dialog_content = "¡Para mostrarte que todavía tengo mucho que ofrecer, por supuesto!",
  ui_story_5089_50890700_26_dialog_content = "Ah— Ahhh—",
  ui_story_5089_50890700_27_dialog_content = "*bostezo* Ugh, ¿ya es la mañana?",
  ui_story_5089_50890700_28_dialog_content = "Estaba demasiado asustado para dormir anoche...",
  ui_story_5089_50890700_29_dialog_content = "¡Ahh—!",
  ui_story_5089_50890700_30_dialog_content = "*suspiro* Ya corrimos un gran riesgo al llevarte a un montón de médicos diferentes en medio de la noche.",
  ui_story_5089_50890700_31_dialog_content = "Pero todos dijeron lo mismo: que tu condición fue causada por envenenamiento, y que el veneno ya se ha infiltrado en tus huesos. Según ellos, ya estás más allá de la salvación.",
  ui_story_5089_50890700_32_dialog_content = "Awoo, awoooo—",
  ui_story_5089_50890700_33_dialog_content = "¿Eres realmente el Rey de Ye en persona? Si es así...",
  ui_story_5089_50890700_34_dialog_content = "\"Sin esperanza\" ni siquiera comienza a describir la situación en la que estamos ahora.",
  ui_story_5089_50890700_35_dialog_content = "No solo eso, sino que algo que dijo Jiu ayer me dio un mal presentimiento realmente.",
  ui_story_5089_50890700_36_dialog_content = "¿Así que esta clínica tampoco puede hacer nada por él, eh?",
  ui_story_5089_50890700_37_dialog_content = "No te rindas aún, Jiu. ¿Quizás podamos conseguir que uno de estos médicos escriba una carta para Liqing?",
  ui_story_5089_50890700_38_dialog_content = "Incluso podríamos intentar encontrar a ese tal \"Bucunzi\" que Dantang mencionó antes—",
  ui_story_5089_50890700_39_dialog_content = "PlayerName.",
  ui_story_5089_50890700_40_dialog_content = "Si la persona en el trono no es el verdadero Rey de Ye, ¿qué será de Su Alteza?",
  ui_story_5089_50890700_41_dialog_content = "Bueno...",
  ui_story_5089_50890700_42_dialog_content = "Estoy profundamente endeudado no solo con el rey, sino también con ella. En nuestro tiempo juntos, Su Alteza solo me ha mostrado bondad.",
  ui_story_5089_50890700_43_dialog_content = "Ahora que la princesa me ha relevado de mis deberes como su guardaespaldas, puede que no tenga derecho a entrometerme en sus asuntos.",
  ui_story_5089_50890700_44_dialog_content = "Pero si ya no puedo protegerla...",
  ui_story_5089_50890700_45_dialog_content = "Entonces confío la seguridad de Su Alteza en ti.",
  ui_story_5089_50890700_46_dialog_content = "Lo siento.",
  ui_story_5089_50890700_47_dialog_content = "Espera un minuto... ¿Dónde diablos está ella, de todos modos?!",
  ui_story_5089_50890700_48_dialog_content = "¡Grrr... Lo sabía!",
  ui_story_5089_50890700_49_dialog_content = "Menos mal que planifiqué algo así...",
  ui_story_5089_50890700_50_dialog_content = "¡Tío Li! Lo siento, pero ¿podría pedirte que te ocupes de este hombre?",
  ui_story_5089_50890700_51_dialog_content = "¿Eh? Claro, mi joven amigo, ¿pero adónde vas con tanta prisa?",
  ui_story_5089_50890700_52_dialog_content = "¡A la ciudad de Jingliang!",
  ui_story_5089_50890700_53_dialog_content = "¡Ahh—!",
  ui_story_5089_50890700_54_dialog_content = "Mi señor, un asesino ha violado las puertas del palacio y nuestros guardias no son rival para ella. ¡Se acerca al salón principal mientras hablamos!",
  ui_story_5089_50890700_55_dialog_content = "Debe ser Espada de Hielo, Su Alteza.",
  ui_story_5089_50890700_56_dialog_content = "¿Deberíamos interceptarla?",
  ui_story_5089_50890700_57_dialog_content = "No es necesario. Si ella busca una audiencia con el rey, entonces la esperaré justo aquí.",
  ui_story_5089_50890700_58_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5089_50890700_59_dialog_content = "¡Alto! Te encuentras ante el poderoso Rey de Ye, ¡no avances más!",
  ui_story_5089_50890700_60_dialog_content = "Hazte a un lado.",
  ui_story_5089_50890700_61_dialog_content = "Eurgh—",
  ui_story_5089_50890700_62_dialog_content = "<color=#e8d9bb>Jiu entra con paso firme al salón principal y cruza la mirada con el hombre en el trono.</color>",
  ui_story_5089_50890700_63_dialog_content = "Parece que su reputación como la espada más afilada del rey está bien ganada.",
  ui_story_5089_50890700_64_dialog_content = "Ningún guerrero en todo el palacio podría esperar rivalizar contigo.",
  ui_story_5089_50890700_65_dialog_content = "¡Deja de actuar!",
  ui_story_5089_50890700_66_dialog_content = "Ya me he encontrado con el verdadero rey, tú impostor—",
  ui_story_5089_50890700_67_dialog_content = "¡Ahora retírate de su trono!",
  ui_story_5089_50890700_68_dialog_content = "Ah, así que has visto a ese tonto confundido por ti mismo.",
  ui_story_5089_50890700_69_dialog_content = "<color=#e8d9bb>Sonido metálico-</color>",
  ui_story_5089_50890700_70_dialog_content = "<color=#e8d9bb>Sus espadas chocan, llenando el salón con su poderosa reverberación.</color>",
  ui_story_5089_50890700_71_dialog_content = "¡Cómo te atreves a insultar al rey tan insensiblemente!",
  ui_story_5089_50890700_72_dialog_content = "Je, admiro tu ferocidad.",
  ui_story_5089_50890700_73_dialog_content = "Realmente eres el espadachín más poderoso bajo mi mando.",
  ui_story_5089_50890700_74_dialog_content = "¡Por qué tú...!",
  ui_story_5089_50890700_75_dialog_content = "¡Guardias! ¡Saluden a su superior con una amistosa prueba de fuerza!",
  ui_story_5089_50890700_76_dialog_content = "¡Si su Alteza!",
  ui_story_5089_50890700_77_dialog_content = "<color=#e8d9bb>Los guardias de la sombra del rey se acercan desde ambos lados, sus afilados cables de metal cortando el aire.</color>",
  ui_story_5089_50890700_78_dialog_content = "<color=#e8d9bb>Justo cuando Jiu está a punto de esquivar, nota una laguna en las defensas del falso rey y ataca.</color>",
  ui_story_5089_50890700_79_dialog_content = "—!",
  ui_story_5089_50890700_80_dialog_content = "<color=#e8d9bb>Un alambre de metal perfora su pierna inferior, pero su ataque no vacila ni por un momento. ¡Ella empuja su espada directamente al corazón del falso rey con toda su fuerza!</color>",
  ui_story_5089_50890700_81_dialog_content = "Desde que eras un niño, siempre has tenido este terrible hábito.",
  ui_story_5089_50890700_82_dialog_content = "<color=#e8d9bb>Sonido metálico-</color>",
  ui_story_5089_50890700_83_dialog_content = "<color=#e8d9bb>La punta de su espada presiona la ligera armadura del rey y rebota ligeramente.</color>",
  ui_story_5089_50890700_84_dialog_content = "Maldito seas...",
  ui_story_5089_50890700_85_dialog_content = "<color=#e8d9bb>Jiu se recupera inmediatamente y se prepara para atacar una vez más.</color>",
  ui_story_5089_50890700_86_dialog_content = "Tu cuchilla es afilada, pero perfeccionar un borde hasta su límite tiene el costo de la durabilidad de la cuchilla.",
  ui_story_5089_50890700_87_dialog_content = "¿Has olvidado la razón por la que te di el nombre \"Jiu\"?",
  ui_story_5089_50890700_88_dialog_content = "!",
  ui_story_5089_50890700_89_dialog_content = "<color=#e8d9bb>—Hace diez años</color>",
  ui_story_5089_50890700_90_dialog_content = "¿Así que perseguiste al asesino de tu familia hasta aquí, descalzo y solo, sin comer ni beber nada durante todo un día?",
  ui_story_5089_50890700_91_dialog_content = "Jajaja, nunca esperé que alguien tan joven fuera tan decidido.",
  ui_story_5089_50890700_92_dialog_content = "Pero solo mírate ahora: muriéndote de hambre, cubierto de ampollas y apenas capaz de mantenerte en pie.",
  ui_story_5089_50890700_93_dialog_content = "Incluso si alcanzas a tu enemigo en esta condición, la única victoria que podrías esperar es una en la que ambos mueran.",
  ui_story_5089_50890700_94_dialog_content = "... Pero eso no te molestó, ¿verdad? Después de todo, ¿qué más podrías hacer con tu vida además de sacrificarla en nombre de la venganza?",
  ui_story_5089_50890700_95_dialog_content = "Pero ahora que he llevado a cabo tu venganza, es apropiado que tu vida me pertenezca ahora.",
  ui_story_5089_50890700_96_dialog_content = "¿\"Jiu-mei\", fue eso? Un nombre que significa \"la novena hija\" apenas vale la pena mantener.",
  ui_story_5089_50890700_97_dialog_content = "A partir de este día, simplemente serás conocido como \"Jiu\".",
  ui_story_5089_50890700_98_dialog_content = "Un nombre que se refiere a una piedra preciosa del negro más puro. Es tan hermosa como el magatama, pero mucho más fuerte.",
  ui_story_5089_50890700_99_dialog_content = "Bajo mi mando, afilarás tu filo y te convertirás en mi espada más afilada, siempre y cuando no te permitas volverte frágil.",
  ui_story_5089_50890700_100_dialog_content = "<color=#e8d9bb>Jiu pierde el enfoque momentáneamente, y es inmediatamente clavado al suelo por una red de innumerables cables de metal.</color>",
  ui_story_5089_50890700_101_dialog_content = "<color=#e8d9bb>Su máscara cae al suelo, pero ella continúa mirando amenazadoramente al falso rey.</color>",
  ui_story_5089_50890700_102_dialog_content = "¿Quién... Quién eres tú?",
  ui_story_5089_50890700_103_dialog_content = "¿No dijeron que alguien se infiltró en el palacio? ¿Por qué todavía hay tantos guardias vigilando este lugar?",
  ui_story_5089_50890700_104_dialog_content = "Cuando dijiste que huyéramos justo ahora, pensé que era porque tenías algún tipo de plan brillante.",
  ui_story_5089_50890700_105_dialog_content = "Improvisar es un plan de acción perfectamente aceptable, dadas nuestras circunstancias.",
  ui_story_5089_50890700_106_dialog_content = "Entiendo que depositas muy poca fe en mi adivinación, pero yo creo en ella de todo corazón.",
  ui_story_5089_50890700_107_dialog_content = "La ominosa fortuna que PlayerName sacó antes coincide perfectamente con nuestra situación actual.",
  ui_story_5089_50890700_108_dialog_content = "Sin embargo, si mis cálculos son correctos, no podemos confiar completamente en PlayerName y la señorita Jiu para resolver este aprieto.",
  ui_story_5089_50890700_109_dialog_content = "¿Qué estás tratando de decir?",
  ui_story_5089_50890700_110_dialog_content = "Es simple: mientras yo distraigo a los soldados, aprovecharás la oportunidad para escapar del palacio.",
  ui_story_5089_50890700_111_dialog_content = "En cuanto a lo que viene después, ¡simplemente tendremos que improvisar!",
  ui_story_5089_50890700_112_dialog_content = "¡Espera, Tianxian!",
  ui_story_5089_50890700_113_dialog_content = "¡¿Quién va allí?!",
  ui_story_5089_50890700_114_dialog_content = "¡Después de ellos!",
  ui_story_5089_50890700_115_dialog_content = "Nunca entenderé a ese hombre.",
  ui_story_5089_50890700_116_dialog_content = "Pero parece que no tengo elección ahora—",
  ui_story_5089_50890700_117_dialog_content = "¿A dónde va, Su Alteza?",
  ui_story_5089_50890700_118_dialog_content = "...",
  ui_story_5089_50890700_119_dialog_content = "Xuan Ji, los soldados—",
  ui_story_5089_50890700_120_dialog_content = "Baja la voz, estoy ocupado aquí.",
  ui_story_5089_50890700_121_dialog_content = "¡Pero no queda tiempo! ¿Por qué sigues jugueteando con esas fichas?",
  ui_story_5089_50890700_122_dialog_content = "¡Estos no son azulejos ordinarios! Son ingeniosos dispositivos que he estado elaborando meticulosamente durante varios días.",
  ui_story_5089_50890700_123_dialog_content = "Te has vuelto mucho más sabio, pero aún tienes mucho que aprender en cuanto a astucia y engaño.",
  ui_story_5089_50890700_124_dialog_content = "¿Qué significa eso?",
  ui_story_5089_50890700_125_dialog_content = "Lo que quiero decir es que esto puede parecerte una celda de prisión ordinaria.",
  ui_story_5089_50890700_126_dialog_content = "Pero en las manos de un verdadero artesano, cualquier cosa puede ser modificada en un dispositivo o mecanismo: taburetes, mesas, vigas del techo e incluso el suelo bajo tus pies.",
  ui_story_5089_50890700_127_dialog_content = "¡Ahora deleita tus ojos con mi última invención, que fue inspirada por nuestro Celestita favorito y hecha con simples artículos del hogar: la Baldosa Deflectora de Lumina!",
  ui_story_5089_50890700_128_dialog_content = "... ¿Estás bromeando, no? Entonces, ¿qué hace exactamente?",
  ui_story_5089_50890700_129_dialog_content = "Esta fina pieza de equipo es capaz de redirigir cualquier luz entrante o Lumina a una ubicación deseada.",
  ui_story_5089_50890700_130_dialog_content = "¿Y cómo exactamente se supone que eso nos va a ayudar?",
  ui_story_5089_50890700_131_dialog_content = "¡Lo averiguaremos muy pronto!",
  ui_story_5089_50890700_132_dialog_content = "Hace diez años, un alto funcionario, agotado por las luchas de poder dentro de la corte real, cayó en desgracia y se convirtió en prisionero. Fue condenado a trabajos forzados en las minas hasta su muerte.",
  ui_story_5089_50890700_133_dialog_content = "Sin embargo, el destino tenía otros planes para él. Los oficiales que lo escoltaban al campo de trabajo eran indolentes y, en lugar de terminar el viaje, decidieron alojarse en la casa de una familia cercana.",
  ui_story_5089_50890700_134_dialog_content = "No eran más que ciudadanos ordinarios, lo que le facilitó emboscarlos y hacer su escape.",
  ui_story_5089_50890700_135_dialog_content = "Pero mientras huía del patio, se encontró con sus captores mientras intentaban aprovecharse de la joven hija de la familia.",
  ui_story_5089_50890700_136_dialog_content = "Y así los mató sin pensarlo dos veces, y continuó por su ruta original hacia el campo de trabajo.",
  ui_story_5089_50890700_137_dialog_content = "El príncipe que estaba a cargo del campo de trabajo en ese momento era un buen hombre, pero aún así un torpe. Con solo una dosis de cierta medicina, perdió completamente la razón.",
  ui_story_5089_50890700_138_dialog_content = "Y así, después de ponerse un ligero disfraz, el prisionero intercambió lugares con el príncipe.",
  ui_story_5089_50890700_139_dialog_content = "Los hombres en su presencia carecían tanto de lealtad, que nunca se dieron cuenta de que otro hombre había reemplazado silenciosamente a su maestro.",
  ui_story_5089_50890700_140_dialog_content = "Casualmente, fue en este momento que la joven hija llegó, buscando venganza por su familia caída.",
  ui_story_5089_50890700_141_dialog_content = "Fue entonces cuando el prisionero se dio cuenta de que su escape a la fuerza resultó en sus muertes.",
  ui_story_5089_50890700_142_dialog_content = "Y así él acogió a la chica, y la forjó en una espada leal y fiel.",
  ui_story_5089_50890700_143_dialog_content = "¡E-Eras tú todo el tiempo—!",
  ui_story_5089_50890700_144_dialog_content = "<color=#e8d9bb>Los ojos de Jiu se vuelven rojos mientras se esfuerza por levantar su cuerpo. La red de alambre que la sujeta emite un gemido agudo, como si estuviera a punto de romperse.</color>",
  ui_story_5089_50890700_145_dialog_content = "Finalmente ha llegado el momento de revelar la verdad.",
  ui_story_5089_50890700_146_dialog_content = "Ahora dime, ¿todavía tienes la intención de vengar la muerte de tu familia?",
  ui_story_5089_50890700_147_dialog_content = "¿O me expresarás gratitud por acogerte y criarte durante todos estos años?",
  ui_story_5089_50890700_148_dialog_content = "Yo...",
  ui_story_5089_50890700_149_dialog_content = "<color=#e8d9bb>Por primera vez, la espada de Jiu tiembla en su mano.</color>",
  ui_story_5089_50890700_150_dialog_content = "¿Para qué has estado viviendo todo este tiempo, Jiu? ¿Cuál es tu propósito?",
  ui_story_5089_50890700_151_dialog_content = "¡Hraaagh—!",
  ui_story_5089_50890700_152_dialog_content = "<color=#e8d9bb>Una raya de luz pasa rápidamente.</color>",
  ui_story_5089_50890700_153_dialog_content = "<color=#e8d9bb>Los cables de metal se rompen y vuelan en todas direcciones. Entre los escombros que caen, Jiu desata su ataque definitivo.</color>",
  ui_story_5089_50890700_154_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5089_50890700_155_dialog_content = "<color=#e8d9bb>Ella blande su espada cargada de Lumina, y la onda de choque resultante parte el palacio en dos, dejando profundas trincheras en el suelo de piedra.</color>",
  ui_story_5089_50890700_156_dialog_content = "<color=#e8d9bb>El Rey de Ye, sin embargo, esquiva fácilmente el ataque y emerge ileso.</color>",
  ui_story_5089_50890700_157_dialog_content = "¿Estás realmente tan lleno de dudas que ni siquiera puedes sostener tu espada con firmeza?",
  ui_story_5089_50890700_158_dialog_content = "<color=#e8d9bb>¡Pam—</color>",
  ui_story_5089_50890700_159_dialog_content = "<color=#e8d9bb>El rey golpea la espada de Jiu de su mano y la manda a una esquina de la habitación.</color>",
  ui_story_5089_50890700_160_dialog_content = "<color=#e8d9bb>Hace unos momentos.</color>",
  ui_story_5089_50890700_161_dialog_content = "Su Alteza, si insiste en irse, no nos quedará más remedio que detenerlo a la fuerza.",
  ui_story_5089_50890700_162_dialog_content = "Nunca pensé que vería el día en que tendría que luchar contra mis guardias del palacio en Ye Kingdom.",
  ui_story_5089_50890700_163_dialog_content = "Desafortunadamente para ti, retirarme ya no es una opción para mí.",
  ui_story_5089_50890700_164_dialog_content = "Todavía tengo a alguien esperándome allá afuera.",
  ui_story_5089_50890700_165_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5089_50890700_166_dialog_content = "<color=#e8d9bb>De repente, la sala principal cercana es destrozada por una poderosa oleada de Lumina.</color>",
  ui_story_5089_50890700_167_dialog_content = "<color=#e8d9bb>Inmediatamente después, un destello de luz llena la habitación mientras la ola de Lumina se dirige directamente hacia ellos!</color>",
  ui_story_5089_50890700_168_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5089_50890700_169_dialog_content = "<color=#e8d9bb>La torre del palacio está dividida por la mitad, creando una brecha entre los guardias reales y Dantang.</color>",
  ui_story_5089_50890700_170_dialog_content = "<color=#e8d9bb>Otro destello repentino de luz ilumina el camino fuera del palacio.</color>",
  ui_story_5089_50890700_171_dialog_content = "Esa dirección... ¿Ministra Armilla?",
  ui_story_5089_50890700_172_dialog_content = "Tenía la sensación de que ella nunca se quedaría quieta en su celda de prisión.",
  ui_story_5089_50890700_173_dialog_content = "¿Entonces crees que también debería escapar del palacio?",
  ui_story_5089_50890700_174_dialog_content = "Su Alteza.",
  ui_story_5089_50890700_175_dialog_content = "¿Qué es?",
  ui_story_5089_50890700_176_dialog_content = "Perdónanos, pero la Princesa ha escapado del palacio.",
  ui_story_5089_50890700_177_dialog_content = "El estado de la persona que entró al palacio con la princesa también es desconocido, al igual que su paradero.",
  ui_story_5089_50890700_178_dialog_content = "Nuestros guardias afirman haberlo visto sumergirse en un grupo de arbustos, pero cuando fueron a investigar, todo lo que encontraron fue una figurita de azúcar.",
  ui_story_5089_50890700_179_dialog_content = "Además...",
  ui_story_5089_50890700_180_dialog_content = "¿Qué más? Habla ya.",
  ui_story_5089_50890700_181_dialog_content = "Parece que \"ellos\" planean hacer su movimiento pronto.",
  ui_story_5089_50890700_182_dialog_content = "Insisten en que entreguemos las armas en los próximos tres días.",
  ui_story_5089_50890700_183_dialog_content = "Sin embargo, el taller afirma carecer de la capacidad para cumplir su enorme pedido en tan corto tiempo. El Reino de Ji también nos está instando a completar su transacción anterior...",
  ui_story_5089_50890700_184_dialog_content = "Entendido.",
  ui_story_5089_50890700_185_dialog_content = "Lo discutiremos más tarde.",
  ui_story_5089_50890700_186_dialog_content = "Por ahora, restrinja a su ex líder hasta que recupere la compostura.",
  ui_story_5089_50890700_187_dialog_content = "Si, su Alteza.",
  ui_story_5089_50890700_188_dialog_content = "<color=#e8d9bb>¡Wham!</color>",
  ui_story_5089_50890700_189_dialog_content = "<color=#e8d9bb>El guardia sombrío lanza a Jiu en una habitación vacía y se va.</color>",
  ui_story_5089_50890700_190_dialog_content = "¡Bueno, si no es la señorita Jiu!",
  ui_story_5089_50890700_191_dialog_content = "¿Has venido a hacerme compañía?",
  ui_story_5089_50890700_192_dialog_content = "...",
  ui_story_5089_50890802_1_dialog_content = "¡Alerta a todos los guardias de la ciudad! ¡La princesa ha sido secuestrada!",
  ui_story_5089_50890802_2_dialog_content = "¡Busca en cada rincón de la ciudad! ¡Reporta cualquier personaje sospechoso de inmediato!",
  ui_story_5089_50890802_3_dialog_content = "¡Entendido!",
  ui_story_5089_50890802_4_dialog_content = "Tantos guardias... Parece que toda la atmósfera de la ciudad de Jingliang cambió repentinamente.",
  ui_story_5089_50890802_5_dialog_content = "Y algo me dice que soy uno de los \"personajes sospechosos\" que están buscando.",
  ui_story_5089_50890802_6_dialog_content = "¿Quién está ahí? ¡Muéstrate!",
  ui_story_5089_50890802_7_dialog_content = "Uh-oh—Urk! ¡S-Suéltame...!",
  ui_story_5089_50890802_8_dialog_content = "Shh, solo soy yo.",
  ui_story_5089_50890802_9_dialog_content = "¿Dantang?!",
  ui_story_5089_50890802_10_dialog_content = "Sí, ahora sígueme.",
  ui_story_5089_50890802_11_dialog_content = "¿Qué es este lugar?",
  ui_story_5089_50890802_12_dialog_content = "Es una habitación segura preparada por los escoltas armados que contratamos para devolver el oro del príncipe heredero.",
  ui_story_5089_50890802_13_dialog_content = "Dado que a menudo trabajan con el inframundo criminal, naturalmente tienen una necesidad de espacios como este.",
  ui_story_5089_50890802_14_dialog_content = "Y dado que hicimos un pedido tan caro, es normal que nos proporcionen algunas comodidades adicionales.",
  ui_story_5089_50890802_15_dialog_content = "¿Estabas planeando esto con tanta anticipación todo el tiempo?!",
  ui_story_5089_50890802_16_dialog_content = "¡Así que había una razón para dejarnos atrás en la posada!",
  ui_story_5089_50890802_17_dialog_content = "No estaba completamente seguro de la verdad en ese entonces. Todo lo que tenía eran las vagas insinuaciones de la Ministra Armilla para guiarme.",
  ui_story_5089_50890802_18_dialog_content = "Aunque las posibilidades eran escasas, la mera posibilidad de juego sucio representaba una gran amenaza para todo el Reino Ye.",
  ui_story_5089_50890802_19_dialog_content = "No solo eso... Pero el precio de la ganancia es demasiado alto.",
  ui_story_5089_50890802_20_dialog_content = "El Tío Li también nos informó que los comerciantes del Reino Ji han estado comprando comida a pesar de los altos precios últimamente.",
  ui_story_5089_50890802_21_dialog_content = "... El tumulto al comienzo de la primavera también se debió en parte a la renuencia del Reino Ye a entregar cañones a la costa.",
  ui_story_5089_50890802_22_dialog_content = "El Reino de Ji nunca soportaría estas pérdidas sin obtener algo a cambio.",
  ui_story_5089_50890802_23_dialog_content = "¿Estás diciendo... que el Reino Ji está elevando deliberadamente el precio de los granos?",
  ui_story_5089_50890802_24_dialog_content = "El ciudadano común es el más perjudicado cuando los precios suben de esta manera. Cuando eso sucede, es más probable que se vayan y busquen otras formas de sobrevivir.",
  ui_story_5089_50890802_25_dialog_content = "En los últimos años, el Reino de Ye ha establecido innumerables talleres de varios tamaños. Al hacerlo, han atraído a muchos de los ciudadanos jóvenes y saludables del reino, obligándolos a abandonar sus campos con la esperanza de obtener un trabajo mejor remunerado.",
  ui_story_5089_50890802_26_dialog_content = "Nuestras reservas de grano ya eran insuficientes para manejar un cambio de población de esta magnitud.",
  ui_story_5089_50890802_27_dialog_content = "El creciente costo del grano también ha aumentado los costos para otros sectores. En resumen, la economía del reino está atrapada en un círculo vicioso.",
  ui_story_5089_50890802_28_dialog_content = "El Reino Ji, sin embargo, no escasea en fondos en absoluto. Si deciden desafiarnos a una guerra de desgaste, temo que no tengamos ninguna posibilidad de ganar.",
  ui_story_5089_50890802_29_dialog_content = "Sin embargo, no estoy convencido de que el Reino de Ji desee cortar lazos completamente. En todo caso, es probable que deseen aprovechar nuestra debilidad para seguir explotándonos.",
  ui_story_5089_50890802_30_dialog_content = "... Su momento no podría ser peor.",
  ui_story_5089_50890802_31_dialog_content = "¿Su tiempo?",
  ui_story_5089_50890802_32_dialog_content = "Dime, PlayerName: ¿qué consideras exactamente una \"nación\"?",
  ui_story_5089_50890802_33_dialog_content = "¿Eh? Bueno... Diría que es un grupo de personas que se unen en busca de una vida mejor.",
  ui_story_5089_50890802_34_dialog_content = "Además de promover sus intereses, también trabajan duro para todos los demás en el grupo.",
  ui_story_5089_50890802_35_dialog_content = "¿Es así como la gente de Eraveil define una nación? Debo decir, suena como una existencia bastante utópica.",
  ui_story_5089_50890802_36_dialog_content = "¿E-Estoy equivocado?",
  ui_story_5089_50890802_37_dialog_content = "En absoluto, PlayerName.",
  ui_story_5089_50890802_38_dialog_content = "Aunque cada reino vasallo en Longzhou cae bajo el dominio del Imperio Zhao, cada uno tiene sus propias opiniones sobre lo que significa ser una nación.",
  ui_story_5089_50890802_39_dialog_content = "Por ejemplo, el Reino de Ji cree que gobernar un país no es diferente a dirigir un negocio. El Reino de Ye, por otro lado, ve las cosas de manera diferente.",
  ui_story_5089_50890802_40_dialog_content = "En nuestros ojos, una nación es un mecanismo masivo e informe. Día y noche, funciona sin descanso.",
  ui_story_5089_50890802_41_dialog_content = "Eres el pivote, yo soy el engranaje, el artesano es el aceite y las masas son su fuerza motriz.",
  ui_story_5089_50890802_42_dialog_content = "Mientras cada pieza de la máquina cumpla su rol diligentemente y normalmente, nuestra nación prosperará naturalmente.",
  ui_story_5089_50890802_43_dialog_content = "¿Entonces qué tal ahora?",
  ui_story_5089_50890802_44_dialog_content = "Nuestro rey es un impostor, los intereses en conflicto marcan su corte, los artesanos no son libres y las masas están al borde de un sufrimiento aún mayor. Este es el estado actual de nuestra nación.",
  ui_story_5089_50890802_45_dialog_content = "En lugar de intentar resolver cada uno de estos problemas individualmente, decidí ir al corazón del conflicto.",
  ui_story_5089_50890802_46_dialog_content = "Y así regresé voluntariamente al palacio, con la esperanza de encontrar un defecto en el núcleo del sufrimiento de nuestra nación.",
  ui_story_5089_50890802_47_dialog_content = "Hacerlo también permitió que tú y Jiu continuaran buscando pruebas sin ser perseguidos por los soldados del rey.",
  ui_story_5089_50890802_48_dialog_content = "Hablando francamente, sabía que Jiu nunca estaría de acuerdo con esto, lo que no me dejó más opción que recurrir al engaño. Por favor, no me lo tomes a mal, PlayerName.",
  ui_story_5089_50890802_49_dialog_content = "No te culpo por ello, Dantang. Después de nuestro tiempo juntos, aprendí lo terca que ella también puede ser.",
  ui_story_5089_50890802_50_dialog_content = "Por eso tuve que hacer algo similar con ella...",
  ui_story_5089_50890802_51_dialog_content = "Perdona la interrupción, jóvenes maestros, pero su envío ha llegado con seguridad. May ¿Puedo molestarlos para una firma?",
  ui_story_5089_50890802_52_dialog_content = "Sí, claro. Muchas gracias por tu ayuda.",
  ui_story_5089_50890802_53_dialog_content = "Además, Su Alteza, hemos avanzado en el asunto desde nuestra última conversación.",
  ui_story_5089_50890802_54_dialog_content = "Mis hombres fuera de la ciudad me han informado que efectivamente hay Portadores de Huolong moviéndose en esa dirección, y que parecen estar transportando una gran cantidad de mercancías.",
  ui_story_5089_50890802_55_dialog_content = "Comprendido. Gracias por toda tu ayuda.",
  ui_story_5089_50890802_56_dialog_content = "Solo haciendo nuestro trabajo. Despedida.",
  ui_story_5089_50890802_57_dialog_content = "¿Hablaba él sobre el taller secreto?",
  ui_story_5089_50890802_58_dialog_content = "En efecto. Durante mi tiempo en el palacio, recopilé una cantidad considerable de información.",
  ui_story_5089_50890802_59_dialog_content = "El falso rey ha estado explotando los recursos del Reino Ye para fabricar armas para los Jinetes del Destino.",
  ui_story_5089_50890802_60_dialog_content = "El Reino de Ji también ha estado retrasando la entrega de sus cañones costeros. Mi sospecha es que también están conspirando con los Fate Riders, quienes desean reclamar esos cañones para sí mismos.",
  ui_story_5089_50890802_61_dialog_content = "Y recientemente volvieron a aumentar la demanda de armas de fuego.",
  ui_story_5089_50890802_62_dialog_content = "Han insistido en el asunto varias veces ahora, e incluso han amenazado al falso rey si no cumple.",
  ui_story_5089_50890802_63_dialog_content = "Cuando mencionaste la existencia de un taller oculto, envié inmediatamente a estos hombres a investigar.",
  ui_story_5089_50890802_64_dialog_content = "Sin embargo, no esperaba que tomaran medidas tan rápido...",
  ui_story_5089_50890802_65_dialog_content = "¡No podemos quedarnos aquí parados y dejar que los Fate Riders se hagan con todas esas armas!",
  ui_story_5089_50890802_66_dialog_content = "Estoy totalmente de acuerdo contigo.",
  ui_story_5089_50890802_67_dialog_content = "Pero dada nuestra situación actual, es bastante difícil para nosotros tomar medidas de cualquier manera.",
  ui_story_5089_50890802_68_dialog_content = "Incluso con tu ayuda, descubrir la verdad no fue en absoluto simple. Si tan solo hubiera podido prepararme antes...",
  ui_story_5089_50890802_69_dialog_content = "Eso no parece ni suena como tú en absoluto, Dantang.",
  ui_story_5089_50890802_70_dialog_content = "¿PlayerName?",
  ui_story_5089_50890802_71_dialog_content = "La Dantang que conozco, nunca se dudaría a sí misma por desafiar una situación como esta, especialmente si supuestamente el destino tuviera una mano en ello.",
  ui_story_5089_50890802_72_dialog_content = "El Dantang que conozco es valiente, hasta el punto de que es casi aterrador.",
  ui_story_5089_50890802_73_dialog_content = "... Me halagas, mi amigo. Pero desafortunadamente, nuestro predicamento no puede ser resuelto solo con valentía.",
  ui_story_5089_50890802_74_dialog_content = "Pero si podemos traer suficientes chips a la mesa de negociación...",
  ui_story_5089_50890802_75_dialog_content = "Eso no debería ser un problema.",
  ui_story_5089_50890802_76_dialog_content = "¿Qué?",
  ui_story_5089_50890802_77_dialog_content = "Si estás preocupado por las fichas de negociación, tenemos muchas.",
  ui_story_5089_50890802_78_dialog_content = "Por ejemplo... Tenemos suficiente oro en nuestras manos para comprar una ciudad entera.",
  ui_story_5089_50890802_79_dialog_content = "!",
  ui_story_5089_50890802_80_dialog_content = "¡Pero ese fue un regalo del príncipe heredero para ti, uno que planeabas devolver!",
  ui_story_5089_50890802_81_dialog_content = "Bueno, no fue fácil para nosotros llegar hasta aquí. Sería un desperdicio no utilizar todo lo que tenemos a nuestra disposición.",
  ui_story_5089_50890802_82_dialog_content = "Pero incluso con todo este oro, intentar reunir suficiente mano de obra en un tiempo tan limitado—",
  ui_story_5089_50890802_83_dialog_content = "También tengo una idea para eso.",
  ui_story_5089_50890802_84_dialog_content = "No entiendo las complejidades de la política judicial, por lo que no puedo ofrecer mucho de una opinión.",
  ui_story_5089_50890802_85_dialog_content = "Pero creo que podemos simplificar las cosas un poco con este oro.",
  ui_story_5089_50890802_86_dialog_content = "Después de todo, el dinero está destinado a gastarse en cosas, ¿verdad?",
  ui_story_5089_50890802_87_dialog_content = "Entonces... ¿Qué exactamente deseas comprar PlayerName?",
  ui_story_5089_50890802_88_dialog_content = "Supongo que esos chicos nunca han conducido un Transportador Huolong antes, ¿verdad?",
  ui_story_5089_50890802_89_dialog_content = "Y con todos los transportistas yendo y viniendo del taller secreto, es poco probable que los aldeanos cercanos no hayan visto ni oído nada. En otras palabras, no hay forma de que alguien creyera que estaba abandonado, al menos no recientemente.",
  ui_story_5089_50890802_90_dialog_content = "Y sin embargo, de alguna manera, parece que nadie sabía nada al respecto hasta ahora.",
  ui_story_5089_50890802_91_dialog_content = "Eso solo puede significar que el taller ha estado asegurando su secreto al recibir envíos más pequeños a través de múltiples entregas.",
  ui_story_5089_50890802_92_dialog_content = "Pero ahora, debido al enorme pedido de los Fate Riders, parece que están utilizando múltiples transportadores para transportar los materiales necesarios.",
  ui_story_5089_50890802_93_dialog_content = "La Guilda de Artesanos supervisa el uso de los Transportistas Huolong.",
  ui_story_5089_50890802_94_dialog_content = "La asociación en sí está compuesta por funcionarios de ambas sectas principales, así como por administradores nombrados por la corte real. Juntos, regulan el uso de los Portadores Huolong.",
  ui_story_5089_50890802_95_dialog_content = "Incluso el rey no puede eludir sus protocolos o usarlo libremente.",
  ui_story_5089_50890802_96_dialog_content = "Sin embargo, no vigilan de cerca a las personas que alquilan los transportistas.",
  ui_story_5089_50890802_97_dialog_content = "En otras palabras, probablemente los Fate Riders no tuvieron problemas para pedir prestados los derechos a los transportistas a través de uno de esos talleres, ¿verdad?",
  ui_story_5089_50890802_98_dialog_content = "¿Estás diciendo que quieres investigar cada taller individualmente?",
  ui_story_5089_50890802_99_dialog_content = "No.",
  ui_story_5089_50890802_100_dialog_content = "No necesitamos enfrentarnos a ellos directamente. Después de todo, los Fate Riders son a quienes perseguimos.",
  ui_story_5089_50890802_101_dialog_content = "Ahora que estoy mirando desde afuera, creo que estoy empezando a entender el \"impulso\" del que Xuan Ji estaba hablando.",
  ui_story_5089_50890802_102_dialog_content = "¡Dantang! El Gremio de Artesanos solo se encarga de alquilar los transportistas, ¿verdad?",
  ui_story_5089_50890802_103_dialog_content = "Sí, así es.",
  ui_story_5089_50890802_104_dialog_content = "Entonces lo que quiero comprar...",
  ui_story_5089_50890802_105_dialog_content = "Son las pistas mismas.",
  ui_story_5089_50890802_106_dialog_content = "... Realmente eres un genio, PlayerName!",
  ui_story_5089_50890802_107_dialog_content = "<color=#e8d9bb>Taller Secreto</color>",
  ui_story_5089_50890802_108_dialog_content = "¿Qué pasa con estos Portadores de Huolong? ¿Quién les dio permiso para actuar por su cuenta?!",
  ui_story_5089_50890802_109_dialog_content = "Cuida tu tono. Estaba a punto de hacerte la misma pregunta.",
  ui_story_5089_50890802_110_dialog_content = "Ustedes nunca dejan de instarnos a entregar las armas, pero ¿qué han estado haciendo todo este tiempo?",
  ui_story_5089_50890802_111_dialog_content = "Si no podemos producir suficientes a tiempo, simplemente envía el lote destinado al Reino Ji. Eso no debería ser demasiado difícil para ti, ¿verdad?",
  ui_story_5089_50890802_112_dialog_content = "... Si fallamos en cumplir con la orden del Reino de Ji, puede afectar las relaciones entre nuestras dos naciones.",
  ui_story_5089_50890802_113_dialog_content = "Ja, incluso un niño de tres años no sería tan ingenuo.",
  ui_story_5089_50890802_114_dialog_content = "Todos estamos en liga con los Jinetes del Destino ahora. ¿Realmente necesito decirte a quién seguir las órdenes? Los lazos entre los dos reinos ya no son de nuestra preocupación.",
  ui_story_5089_50890802_115_dialog_content = "A menos que... No me digas que tu supuesto \"rey\" se considera el verdadero gobernante del Reino de Ye?",
  ui_story_5089_50890802_116_dialog_content = "Claro que no.",
  ui_story_5089_50890802_117_dialog_content = "Bien. Entiendo que una vez fue condenado a muerte, pero su lealtad a los Jinetes del Destino es lo único que lo ha mantenido vivo como rey hasta el día de hoy.",
  ui_story_5089_50890802_118_dialog_content = "Si se atreve a traicionarlos, perderá todo tan rápido como lo ganó.",
  ui_story_5089_50890802_119_dialog_content = "Sin embargo, con el levantamiento casi a la mano, cualquier caos causado por la desobediencia de los estados vasallos también trabajará a nuestro favor.",
  ui_story_5089_50890802_120_dialog_content = "Seguramente entiendes eso, ¿verdad?",
  ui_story_5089_50890802_121_dialog_content = "... Por supuesto.",
  ui_story_5089_50890802_122_dialog_content = "Bien, ahora apresúrate y carga las mercancías.",
  ui_story_5089_50890802_123_dialog_content = "Lady Zhui Hu, hemos encontrado un problema.",
  ui_story_5089_50890802_124_dialog_content = "¿Ahora que?",
  ui_story_5089_50890802_125_dialog_content = "Parece que no podemos usar los Transportadores Huolong en este momento.",
  ui_story_5089_50890802_126_dialog_content = "¿Qué? ¿No pagamos a los talleres para asegurar el uso exclusivo de los portaaviones?!",
  ui_story_5089_50890802_127_dialog_content = "E-Eso no es el problema. Es solo que...",
  ui_story_5089_50890802_128_dialog_content = "La carretera ha sido bloqueada.",
  ui_story_5089_50890802_129_dialog_content = "¡¿Qué?!",
  ui_story_5089_50890901_1_dialog_content = "Tu generosa contribución ha hecho las cosas mucho más simples, PlayerName.",
  ui_story_5089_50890901_2_dialog_content = "Después de alquilar temporalmente las tierras que rodean las vías, he pedido a la gente que bloquee el camino que conduce al taller secreto.",
  ui_story_5089_50890901_3_dialog_content = "Hemos detenido efectivamente a los Fate Riders en su camino.",
  ui_story_5089_50890901_4_dialog_content = "Pero parece que nuestro bloqueo está empezando a causar problemas a algunos de los comerciantes ambulantes—",
  ui_story_5089_50890901_5_dialog_content = "¡Por favor, amigos! Solo estoy aquí para conseguir algunos granos. ¡No he hecho nada malo!",
  ui_story_5089_50890901_6_dialog_content = "¿No podrías por favor dejar pasar a nuestra caravana?",
  ui_story_5089_50890901_7_dialog_content = "Eres del Reino Ji, ¿verdad?",
  ui_story_5089_50890901_8_dialog_content = "¿Por qué, sí, lo soy. ¿Es eso un problema? Puedo asegurarte que tengo todos mis documentos de negocios en orden...",
  ui_story_5089_50890901_9_dialog_content = "(Dantang.)",
  ui_story_5089_50890901_10_dialog_content = "(Derecha.)",
  ui_story_5089_50890901_11_dialog_content = "Ejem, ¿te das cuenta con quién estás hablando ahora mismo?",
  ui_story_5089_50890901_12_dialog_content = "Eh, no... No puedo decir que lo haga...",
  ui_story_5089_50890901_13_dialog_content = "Este es PlayerName, Señor de Eraveil. Es un enviado especial de la tierra de Astra y un oficial honorable personalmente nombrado por el Rey de Ji.",
  ui_story_5089_50890901_14_dialog_content = "Bendecido por la Doncella Dragón, es un aliado cercano al gremio Lin, y el sujeto de los avances sinceros del príncipe heredero...",
  ui_story_5089_50890901_15_dialog_content = "(¡Ya está bien, has dejado claro tu punto! Puedes decir que ya está convencido por la mirada en sus ojos, ¡así que déjalo ya!)",
  ui_story_5089_50890901_16_dialog_content = "¡Ah, sí, ahora recuerdo! Verte una vez más es el mayor honor que podría esperar, ¡mi señor!",
  ui_story_5089_50890901_17_dialog_content = "Dime, ¿cómo puedo estar a tu servicio? Haré cualquier cosa que me pidas, siempre y cuando esté dentro de mi poder... Espera, tú fuiste quien selló el camino, ¿verdad?",
  ui_story_5089_50890901_18_dialog_content = "¡Perdóname por mi ignorancia, mi señor! Incluso si me desterraras hasta el fin de los tiempos, ¡no albergaría ningún resentimiento!",
  ui_story_5089_50890901_19_dialog_content = "No es nada tan grave. Solo tengo una propuesta de negocios para ti, eso es todo.",
  ui_story_5089_50890901_20_dialog_content = "¡Por todos los medios, mi señor! Le ofreceré el mejor precio por lo que desee!",
  ui_story_5089_50890901_21_dialog_content = "¿Cuánto oro nos queda, Dantang?",
  ui_story_5089_50890901_22_dialog_content = "Después de pagar por las pistas, la tierra que las rodea y los salarios de los artesanos... Solo hemos utilizado una porción muy pequeña de nuestros fondos.",
  ui_story_5089_50890901_23_dialog_content = "Dale el descanso, entonces.",
  ui_story_5089_50890901_24_dialog_content = "¿Lo siento...?",
  ui_story_5089_50890901_25_dialog_content = "Quiero usar este oro para comprar toda la comida que has obtenido del Reino Ye.",
  ui_story_5089_50890901_26_dialog_content = "Ah, mi señor... Esto presenta un gran desafío, sabes...",
  ui_story_5089_50890901_27_dialog_content = "Sé que estás trabajando para El Rey de Ji.",
  ui_story_5089_50890901_28_dialog_content = "!",
  ui_story_5089_50890901_29_dialog_content = "Puedes decirle que te obligamos a hacerlo, si es necesario. Asumiré toda la responsabilidad por todo.",
  ui_story_5089_50890901_30_dialog_content = "Ya veo... Supongo que puedo hacer una excepción por ti, mi señor.",
  ui_story_5089_50890901_31_dialog_content = "Bien. Y no te preocupes, siempre cumplo mi palabra.",
  ui_story_5089_50890901_32_dialog_content = "Uf, finalmente se fueron.",
  ui_story_5089_50890901_33_dialog_content = "Jeje.",
  ui_story_5089_50890901_34_dialog_content = "Sí, sí, adelante y ríe. Estoy seguro de que mi actuación \"señorial\" debe haber sido divertida de ver...",
  ui_story_5089_50890901_35_dialog_content = "Para nada, PlayerName. Tu actuación fue muy cautivadora.",
  ui_story_5089_50890901_36_dialog_content = "¿Mmm?",
  ui_story_5089_50890901_37_dialog_content = "Esa gente de allí...",
  ui_story_5089_50890901_38_dialog_content = "<color=#e8d9bb>Hace momentos—</color>",
  ui_story_5089_50890901_39_dialog_content = "Toc, toc, toc.",
  ui_story_5089_50890901_40_dialog_content = "¿Eh? ¿Quién podría ser en un momento como este?",
  ui_story_5089_50890901_41_dialog_content = "...",
  ui_story_5089_50890901_42_dialog_content = "¡Hermana Xuan Ji! Nuestro hermano de la Guilda de Artesanos dice que el Caelestita es—",
  ui_story_5089_50890901_43_dialog_content = "Suspiro, ¿cuántas veces tengo que decírtelo, Qian Ji? Deja de referirte a nosotros como hermanos mientras estamos en el palacio.",
  ui_story_5089_50890901_44_dialog_content = "Aunque no tenemos intención de tomar partido, nunca es buena idea darles una razón para malinterpretarnos.",
  ui_story_5089_50890901_45_dialog_content = "Es lo que llevó a la condena del Maestro Houfeng la última vez, ¿recuerdas?",
  ui_story_5089_50890901_46_dialog_content = "Maestro Houfeng... ¿Te refieres al inventor de hace diez años?",
  ui_story_5089_50890901_47_dialog_content = "Por lo que recuerdo, era un artesano pícaro que se negó a aliarse con cualquier facción, e intentó aprender de todas las fuentes imaginables.",
  ui_story_5089_50890901_48_dialog_content = "Se suponía que era muy talentoso, pero también algo arrogante por ello. Aunque ambas facciones intentaron persuadirlo para que se uniera a ellos, siempre los rechazó.",
  ui_story_5089_50890901_49_dialog_content = "Y después de unirse a la corte como asesor, era conocido por proponer muchas ideas radicales de reforma.",
  ui_story_5089_50890901_50_dialog_content = "Propuso levantar las restricciones comerciales sobre las creaciones de relojería e instituir el control del tribunal sobre los recursos para todas las facciones.",
  ui_story_5089_50890901_51_dialog_content = "Su fervor por servir a su país era innegable, pero sus acciones eran demasiado extremas y no consideraban la realidad.",
  ui_story_5089_50890901_52_dialog_content = "No puedes culpar a nadie más si terminas como él, Lady Xuan Ji. Su ejemplo no debería ser seguido.",
  ui_story_5089_50890901_53_dialog_content = "Lo sé, pero soy un ciudadano perfectamente respetuoso de la ley del reino. ¿No recuerdas lo obediente que fui cuando el rey decidió encerrarme?",
  ui_story_5089_50890901_54_dialog_content = "Parece que has olvidado la razón por la que te encerraron en primer lugar.",
  ui_story_5089_50890901_55_dialog_content = "Cualquiera que sea la razón, estoy seguro de que no tenía nada que ver conmigo manipulando los blásters arcanos que personalmente ayudé a diseñar.",
  ui_story_5089_50890901_56_dialog_content = "Muy bien, ahora déjame ver esa carta.",
  ui_story_5089_50890901_57_dialog_content = "... ¡Jajaja! Qué muy interesante. Debería haber esperado tanto de PlayerName.",
  ui_story_5089_50890901_58_dialog_content = "Su estrategia es un poco ortodoxa, pero para mi sorpresa, parece ser la mejor opción dada las circunstancias.",
  ui_story_5089_50890901_59_dialog_content = "Parece que finalmente ve las cosas claramente.",
  ui_story_5089_50890901_60_dialog_content = "¿Y qué sería eso exactamente?",
  ui_story_5089_50890901_61_dialog_content = "No hay nada de qué preocuparse. En cualquier caso, necesitaré que entregues un mensaje en breve.",
  ui_story_5089_50890901_62_dialog_content = "Como un artesano ordinario sin participación en la política, estaría mal involucrarme en estos asuntos.",
  ui_story_5089_50890901_63_dialog_content = "Pero como miembro del gremio, es mi deber proporcionar información si eso significa erradicar a cualquier traidor entre nosotros.",
  ui_story_5089_50890901_64_dialog_content = "Así que por favor haz tu mejor esfuerzo, hermano.",
  ui_story_5089_50890901_65_dialog_content = "Si hermana.",
  ui_story_5089_50890901_66_dialog_content = "Entonces... ¿Cómo te sientes allí, vecino?",
  ui_story_5089_50890901_67_dialog_content = "...",
  ui_story_5089_50890901_68_dialog_content = "Es extraño, pensé que hablar sobre el Maestro Houfeng te haría abrirte.",
  ui_story_5089_50890901_69_dialog_content = "Después de todo, su historia parece tan familiar ahora. Un hombre nombrado en la corte real hace diez años, pero luego se involucró en sus luchas de poder y, cayó en desgracia, nunca más se le vio ni se supo de él.",
  ui_story_5089_50890901_70_dialog_content = "Solo puedo pensar en una persona que cumple con todos esos criterios.",
  ui_story_5089_50890901_71_dialog_content = "... Ya no es asunto mío.",
  ui_story_5089_50890901_72_dialog_content = "Mis obsesiones de toda la vida con la gratitud y la venganza no son más que una broma ahora.",
  ui_story_5089_50890901_73_dialog_content = "Ya no sé cómo manejar mi espada, lo que significa que ya no sirvo para ningún propósito.",
  ui_story_5089_50890901_74_dialog_content = "Así que por favor deje de preocuparse por mí, Lady Xuan Ji.",
  ui_story_5089_50890901_75_dialog_content = "Vivir para un solo propósito, y merecer ser abandonado si ya no puedes lograrlo.",
  ui_story_5089_50890901_77_dialog_content = "Tengo una pregunta para ti, señorita Jiu.",
  ui_story_5089_50890901_79_dialog_content = "...",
  ui_story_5089_50890901_80_dialog_content = "¿Incluso hay alguna diferencia?",
  ui_story_5089_50890901_81_dialog_content = "Suspiro... Parece que no voy a progresar mucho aquí en poco tiempo.",
  ui_story_5089_50890901_82_dialog_content = "Ahora depende de ti, mi amigo.",
  ui_story_5089_50890901_83_dialog_content = "...",
  ui_story_5089_50890901_84_dialog_content = "¿Algo te molesta, PlayerName?",
  ui_story_5089_50890901_86_dialog_content = "¿Perdón?",
  ui_story_5089_50890901_87_dialog_content = "Eh, no es nada. ¿Estabas diciendo algo hace un momento?",
  ui_story_5089_50890901_88_dialog_content = "Sí. Estaba diciendo que si los Fate Riders realmente quisieran superar nuestros obstáculos, no podríamos detenerlos.",
  ui_story_5089_50890901_89_dialog_content = "Es por eso que sugiero que pidamos refuerzos.",
  ui_story_5089_50890901_90_dialog_content = "La ciudad de Jingliang solo puede albergar a tantos soldados dentro de sus muros, por lo que la mayoría de ellos están estacionados fuera de la ciudad.",
  ui_story_5089_50890901_91_dialog_content = "Puede que no sean tan poderosos como los soldados dentro de la ciudad, pero aún estamos claramente en desventaja numérica.",
  ui_story_5089_50890901_92_dialog_content = "¿Entonces estás pensando en usar tu autoridad como princesa para traer a algunos de ellos a nuestro lado?",
  ui_story_5089_50890901_93_dialog_content = "¡No, PlayerName!",
  ui_story_5089_50890901_94_dialog_content = "Espera... ¿Por qué de repente me estás entregando una daga?!",
  ui_story_5089_50890901_95_dialog_content = "Pueden estar estacionados fuera de la ciudad, pero eso no los hace menos unificados como soldados. A estas alturas, las noticias desde dentro de la ciudad ya deben haberles llegado.",
  ui_story_5089_50890901_96_dialog_content = "Ambos sabemos que, en este punto, mi \"tío\" no tiene ninguna razón para mantener su mano contra mí.",
  ui_story_5089_50890901_97_dialog_content = "Es seguro asumir que no me obedecerán si me revelo ante ellos.",
  ui_story_5089_50890901_98_dialog_content = "¿Entonces por qué estamos aquí?",
  ui_story_5089_50890901_99_dialog_content = "Por esto.",
  ui_story_5089_50890901_100_dialog_content = "... ¿Por qué me estás dando una daga?",
  ui_story_5089_50890901_101_dialog_content = "No podemos estar seguros sobre las órdenes dadas a los soldados en este lugar.",
  ui_story_5089_50890901_102_dialog_content = "Pero mientras a mi \"tío\" le importe su estatus, no enviará abiertamente a alguien para asesinarme.",
  ui_story_5089_50890901_103_dialog_content = "Si ese es el caso, entonces debería seguir siendo visto como alguien que requiere su protección. Como tal...",
  ui_story_5089_50890901_104_dialog_content = "¿Quieres que finja secuestrarte y los lleve a todos hasta el taller?",
  ui_story_5089_50890901_105_dialog_content = "¡Pero eso es demasiado arriesgado! ¡No hay forma de saber qué podría salir mal!",
  ui_story_5089_50890901_106_dialog_content = "¿Y si logran capturarnos a ambos a la vez? ¿O peor aún, qué pasa si el falso rey ya decidió que no vales la pena mantener vivo?!",
  ui_story_5089_50890901_107_dialog_content = "Deberíamos regresar y replantear nuestra estrategia antes de-",
  ui_story_5089_50890901_108_dialog_content = "<color=#e8d9bb>De repente, Dantang agarra la mano que estoy usando para sostener la daga, y la lleva rápidamente a su cuello.</color>",
  ui_story_5089_50890901_109_dialog_content = "¿Dantang?!",
  ui_story_5089_50890901_110_dialog_content = "<color=#e8d9bb>Intento desesperadamente alejarlo, pero la daga aún deja una marca roja en su cuello.</color>",
  ui_story_5089_50890901_111_dialog_content = "Por favor mírame, PlayerName.",
  ui_story_5089_50890901_112_dialog_content = "<color=#e8d9bb>Una gota de sangre se desliza por la hoja hasta mi palma, pero Dantang simplemente se ríe bajo la luz del sol, filtrándose a través de las hojas del bosque.</color>",
  ui_story_5089_50890901_113_dialog_content = "Confío en ti.",
  ui_story_5089_50890901_114_dialog_content = "... Lo sé.",
  ui_story_5089_50890901_115_dialog_content = "¿Quién va allí?",
  ui_story_5089_50890901_116_dialog_content = "¡S-Quédate atrás!",
  ui_story_5089_50890901_117_dialog_content = "¡Tu Princesa Zhuohua está en mis manos ahora!",
  ui_story_5089_50890901_118_dialog_content = "!",
  ui_story_5089_50890901_119_dialog_content = "¡La princesa ha sido secuestrada! ¡Todos los soldados reúnanse!",
  ui_story_5089_50890901_120_dialog_content = "¡Suelta a la princesa inmediatamente, y tu vida aún puede ser perdonada!",
  ui_story_5089_50890901_121_dialog_content = "¡Ustedes no me asustan! ¿Y además, realmente creen que me rendiría tan fácilmente?!",
  ui_story_5089_50890901_122_dialog_content = "¡Soy un miembro de los Jinetes del Destino, y nuestro bastión no está demasiado lejos de aquí! ¡Tenemos más luchadores y armas de las que puedes manejar!",
  ui_story_5089_50890901_123_dialog_content = "¡Así que no hagas movimientos bruscos, o tendremos una guerra en nuestras manos!",
  ui_story_5089_50890901_124_dialog_content = "¡Arquero! ¡Apunta!",
  ui_story_5089_50890901_125_dialog_content = "¡Potencia de fuerza!",
  ui_story_5089_50890901_126_dialog_content = "Urgh—",
  ui_story_5089_50890901_127_dialog_content = "¡No dejes que se escape!",
  ui_story_5089_50890901_128_dialog_content = "¡Hemos perdido de vista a la princesa y a su secuestrador, señor!",
  ui_story_5089_50890901_129_dialog_content = "¡Entonces dispersense y busquen, tonto! ¡No podemos permitir que le pase algo a la princesa!",
  ui_story_5089_50890901_130_dialog_content = "Pero no tenemos pistas para—¡Espera! ¡Hay una begonia en el suelo por aquí!",
  ui_story_5089_50890901_131_dialog_content = "Debe ser una pista dejada por la princesa. ¡Rápido, busca más de ellas!",
  ui_story_5089_50890901_132_dialog_content = "¡Pueden llevarnos a su escondite!",
  ui_story_5089_50890901_133_dialog_content = "Mi señor, un grupo de soldados de fuera de la ciudad se acerca al taller.",
  ui_story_5089_50890901_134_dialog_content = "¿Por qué razón?",
  ui_story_5089_50890901_135_dialog_content = "Dicen que se encontraron con un delincuente que ha secuestrado a la princesa.",
  ui_story_5089_50890901_136_dialog_content = "Sin atreverse a perderles la pista, el capitán de su escuadrón siguió su rastro hasta esta ubicación.",
  ui_story_5089_50890901_137_dialog_content = "Así que no solo están bloqueadas las carreteras, sino que también estamos rodeados por guardias de la ciudad.",
  ui_story_5089_50890901_138_dialog_content = "Es probable que pronto estalle un asedio.",
  ui_story_5089_50890901_139_dialog_content = "Si eso sucediera, nuestra gente debería ser capaz de defender el taller. Sugiero que los mantengamos en posición por el momento.",
  ui_story_5089_50890901_140_dialog_content = "Sin embargo, todavía insisten en ver qué está pasando aquí.",
  ui_story_5089_50890901_141_dialog_content = "Je.",
  ui_story_5089_50890901_142_dialog_content = "¿Así que esa es su estrategia, verdad? Patético.",
  ui_story_5089_50890901_143_dialog_content = "Ve.",
  ui_story_5089_50890901_144_dialog_content = "Si desean que me revele, entonces como rey, me enfrentaré a ellos con gusto.",
  ui_story_5089_50890901_145_dialog_content = "<color=#e8d9bb>Momentos después—</color>",
  ui_story_5089_50890901_146_dialog_content = "Gracias a Dios, finalmente se fueron.",
  ui_story_5089_50890901_147_dialog_content = "Dicen que es más oscuro debajo de la lámpara, pero siempre encuentro que esconderme justo debajo de la nariz del enemigo es la opción más segura.",
  ui_story_5089_50890901_148_dialog_content = "Aun así, nunca esperé que él simplemente se sentara aquí y cavilara todo el día. Incluso con el palacio en un estado tan lamentable, nunca llamó a nadie para arreglarlo.",
  ui_story_5089_50890901_149_dialog_content = "Pero gracias a estas vigas anchas, he permanecido oculto sin forzar demasiado mis pobres huesos viejos.",
  ui_story_5089_50890901_150_dialog_content = "Ahora que se han ido, debería poder salir del palacio sin ningún problema.",
  ui_story_5089_50890901_151_dialog_content = "¿Mm? ¿No es esta... la espada de la señorita Jiu?",
  ui_story_5089_50890901_152_dialog_content = "Supongo que debería devolvérselo a ella.",
  ui_story_5089_50890901_153_dialog_content = "*Jadeando* Caray... Todo este tiempo... He estado corriendo lo más rápido que puedo...",
  ui_story_5089_50890901_154_dialog_content = "¿Cómo lograron esos soldados alcanzarnos tan rápido?!",
  ui_story_5089_50890901_155_dialog_content = "Intenté distraerlos con mis begonias lo mejor que pude, pero vieron a través de ello más rápido de lo que imaginé.",
  ui_story_5089_50890901_156_dialog_content = "Además, su caza implacable demuestra que su entrenamiento no es deficiente, incluso fuera de la ciudad.",
  ui_story_5089_50890901_157_dialog_content = "Para que mi \"tío\" mantenga a soldados tan bien entrenados bajo su mando y ese arsenal de armas...",
  ui_story_5089_50890901_158_dialog_content = "¿Qué podrían estar planeando los Fate Riders...?",
  ui_story_5089_50890901_159_dialog_content = "No sirve de nada pensar en ello ahora. Ya hemos hecho todo lo que podemos hacer.",
  ui_story_5089_50890901_160_dialog_content = "Solo recuperemos el aliento aquí por un rato.",
  ui_story_5089_50890901_161_dialog_content = "No he visto ningún movimiento proveniente del taller, pero no se puede predecir cómo reaccionarán una vez que nos vean.",
  ui_story_5089_50890901_162_dialog_content = "<color=#e8d9bb>Detrás de nosotros, los soldados bien entrenados se despliegan y nos rodean. Las antorchas en sus manos pintan el cielo nocturno de un rojo ardiente.</color>",
  ui_story_5089_50890901_163_dialog_content = "<color=#e8d9bb>Ante nosotros, el taller muestra signos de actividad a pesar de que no se ve a nadie. Se cierne sobre nosotros de manera inquietante, como una bestia enorme preparándose para saltar.",
  ui_story_5089_50890901_164_dialog_content = "Nunca tuve la oportunidad de decírtelo antes, PlayerName.",
  ui_story_5089_50890901_165_dialog_content = "Aunque pedí descaradamente tu ayuda, nunca tuve la intención de ponerte en una situación tan peligrosa hoy.",
  ui_story_5089_50890901_166_dialog_content = "Por esto, lo siento terriblemente.",
  ui_story_5089_50890901_167_dialog_content = "No te preocupes, Dantang. Tengo la sensación de que estaremos bien.",
  ui_story_5089_50890901_168_dialog_content = "Después de todo, también confío en ti.",
  ui_story_5089_50890901_169_dialog_content = "¿Eh? Algo está pasando con los soldados...",
  ui_story_5089_50890901_170_dialog_content = "El rey ha llegado—",
  ui_story_5089_50890901_171_dialog_content = "Mira, es...",
  ui_story_5089_50890901_172_dialog_content = "Mi supuesto tío.",
  ui_story_5089_50890901_173_dialog_content = "Oh Dantang, pensé que serías más inteligente que esto.",
  ui_story_5089_50890901_174_dialog_content = "¿No sabes que con una sola orden mía, ese taller permanecerá completamente intacto?",
  ui_story_5089_50890901_175_dialog_content = "Sois los únicos que encontrarán su fin aquí, en un lugar donde nadie os encontrará jamás.",
  ui_story_5089_50890901_176_dialog_content = "Has caminado directamente hacia tus propias tumbas.",
  ui_story_5089_50890901_177_dialog_content = "Si realmente fueras mi tío, tendrías la autoridad para deshacerte de nosotros de esa manera.",
  ui_story_5089_50890901_178_dialog_content = "¡Pero no tienes derecho a hacerlo como un impostor y un títere!",
  ui_story_5089_50890901_179_dialog_content = "¡Ante todas estas personas, te expondremos por quien realmente eres—Maestro Houfeng!",
  ui_story_5089_50890902_1_dialog_content = "¡Ahora, PlayerName!",
  ui_story_5089_50890902_2_dialog_content = "¡Potencia de fuerza!",
  ui_story_5089_50890902_3_dialog_content = "Urgh...",
  ui_story_5089_50890902_4_dialog_content = "(Estos soldados no son nuestro objetivo, por lo que no deberíamos perder tiempo luchando contra ellos.)",
  ui_story_5089_50890902_5_dialog_content = "(Los Fate Riders usan máscaras similares a la carne para ocultarse.)",
  ui_story_5089_50890902_6_dialog_content = "(Todo lo que necesito es una sola oportunidad... ¡Para desgarrar su máscara—!)",
  ui_story_5089_50890902_7_dialog_content = "¡¿Qué?!",
  ui_story_5089_50890902_8_dialog_content = "<color=#e8d9bb>La daga encuentra su marca a lo largo del rostro del falso rey.</color>",
  ui_story_5089_50890902_9_dialog_content = "<color=#e8d9bb>Pero lo que corta no es la máscara inorgánica que esperaban.</color>",
  ui_story_5089_50890902_10_dialog_content = "<color=#e8d9bb>Más bien, la sangre comienza a filtrarse desde la herida, indicando que el rostro del objetivo es completamente real.</color>",
  ui_story_5089_50890902_11_dialog_content = "Cómo podría ser esto...?",
  ui_story_5089_50890902_12_dialog_content = "Está todo menos confirmado ahora.",
  ui_story_5089_50890902_13_dialog_content = "Dime, ¿los resultados fueron de tu agrado?",
  ui_story_5089_50891001_1_dialog_content = "¡S-Su Alteza...! ¡No se queden ahí parados, tontos! ¡Defiendan al rey!",
  ui_story_5089_50891001_2_dialog_content = "Bajen las armas, todos ustedes. Esto no es más que un niño haciendo un alboroto.",
  ui_story_5089_50891001_3_dialog_content = "No... No puedes ser el verdadero Rey de Ye, entonces ¿por qué...?",
  ui_story_5089_50891001_4_dialog_content = "Si todo tu intrigante plan fue para este singular momento, entonces tu estupidez es aún mayor de lo que imaginé.",
  ui_story_5089_50891001_5_dialog_content = "He estado usando esta identidad durante tantos años, y nadie ha notado nada inusual.",
  ui_story_5089_50891001_6_dialog_content = "¿De verdad pensaste que esto se podría lograr con algo tan simple como una máscara?",
  ui_story_5089_50891001_7_dialog_content = "!",
  ui_story_5089_50891001_8_dialog_content = "Por supuesto que no. Durante los últimos diez años, he estado haciendo pequeños ajustes graduales a mi apariencia.",
  ui_story_5089_50891001_9_dialog_content = "Cortando y tallando a través de mi propia carne y huesos, todo para lograr el disfraz perfecto.",
  ui_story_5089_50891001_10_dialog_content = "Cuando mis brazos no eran lo suficientemente largos, me los rompí para que crecieran más.",
  ui_story_5089_50891001_11_dialog_content = "Cuando mi voz no coincidía del todo, hice gárgaras con veneno para remodelar mi garganta y cuerdas vocales.",
  ui_story_5089_50891001_12_dialog_content = "Me dijeron que antes de ascender al trono, mi tío a menudo era el objetivo de asesinatos... Ya veo.",
  ui_story_5089_50891001_13_dialog_content = "Ciertamente has ido más allá por los Fate Riders.",
  ui_story_5089_50891001_14_dialog_content = "¿Los Fate Riders, dices? ¡Ja! Esos cobardes no son diferentes a las ratas que infestan las sombras del imperio.",
  ui_story_5089_50891001_15_dialog_content = "¡Esos insolentes roedores están muy equivocados si creen que pueden desafiar al legítimo rey del Reino de Ye!",
  ui_story_5089_50891001_16_dialog_content = "Tú...",
  ui_story_5089_50891001_17_dialog_content = "Nuestro ritual anual de supresión ha comenzado a fallarnos, y el nuevo emperador es demasiado joven e inexperto para guiarnos a través de la tormenta que se avecina. Si nada cambia, nuestras tierras pronto serán sumergidas en la oscuridad.",
  ui_story_5089_50891001_18_dialog_content = "Al principio, tenía la intención de proceder con cuidado para mantener nuestra relación con el Reino Ji.",
  ui_story_5089_50891001_19_dialog_content = "Pero con las cosas como están ahora, no veo ningún problema en entregar todas nuestras armas a los Fate Riders.",
  ui_story_5089_50891001_20_dialog_content = "Con esas armas de fuego en mano, su rebelión comenzará aún más pronto.",
  ui_story_5089_50891001_21_dialog_content = "Durante años, los Jinetes del Destino han infiltrado las cortes de los diversos reinos de Longzhou. La inundación de Haojin solo demostró lo que les sucederá al resto de los estados vasallos. Una vez que estén ocupados con sus propias crisis, los Jinetes del Destino volverán a apuntar a la capital imperial de Yangjing.",
  ui_story_5089_50891001_22_dialog_content = "Mientras la mantis acecha a la cigarra, el gorrión espera pacientemente para reclamar los despojos de su batalla.",
  ui_story_5089_50891001_23_dialog_content = "Durante años, aguardé mi tiempo, esperando la ráfaga de viento perfecta, pero nunca llegó.",
  ui_story_5089_50891001_24_dialog_content = "Me niego a esperar más. ¡Seré el viento que me lleve a la victoria!",
  ui_story_5089_50891001_25_dialog_content = "A lo largo de diez largos años, he entrenado a mis tropas incansablemente para que estén listas para la guerra en cualquier momento.",
  ui_story_5089_50891001_26_dialog_content = "Cuando las fuerzas de estas tierras finalmente choquen, el vencedor no necesariamente será decidido por el poder de los Jinetes del Destino.",
  ui_story_5089_50891001_27_dialog_content = "Has descubierto mi secreto, Dantang.",
  ui_story_5089_50891001_28_dialog_content = "Pero a pesar de tu necedad, tus talentos aún valorarían enormemente el reino. ¿Estás dispuesto a seguirme como tu rey?",
  ui_story_5089_50891001_29_dialog_content = "Simplemente asiente con la cabeza, y te garantizo que seguirás siendo la Princesa Zhuohua del Reino de Ye.",
  ui_story_5089_50891001_30_dialog_content = "En cuanto a ti, Caelestite, tus habilidades también serían de uso indiscutible para mí en la batalla. ¿Te alinearás con mis nobles objetivos?",
  ui_story_5089_50891001_31_dialog_content = "Porque pronto, los siete reinos de Longzhou caerán bajo mi gobierno...",
  ui_story_5089_50891001_32_dialog_content = "¿Eres consciente de que los Fate Riders han estado coludiendo con los espíritus malvados, y que innumerables vidas se han perdido como resultado de su traición?",
  ui_story_5089_50891001_33_dialog_content = "Por supuesto. Estoy completamente al tanto de sus métodos, dado que el Reino Ye es la principal fuente de sus armas.",
  ui_story_5089_50891001_34_dialog_content = "¿Pero por qué debería preocuparme por las vidas de los demás cuando no pueden ser útiles para mí? Preocuparse por los sujetos de mis enemigos mortales es mostrar debilidad como conquistador.",
  ui_story_5089_50891001_35_dialog_content = "En cuanto a los espíritus malvados, no son diferentes a los animales salvajes. Si los Jinetes del Destino tienen la desfachatez de emplearlos en sus métodos, entonces que así sea.",
  ui_story_5089_50891001_36_dialog_content = "Siempre puedo deshacerme de ellos más tarde, si la necesidad lo exige.",
  ui_story_5089_50891001_37_dialog_content = "Entiendo tus puntos de vista, pero parece—",
  ui_story_5089_50891001_38_dialog_content = "Que nuestros caminos son demasiado diferentes para estar alguna vez alineados.",
  ui_story_5089_50891001_39_dialog_content = "Sugiero fuertemente que no me desafíes, princesa.",
  ui_story_5089_50891001_40_dialog_content = "Uh... ¿Podría preguntarte algo?",
  ui_story_5089_50891001_41_dialog_content = "¿Realmente está bien que digas todo esto en voz alta?",
  ui_story_5089_50891001_42_dialog_content = "Hay un taller lleno de Fate Riders justo al lado de nosotros.",
  ui_story_5089_50891001_43_dialog_content = "Ya he ordenado a mi gente que cierre ese taller. A diferencia de ti, me esfuerzo mucho para preparar mi próximo movimiento.",
  ui_story_5089_50891001_44_dialog_content = "Los Fate Riders aspiran a lograr grandes cosas pero aún dependen de mi potencia de fuego.",
  ui_story_5089_50891001_45_dialog_content = "Una vez que las armas hayan sido entregadas, no tengo motivo para preocuparme si las personas en ese taller viven o mueren.",
  ui_story_5089_50891001_46_dialog_content = "¿Entonces qué sucederá si no puedes entregar tus armas en los próximos tres días?",
  ui_story_5089_50891001_47_dialog_content = "... ¿Cómo te enteraste de eso?",
  ui_story_5089_50891001_48_dialog_content = "Bueno, me han dicho que mis habilidades como Celestita son innegablemente útiles.",
  ui_story_5089_50891001_49_dialog_content = "Pero más al grano, estoy bastante seguro de que ya no vas a cumplir con tu fecha límite.",
  ui_story_5089_50891001_50_dialog_content = "¿Qué has hecho?",
  ui_story_5089_50891001_51_dialog_content = "¡Gran Rey! Ha habido un problema—",
  ui_story_5089_50891001_52_dialog_content = "¡Hablar!",
  ui_story_5089_50891001_53_dialog_content = "¡Es el Gremio de Artesanos! ¡Sus personas están desmantelando las pistas del Portador Huolong mientras hablamos! ¡Todas nuestras rutas de transporte originalmente planificadas están fuera de servicio!",
  ui_story_5089_50891001_54_dialog_content = "¿¡Quién permitió que sucediera tal cosa!?",
  ui_story_5089_50891001_55_dialog_content = "El gremio afirma que—",
  ui_story_5089_50891001_56_dialog_content = "Un filántropo adinerado hizo una generosa donación para algunas reparaciones muy necesarias, eso es todo.",
  ui_story_5089_50891001_57_dialog_content = "Las vías estaban completamente desgastadas debido al descuido y mal uso por parte de los operadores de transporte.",
  ui_story_5089_50891001_58_dialog_content = "Mi única condición era especificar el orden en el que se reparaban las pistas. Una petición bastante simple, ¿verdad?",
  ui_story_5089_50891001_59_dialog_content = "Incluso nos ayudó a dirigir su atención hacia un problema muy serio que afecta a su reino.",
  ui_story_5089_50891001_60_dialog_content = "Ya han realizado gran parte del trabajo de desmantelamiento. Incluso si comenzaras a reconstruir las pistas ahora mismo, te llevaría más de tres días terminarlas.",
  ui_story_5089_50891001_61_dialog_content = "Desde el principio, este era el \"camino\" que quería tomar... Si me perdonas el juego de palabras.",
  ui_story_5089_50891001_62_dialog_content = "¡Tus trucos sucios nunca tendrán éxito! Todo lo que se necesita es una orden del rey para—",
  ui_story_5089_50891001_63_dialog_content = "¡Silencio, tonto!",
  ui_story_5089_50891001_64_dialog_content = "Tal vez tengas razón: tal vez mis tácticas realmente sean deshonestas.",
  ui_story_5089_50891001_65_dialog_content = "Pero deberías saber a estas alturas que ya no nos centramos en los medios.",
  ui_story_5089_50891001_66_dialog_content = "Para que el Gremio de Artesanos se alíe contigo... ¿Fue esto obra de la Ministra Armilla?",
  ui_story_5089_50891001_67_dialog_content = "No fue encarcelada por manipular los blásteres arcanos, sino por descubrir tu secreto. ¿No es así, \"Su Alteza\"?",
  ui_story_5089_50891001_68_dialog_content = "Desde el momento en que no lograste encerrarla completamente, perdiste.",
  ui_story_5089_50891001_69_dialog_content = "Incluso si logras aferrarte al trono del Reino de Ye—",
  ui_story_5089_50891001_70_dialog_content = "Cada funcionario de la corte y artesano en Longzhou puede estar observando todos tus movimientos desde las sombras ahora.",
  ui_story_5089_50891001_71_dialog_content = "Hoy, las vías del transportador están siendo desmanteladas, pero mañana, podría haber una falla en un buey de madera.",
  ui_story_5089_50891001_72_dialog_content = "Incluso si cambias a un carruaje tirado por caballos, los caballos pueden no ser lo suficientemente fuertes para mantener las cosas en movimiento.",
  ui_story_5089_50891001_73_dialog_content = "Sin los Transportistas Huolong, imagino que sería imposible transportar grandes cantidades de carga rápidamente.",
  ui_story_5089_50891001_74_dialog_content = "Pero la cosa más importante, por supuesto...",
  ui_story_5089_50891001_75_dialog_content = "¿Qué tan difícil sería explicar a tu reino por qué estás enviando tantas armas de fuego fuera del país?",
  ui_story_5089_50891001_76_dialog_content = "...",
  ui_story_5089_50891001_77_dialog_content = "Mis disculpas, \"Su Alteza\".",
  ui_story_5089_50891001_78_dialog_content = "Independientemente de lo que suceda a continuación...",
  ui_story_5089_50891001_79_dialog_content = "El \"impulso\" actualmente está a mi favor.",
  ui_story_5089_50891001_80_dialog_content = "Comprendo.",
  ui_story_5089_50891001_81_dialog_content = "El camino que estás bloqueando no es el del destino, sino el mío.",
  ui_story_5089_50891001_82_dialog_content = "Cuando dijiste que estábamos entrando en una trampa, ¿alguna vez consideraste que en realidad estábamos preparando la trampa para ti?",
  ui_story_5089_50891001_83_dialog_content = "Te has quedado sin opciones, Maestro Houfeng.",
  ui_story_5089_50891001_84_dialog_content = "Si no logras entregar las armas a tiempo, los Fate Riders vendrán inevitablemente a investigar.",
  ui_story_5089_50891001_85_dialog_content = "Basándome en lo que acabas de decir, tu lealtad a Junming es cuestionable en el mejor de los casos. Me temo que tus acciones pueden no resistir su escrutinio.",
  ui_story_5089_50891001_86_dialog_content = "¿Ahora podemos sentarnos y tener una discusión civilizada, por favor?",
  ui_story_5089_50891001_88_dialog_content = "¿Una discusión civilizada, dices? ¡Jajaja! ¿Has olvidado que todavía soy el rey?",
  ui_story_5089_50891001_89_dialog_content = "¡El destino del Reino Ye descansa únicamente en mis manos!",
  ui_story_5089_50891001_90_dialog_content = "¡Me niego a dejar que cualquiera de ustedes obstaculice mi—!",
  ui_story_5089_50891001_91_dialog_content = "<color=#e8d9bb>Esfuerzo supremo—</color>",
  ui_story_5089_50891001_92_dialog_content = "<color=#e8d9bb>Se escucha el sonido amortiguado de una espada entrando en la carne.</color>",
  ui_story_5089_50891001_93_dialog_content = "<color=#e8d9bb>Poco después, la sangre comienza a salpicar en todas direcciones.</color>",
  ui_story_5089_50891001_94_dialog_content = "¡Houfeng—!",
  ui_story_5089_50891001_95_dialog_content = "<color=#e8d9bb>Desde atrás, un afilado gancho de metal atraviesa el cuerpo del falso rey.</color>",
  ui_story_5089_50891001_96_dialog_content = "¡Eso es... Un aguijón!",
  ui_story_5089_50891001_97_dialog_content = "*suspiro* ¿Por qué no podrías haberte quedado callado y seguido las órdenes?",
  ui_story_5089_50891001_98_dialog_content = "A diferencia de mis hermosas creaciones de relojería, que son el resultado de una extensa investigación y una planificación paciente...",
  ui_story_5089_50891001_99_dialog_content = "Las ambiciones imprudentes e irreales como las tuyas pueden ser mortales.",
  ui_story_5089_50891001_100_dialog_content = "Tú... ¡Cómo te atreves...!",
  ui_story_5089_50891001_101_dialog_content = "La princesa hizo un punto válido.",
  ui_story_5089_50891001_102_dialog_content = "Subestimas demasiado a los Fate Riders.",
  ui_story_5089_50891001_103_dialog_content = "Mi maestro ha decretado que Ye Kingdom ya no nos sirve de ningún propósito.",
  ui_story_5089_50891001_104_dialog_content = "Se me ha dado rienda suelta sobre tus tierras, ¡y comenzaré probando todo el poder de fuego de mi Stinger!",
  ui_story_5089_50891001_105_dialog_content = "Y todo se lo debo a ti, poderoso rey. ¡Si no me hubieras dado la Llama Zhuyin, nada de esto habría sucedido! ¡Jajaja!",
  ui_story_5089_50891001_106_dialog_content = "Ahora bien... Creo que mis órdenes eran arrasar esa montaña de allí.",
  ui_story_5089_50891001_107_dialog_content = "Ajusta los objetivos y comienza a cargar, Stinger. Todavía tenemos mucho trabajo por hacer.",
  ui_story_5089_50891001_108_dialog_content = "<color=#e8d9bb>El Aguijón arranca violentamente su cola del falso rey, quien se desploma en el suelo.</color>",
  ui_story_5089_50891001_109_dialog_content = "¡Es correcto, casi me olvido de este traidor inútil...",
  ui_story_5089_50891001_110_dialog_content = "¡Por orden de los Jinetes del Destino, ejecuten a este hombre!",
  ui_story_5089_50891001_111_dialog_content = "Su Alteza—",
  ui_story_5089_50891001_112_dialog_content = "<color=#e8d9bb>Los guardias reales se preparan para irrumpir, pero algo lanza sus filas en un pandemonio completo.</color>",
  ui_story_5089_50891001_113_dialog_content = "<color=#e8d9bb>Para su total asombro, varios soldados levantan sus armas y comienzan a atacar a sus camaradas!</color>",
  ui_story_5089_50891001_114_dialog_content = "¡Esto no es bueno! El rey está en—",
  ui_story_5089_50891001_115_dialog_content = "¡Begonias brillantes!",
  ui_story_5089_50891001_116_dialog_content = "Tú...",
  ui_story_5089_50891001_117_dialog_content = "No te equivoques, no tengo intención de aliarme contigo.",
  ui_story_5089_50891001_118_dialog_content = "Pero mientras tú vivas, podemos contrarrestar a los Fate Riders.",
  ui_story_5089_50891001_119_dialog_content = "También está el asunto de hacerte responsable de tus crímenes.",
  ui_story_5089_50891001_120_dialog_content = "Tos... ¿Por qué molestarse...?",
  ui_story_5089_50891001_121_dialog_content = "Si no escapas ahora... No vivirás... Para arrepentirte.",
  ui_story_5089_50891001_122_dialog_content = "Mi único arrepentimiento es que no arriesgué todo y te reemplacé antes.",
  ui_story_5089_50891001_123_dialog_content = "Al pie de esa montaña hay innumerables civiles inocentes, así como los campos que los nutren y sostienen.",
  ui_story_5089_50891001_124_dialog_content = "Si huyera ahora mismo, nunca podría llamarme princesa del Reino de Ye nunca más.",
  ui_story_5089_50891001_125_dialog_content = "Así que aquí estoy, y PlayerName no es diferente. ¡Es demasiado tarde para dar la vuelta y huir ahora!",
  ui_story_5089_50891001_126_dialog_content = "Je... Qué sorpresa... Nunca lo supe...",
  ui_story_5089_50891001_127_dialog_content = "Estabas aún más arrogante que yo.",
  ui_story_5089_50891001_128_dialog_content = "Pero las palabras no significan nada... Si no logras sobrevivir.",
  ui_story_5089_50891001_129_dialog_content = "<color=#e8d9bb>Mientras los guardias reales continúan su batalla entre ellos, ¡otro grupo de asesinos Jinete del Destino sale corriendo del taller!</color>",
  ui_story_5089_50891002_1_dialog_content = "Si la batalla continúa así, me temo que las probabilidades estarán en nuestra contra.",
  ui_story_5089_50891002_2_dialog_content = "Señorita Jiu.",
  ui_story_5089_50891002_3_dialog_content = "¿De verdad no tienes nada que decir sobre todo esto?",
  ui_story_5089_50891002_4_dialog_content = "...",
  ui_story_5089_50891002_5_dialog_content = "¿Eh...?",
  ui_story_5089_50891002_6_dialog_content = "¡¿Quién está ahí?!",
  ui_story_5089_50891002_7_dialog_content = "Nuestro maestro nos ha ordenado exterminar a aquellos que se interpongan en nuestro camino.",
  ui_story_5089_50891002_8_dialog_content = "Hmph, así que también se han infiltrado en el palacio.",
  ui_story_5089_50891002_9_dialog_content = "¡Relámpago Destello!",
  ui_story_5089_50891002_10_dialog_content = "...",
  ui_story_5089_50891002_11_dialog_content = "!",
  ui_story_5089_50891002_12_dialog_content = "¡Fuera de mi camino!",
  ui_story_5089_50891002_13_dialog_content = "Señorita Jiu, incluso si decides ignorar todo lo demás que está sucediendo a tu alrededor...",
  ui_story_5089_50891002_14_dialog_content = "¿Vas a dejarte matar realmente por estas ratas que son demasiado cobardes para mostrar sus propias caras?!",
  ui_story_5089_50891002_15_dialog_content = "...",
  ui_story_5089_50891101_1_dialog_content = "Eurgh—",
  ui_story_5089_50891101_2_dialog_content = "¡Sigue así, Dantang! Casi estamos—Ugh...",
  ui_story_5089_50891101_3_dialog_content = "¡PlayerName! Oh no... ¡Estás ardiendo!",
  ui_story_5089_50891101_4_dialog_content = "Está bien; solo he abusado de mis habilidades. Estaré bien pronto...",
  ui_story_5089_50891101_5_dialog_content = "¡Ciertamente no me parece así!",
  ui_story_5089_50891101_6_dialog_content = "... Espera.",
  ui_story_5089_50891101_7_dialog_content = "Nos conocemos lo suficiente como para que entienda bastante bien tus habilidades.",
  ui_story_5089_50891101_8_dialog_content = "Podemos estar superados en número, pero incluso una batalla de esta intensidad no debería ser suficiente para agotarte así.",
  ui_story_5089_50891101_9_dialog_content = "¿Qué más has estado haciendo?",
  ui_story_5089_50891101_10_dialog_content = "... Parece que se acabó la plantilla.",
  ui_story_5089_50891101_11_dialog_content = "Lo siento, he querido decírtelo, pero nunca encontré la oportunidad.",
  ui_story_5089_50891101_12_dialog_content = "Pero ahora... creo que es más rápido simplemente mostrártelo.",
  ui_story_5089_50891101_13_dialog_content = "?",
  ui_story_5089_50891101_14_dialog_content = "¡Escaneo psíquico!",
  ui_story_5089_50891101_15_dialog_content = "Así que, finalmente has llegado.",
  ui_story_5089_50891101_16_dialog_content = "Me has tenido esperando bastante tiempo, princesa.",
  ui_story_5089_50891101_17_dialog_content = "¡Ministra Armilla! Pero... ¿Por qué estás...",
  ui_story_5089_50891101_18_dialog_content = "Por mucho que me gustaría ponerme al día, todavía tengo algunos invitados no deseados con los que lidiar en mi fin.",
  ui_story_5089_50891101_19_dialog_content = "¡Xuan Ji, detrás de ti!",
  ui_story_5089_50891101_20_dialog_content = "¡Relámpago Destello!",
  ui_story_5089_50891101_21_dialog_content = "Muy apreciado, PlayerName.",
  ui_story_5089_50891101_22_dialog_content = "¿Has estado guiando nuestras dos batallas todo este tiempo, PlayerName?! ¡No es de extrañar que tu carga sea tan grande!",
  ui_story_5089_50891101_23_dialog_content = "Si estás preocupado por eso, deberías preguntarle cuánto tiempo ha mantenido su conexión psíquica conmigo. ¡La respuesta podría sorprenderte!",
  ui_story_5089_50891101_24_dialog_content = "...",
  ui_story_5089_50891101_25_dialog_content = "¿PlayerName?",
  ui_story_5089_50891101_26_dialog_content = "E... No ha pasado tanto tiempo... Solo comencé a comunicarme con Xuan Ji ayer.",
  ui_story_5089_50891101_27_dialog_content = "Sí. Para ser exactos, durante un día y una noche entera.",
  ui_story_5089_50891101_28_dialog_content = "Es tu propia culpa por no explicar las cosas más claramente, ¿sabes...",
  ui_story_5089_50891101_29_dialog_content = "Además, he sido cuidadoso de no mantener una conexión poderosa con ella a menos que ocurra una emergencia...",
  ui_story_5089_50891101_30_dialog_content = "Pero para mantener incluso una conexión débil, significa que no has dormido en todo este tiempo.",
  ui_story_5089_50891101_31_dialog_content = "...",
  ui_story_5089_50891101_32_dialog_content = "Tampoco soy el único.",
  ui_story_5089_50891101_33_dialog_content = "Tienes razón... También le debo una disculpa a Jiu.",
  ui_story_5089_50891101_34_dialog_content = "Lo que dijiste anoche me hizo preocuparme de que hicieras algo imprudente, así que me conecté secretamente contigo para estar seguro.",
  ui_story_5089_50891101_35_dialog_content = "También vi tu batalla con el Rey de Ye.",
  ui_story_5089_50891101_36_dialog_content = "Entiendo cómo debes sentirte, pero...",
  ui_story_5089_50891101_37_dialog_content = "¡Cuidado!",
  ui_story_5089_50891101_38_dialog_content = "Ngh...",
  ui_story_5089_50891101_39_dialog_content = "Dantang! ¡¿Estás bien?!",
  ui_story_5089_50891101_40_dialog_content = "!",
  ui_story_5089_50891101_41_dialog_content = "¡Por favor, Jiu! Sé que estás en un lugar terrible ahora mismo, pero necesitamos tu ayuda!",
  ui_story_5089_50891101_42_dialog_content = "Pero... Pero yo...",
  ui_story_5089_50891101_43_dialog_content = "<color=#e8d9bb>Jiu hace una pausa y suelta un suspiro pesado.</color>",
  ui_story_5089_50891101_44_dialog_content = "<color=#e8d9bb>Sin decir nada, ella recoge la daga que el asesino Jinete del Destino dejó caer y se la clava.</color>",
  ui_story_5089_50891101_45_dialog_content = "!",
  ui_story_5089_50891101_46_dialog_content = "<color=#e8d9bb>Esquiva en pánico, pero la daga solo lo roza antes de resbalar de la mano de Jiu y chocar contra la pared.</color>",
  ui_story_5089_50891101_47_dialog_content = "Señorita Jiu, tú...",
  ui_story_5089_50891101_48_dialog_content = "En el pasado, mi espada no era diferente de mi cuerpo.",
  ui_story_5089_50891101_49_dialog_content = "Ya sea herido o manchado de sangre, para mí no hacía ninguna diferencia.",
  ui_story_5089_50891101_50_dialog_content = "El camino de mi espada estaba claro: la gratitud es lo que guiaba cada balanceo y cada golpe.",
  ui_story_5089_50891101_51_dialog_content = "Pero ahora que mi camino ya no está claro, mi habilidad con la espada también me ha abandonado.",
  ui_story_5089_50891101_52_dialog_content = "Como puedes ver, ya no puedo empuñar una hoja.",
  ui_story_5089_50891101_53_dialog_content = "Jiu...",
  ui_story_5089_50891101_54_dialog_content = "Concéntrate en la batalla, PlayerName. Ya no tenemos tiempo para preocuparnos por personas irrelevantes como ella.",
  ui_story_5089_50891101_55_dialog_content = "Al principio tenía dudas, pero ahora veo que aliviarla como mi guardia fue la elección correcta después de todo.",
  ui_story_5089_50891101_56_dialog_content = "¿D-Dantang?",
  ui_story_5089_50891101_57_dialog_content = "Durante diez años, se dedicó al arte de la espada, pero ahora está dispuesta a tirarlo todo sin pensarlo dos veces.",
  ui_story_5089_50891101_58_dialog_content = "Su maestro, el llamado \"mejor espadachín del mundo\", aparentemente no era más que un nombre sin sustancia.",
  ui_story_5089_50891101_59_dialog_content = "... Mi falta de habilidad no es motivo para calumniar el nombre de mi maestro de esta manera, Su Alteza.",
  ui_story_5089_50891101_60_dialog_content = "¿Tu \"maestro\"? ¿Aún puedes llamarlo así como estás ahora?",
  ui_story_5089_50891101_61_dialog_content = "Porque parece que sus enseñanzas ya no se reflejan en tu manejo de la espada.",
  ui_story_5089_50891101_62_dialog_content = "...",
  ui_story_5089_50891101_63_dialog_content = "Si estás tan obsesionado con ajustar cuentas, entonces ajustemos algunas ahora mismo.",
  ui_story_5089_50891101_64_dialog_content = "Has tenido padres que te amaban, vecinos que se preocupaban por ti y maestros que te guiaban.",
  ui_story_5089_50891101_65_dialog_content = "Si no fuera por los esfuerzos de la Capitana Yuebai y la Ministra Armilla a bordo del Shadowind, probablemente estaríamos en el fondo del mar en este momento.",
  ui_story_5089_50891101_66_dialog_content = "Y no olvidemos que PlayerName nunca te ha abandonado, especialmente ahora.",
  ui_story_5089_50891101_67_dialog_content = "Sin embargo, nunca prestaste verdadera atención a la consideración que se te brindó. Qué vergonzoso desperdicio de amabilidad.",
  ui_story_5089_50891101_68_dialog_content = "... Sus percepciones sobre mi carácter son completamente correctas, Su Alteza.",
  ui_story_5089_50891101_69_dialog_content = "Mi deuda con todos ustedes es más de lo que jamás podría pagar. No podría dejar de entender eso.",
  ui_story_5089_50891101_70_dialog_content = "¿Pero qué hay de ti, Lady Dantang?",
  ui_story_5089_50891101_71_dialog_content = "Me considero haber servido fielmente a tu lado, nunca abandonándote ni por un momento.",
  ui_story_5089_50891101_72_dialog_content = "¡Y aún así me dejaste a un lado sin decir otra palabra, como si fuera un par de zapatos desgastados!",
  ui_story_5089_50891101_73_dialog_content = "¿Estás enojado conmigo, Jiu?",
  ui_story_5089_50891101_74_dialog_content = "Y aquí pensé que te habías convertido en nada más que una marioneta sin alma.",
  ui_story_5089_50891101_75_dialog_content = "Lo siento. ¿Le he decepcionado una vez más, Su Alteza?",
  ui_story_5089_50891101_76_dialog_content = "Sí, en realidad.",
  ui_story_5089_50891101_77_dialog_content = "Dado que sabemos que aún eres capaz de emociones, significa que también puedes entender nuestra preocupación por ti.",
  ui_story_5089_50891101_78_dialog_content = "¿Entonces por qué insistes en reprimir tu espada por cosas como la gratitud y la venganza?!",
  ui_story_5089_50891101_79_dialog_content = "Su Alteza...?",
  ui_story_5089_50891101_80_dialog_content = "¡Dantang, detrás de ti—!",
  ui_story_5089_50891101_81_dialog_content = "¡Begonias brillantes!",
  ui_story_5089_50891101_82_dialog_content = "<color=#e8d9bb>Sin mirar atrás, un mar de begonias estalla detrás de Dantang y se extiende en todas direcciones.</color>",
  ui_story_5089_50891101_83_dialog_content = "Hay una última cosa que necesito contarte.",
  ui_story_5089_50891101_84_dialog_content = "No te dejé por tu lealtad a los demás, sino porque no entendiste.",
  ui_story_5089_50891101_85_dialog_content = "<color=#e8d9bb>En un abrir y cerrar de ojos, las begonias florecen hasta donde alcanza la vista.</color>",
  ui_story_5089_50891101_86_dialog_content = "<color=#e8d9bb>Al poner pie en este mar de flores, sus enemigos bajan sus armas y se quedan en un estado de trance.</color>",
  ui_story_5089_50891101_87_dialog_content = "<color=#e8d9bb>En medio de ellos, la apariencia manchada de sangre de Dantang es inimaginablemente cautivadora.</color>",
  ui_story_5089_50891101_88_dialog_content = "\"El universo sigue cincuenta leyes, pero el Cielo guarda cuarenta y nueve secretos, dejando un solo camino para la humanidad.\"",
  ui_story_5089_50891101_89_dialog_content = "Incluso los cielos caprichosos nos dejan un camino, ¿entonces por qué insistes en restringirte de esta manera?",
  ui_story_5089_50891101_90_dialog_content = "Te diré de nuevo las palabras que no pude terminar en la posada.",
  ui_story_5089_50891101_91_dialog_content = "Debe estar enjaulado si buscas admirar el espléndido plumaje de un pájaro.",
  ui_story_5089_50891101_92_dialog_content = "Si buscas admirar el vibrante pelaje de un tigre, debe ser cazado y convertido en un abrigo.",
  ui_story_5089_50891101_93_dialog_content = "Pero esto no es verdadera admiración.",
  ui_story_5089_50891101_94_dialog_content = "Todas las criaturas vivientes nacen libres. Déjalas volar por el cielo y rugir desde las cimas de las montañas si realmente deseas admirarlas.",
  ui_story_5089_50891101_95_dialog_content = "Te obligué a buscar la verdad porque no quiero ser la grillete que te ata para siempre.",
  ui_story_5089_50891101_96_dialog_content = "No deseo que me protejas y obedezcas cada uno de mis caprichos por más tiempo. No quiero que pases el resto de tu vida como una espada oculta en las sombras.",
  ui_story_5089_50891101_97_dialog_content = "Quiero que mantengas la cabeza en alto y vivas libremente bajo la luz del sol.",
  ui_story_5089_50891101_98_dialog_content = "Quiero que tu nombre esté junto al mío en los anales de la historia, no como un silencioso guardián sino como un orgulloso y amado general.",
  ui_story_5089_50891101_99_dialog_content = "Quiero que me sigas por tu propia voluntad.",
  ui_story_5089_50891101_100_dialog_content = "Quiero-",
  ui_story_5089_50891101_101_dialog_content = "¡Ser un verdadero gobernante para ti!",
  ui_story_5089_50891101_102_dialog_content = "Princesa Dantang...",
  ui_story_5089_50891101_103_dialog_content = "Ya no eres mi protector. Ya no tengo derecho a darte órdenes ahora.",
  ui_story_5089_50891101_104_dialog_content = "Pero ahora que ya no estás obligado por el deber, la gratitud o la venganza, si aún estás dispuesto a prestarme tu fuerza...",
  ui_story_5089_50891101_105_dialog_content = "¡Entonces levántate! Arrástrate si es necesario, pero hazlo ahora—",
  ui_story_5089_50891101_106_dialog_content = "Jiu!",
  ui_story_5089_50891101_107_dialog_content = "¡Levántate y quédate a mi lado!",
  ui_story_5089_50891101_108_dialog_content = "... ¿Alguna vez le he dicho lo obstinado que puede ser, Su Alteza?",
  ui_story_5089_50891101_109_dialog_content = "Ni siquiera una vez.",
  ui_story_5089_50891101_110_dialog_content = "Así que ven aquí y dímelo.",
  ui_story_5089_50891101_111_dialog_content = "...",
  ui_story_5089_50891101_112_dialog_content = "Como desees.",
  ui_story_5089_50891101_113_dialog_content = "<color=#e8d9bb>Momentos después.</color>",
  ui_story_5089_50891101_114_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5089_50891101_115_dialog_content = "<color=#e8d9bb>Las puertas del palacio recién reparadas colapsan por segunda vez.</color>",
  ui_story_5089_50891101_116_dialog_content = "¡El convicto está escapando! ¡Tras ella!",
  ui_story_5089_50891101_117_dialog_content = "He vuelto, Hermana Xu—¡Ah! ¿Q-Qué diablos está pasando aquí?!",
  ui_story_5089_50891101_118_dialog_content = "Oh, nada, nuestro invitado más reciente simplemente decidió irse, eso es todo.",
  ui_story_5089_50891101_119_dialog_content = "E-Ese viento que sentí justo ahora... ¿Era ella?!",
  ui_story_5089_50891101_120_dialog_content = "Así es. Mi última pelea me dejó un poco agotado, así que le pedí que nos abriera un camino fuera de la prisión.",
  ui_story_5089_50891101_121_dialog_content = "Honestamente... ¡Oye, espera un minuto!",
  ui_story_5089_50891101_122_dialog_content = "¿Esa chica realmente se fue sin un arma?",
  ui_story_5089_50891101_123_dialog_content = "Por supuesto. Con sus habilidades, podría dividir fácilmente este palacio por la mitad.",
  ui_story_5089_50891101_124_dialog_content = "Tampoco me atrevería a poner una espada en sus manos ahora mismo.",
  ui_story_5089_50891101_125_dialog_content = "¿¡Así que planea enfrentarse al ejército entero del rey completamente desarmada?! ¿¡No te preocupa su seguridad?!",
  ui_story_5089_50891101_126_dialog_content = "¿Qué hay de qué preocuparse?",
  ui_story_5089_50891101_127_dialog_content = "Sé que su tristeza no era mucho para mirar antes, pero ahora—",
  ui_story_5089_50891101_128_dialog_content = "Nadie puede detenerla a menos que ella misma lo permita.",
  ui_story_5089_50891101_129_dialog_content = "¡Ahí está! ¡Rodeen a la fugitiva antes de que intente escapar!",
  ui_story_5089_50891101_130_dialog_content = "Mira, ¡ella está desarmada! ¡Agárrala!",
  ui_story_5089_50891101_131_dialog_content = "Qué ingenuo de tu parte asumir que estoy desarmado.",
  ui_story_5089_50891101_132_dialog_content = "Puede que no tenga una espada en la mano, pero cualquier cosa puede servir como arma para un verdadero espadachín.",
  ui_story_5089_50891101_133_dialog_content = "<color=#e8d9bb>Con un giro, ella se desvanece en la oscuridad de la noche. De repente—</color>",
  ui_story_5089_50891101_134_dialog_content = "<color=#e8d9bb>Los pétalos se dispersan.</color>",
  ui_story_5089_50891101_135_dialog_content = "¿Qué... qué es esto...?",
  ui_story_5089_50891101_136_dialog_content = "<color=#e8d9bb>Las hojas se reúnen.</color>",
  ui_story_5089_50891101_137_dialog_content = "¡Ey, qué te pasa? ¿Por qué estás tirado en el suelo así?! Levántate y—¡Uwaaaa!",
  ui_story_5089_50891101_138_dialog_content = "<color=#e8d9bb>El bambú barre.</color>",
  ui_story_5089_50891101_139_dialog_content = "¡Corre! ¡Corre por tu vida! ¡Aaaahhhh—",
  ui_story_5089_50891101_140_dialog_content = "<color=#e8d9bb>Las sombras parpadean.</color>",
  ui_story_5089_50891101_141_dialog_content = "¡Ahí estás! ¡Toma esto!",
  ui_story_5089_50891101_142_dialog_content = "¿U-Una capa? Pero dónde fue ella... Urgh...",
  ui_story_5089_50891101_143_dialog_content = "<color=#e8d9bb>En un instante, Jiu traza un sangriento camino a través de innumerables soldados.</color>",
  ui_story_5089_50891101_144_dialog_content = "Un demonio... ¡Tiene que ser algún tipo de demonio!",
  ui_story_5089_50891101_145_dialog_content = "No. Definitivamente soy una persona.",
  ui_story_5089_50891101_146_dialog_content = "Alguien que es muy diferente de los demonios o espíritus malignos.",
  ui_story_5089_50891101_147_dialog_content = "Me llevó mucho tiempo y esfuerzo finalmente darme cuenta de esto, así que ¿podrías por favor hacerte a un lado?",
  ui_story_5089_50891101_148_dialog_content = "Tengo que estar en otro lugar ahora mismo.",
  ui_story_5089_50891101_149_dialog_content = "... Consíguela.",
  ui_story_5089_50891101_150_dialog_content = "Hazlo a tu manera, entonces.",
  ui_story_5089_50891101_151_dialog_content = "<color=#e8d9bb>Jiu se agacha y recoge la lanza de un soldado caído. Con un movimiento rápido, rompe la hoja y la blandea como una espada.</color>",
  ui_story_5089_50891101_152_dialog_content = "Mover.",
  ui_story_5089_50891101_153_dialog_content = "Mi lugar—",
  ui_story_5089_50891101_154_dialog_content = "¡Está al lado de mi amo!",
  ui_story_5089_50891201_1_dialog_content = "¿Ya has localizado a Zhui Hu, PlayerName?",
  ui_story_5089_50891201_2_dialog_content = "¡Sí! ¡Ella está justo adelante!",
  ui_story_5089_50891201_3_dialog_content = "Hmph.",
  ui_story_5089_50891201_4_dialog_content = "Todas esas personas, y aún así, eran impotentes para detenerte.",
  ui_story_5089_50891201_5_dialog_content = "Parece que realmente no se comparan con las bestias de relojería después de todo.",
  ui_story_5089_50891201_6_dialog_content = "Si recuerdo correctamente, ¿no destruimos completamente tu preciado Stinger la última vez?",
  ui_story_5089_50891201_7_dialog_content = "Así es, y nuestros refuerzos estarán aquí en cualquier momento. Si yo fuera tú, me rendiría antes de que sea demasiado tarde.",
  ui_story_5089_50891201_8_dialog_content = "¿Refuerzos? Qué miedo.",
  ui_story_5089_50891201_9_dialog_content = "No importa cuántos refuerzos convoques, todos siguen siendo mortales como cualquier otro. ¿Estás seguro de que quieres que estén aquí cuando esta montaña se derrumbe?",
  ui_story_5089_50891201_10_dialog_content = "En lugar de perder tiempo con esta inútil demostración de bravuconería, deberías comenzar a evacuar a todos inmediatamente.",
  ui_story_5089_50891201_11_dialog_content = "Según mi estimación, una vez que esta montaña se derrumbe, toda la tierra de cultivo en esta área completa será completamente diezmada.",
  ui_story_5089_50891201_12_dialog_content = "Ahora veo por qué me asignaron una misión tan extraña.",
  ui_story_5089_50891201_13_dialog_content = "Este debe ser una de las regiones productoras de granos más importantes del Reino de Ye. Parece que la cosecha de este año será algo escasa.",
  ui_story_5089_50891201_14_dialog_content = "Se rumorea que el Reino de Ji también está interfiriendo con los suministros de alimentos del Reino de Ye. Si algo sale mal, una hambruna generalizada podría estar a la vuelta de la esquina.",
  ui_story_5089_50891201_15_dialog_content = "¿No eres tú también del Reino Ye? ¡¿Por qué harías tal cosa?!",
  ui_story_5089_50891201_16_dialog_content = "Pensé que me había explicado perfectamente la última vez: cualquiera dispuesto a apoyar mi oficio merece ser llamado mi maestro.",
  ui_story_5089_50891201_17_dialog_content = "No dejes que sus palabras te distraigan, PlayerName.",
  ui_story_5089_50891201_18_dialog_content = "Ella simplemente está ganando tiempo para... ¡Espera! ¿Dónde está tu Stinger, Zhui Hu?!",
  ui_story_5089_50891201_19_dialog_content = "Jejeje, me alegra que finalmente te hayas dado cuenta, pero ahora es demasiado tarde.",
  ui_story_5089_50891201_20_dialog_content = "¿Ves esa luz a lo lejos?",
  ui_story_5089_50891201_21_dialog_content = "¡Mi ataque Stinger está completamente cargado ahora, y con el poder de la Llama Zhuyin, esta montaña pronto no será más que un montón de escombros!",
  ui_story_5089_50891201_22_dialog_content = "¿Intentarás disfrutar del espectáculo, no es así?",
  ui_story_5089_50891201_23_dialog_content = "¡¿Te has vuelto loco?! ¡Si esa cosa destruye la montaña, morirás junto con el resto de nosotros!",
  ui_story_5089_50891201_24_dialog_content = "Descansa tranquilo, soy perfectamente capaz de mantenerme vivo.",
  ui_story_5089_50891201_25_dialog_content = "Más importante aún, como este es el primer ataque a gran escala de mi Stinger, es natural que observe sus efectos de primera mano.",
  ui_story_5089_50891201_26_dialog_content = "Agradezcan, ustedes dos. No todos tienen la oportunidad de presenciar un espectáculo tan maravilloso.",
  ui_story_5089_50891201_27_dialog_content = "... Ignórala por ahora, PlayerName! ¡Tenemos que detener al Stinger!",
  ui_story_5089_50891201_28_dialog_content = "No hay forma de detenerlo ahora.",
  ui_story_5089_50891201_29_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5089_50891201_30_dialog_content = "<color=#e8d9bb>Un cegador haz de luz rasga la colosal montaña, y innumerables piedras de todos los tamaños caen del cielo.</color>",
  ui_story_5089_50891201_31_dialog_content = "¡Soldados! ¡Escolten al Maestro Hou, quiero decir, escolten al rey a un lugar seguro! Una vez que esté fuera de peligro, busquen sobrevivientes entre los escombros y evacúenlos!",
  ui_story_5089_50891201_32_dialog_content = "Una princesa no debería abandonar a sus invitados tan despiadadamente, ya sabes.",
  ui_story_5089_50891201_33_dialog_content = "<color=#e8d9bb>Una bestia mecánica emerge de los escombros y se lanza directamente a Dantang!</color>",
  ui_story_5089_50891201_34_dialog_content = "¡Cuidado—!",
  ui_story_5089_50891201_35_dialog_content = "Lo siento, pero no puedo permitirte pasar. Es simplemente demasiado peligroso adelante.",
  ui_story_5089_50891201_36_dialog_content = "¡Argh, hemos estado discutiendo sobre esto durante horas, buen hombre! ¿Por qué no me crees?",
  ui_story_5089_50891201_37_dialog_content = "Mis adivinaciones claramente sugieren que un evento catastrófico ocurrirá pronto en alguna parte de esta dirección.",
  ui_story_5089_50891201_38_dialog_content = "Solo podemos contener las mareas del caos y prevenir este desastre inminente entregando rápidamente esta espada a su legítimo dueño.",
  ui_story_5089_50891201_39_dialog_content = "Estoy seguro de que nuestros soldados pueden manejar este supuesto desastre muy bien. De cualquier manera, tú aún no puedes pasar.",
  ui_story_5089_50891201_40_dialog_content = "Te lo ruego, amable señor, solo déjame—",
  ui_story_5089_50891201_41_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5089_50891201_42_dialog_content = "¡¿L-La montaña...?! ¡¿Pero cómo puede ser esto?!",
  ui_story_5089_50891201_43_dialog_content = "Te advertí, ¿no es así?",
  ui_story_5089_50891201_44_dialog_content = "¡No hay tiempo que perder! ¡Me despediré ahora!",
  ui_story_5089_50891201_45_dialog_content = "Espera, tú—",
  ui_story_5089_50891201_46_dialog_content = "<color=#e8d9bb>De repente, parece pasar un viento oscuro e inquietante.</color>",
  ui_story_5089_50891201_47_dialog_content = "¿Hmm? ¿Alguien pasó por aquí hace un momento?",
  ui_story_5089_50891201_48_dialog_content = "¡Begonias brillantes!",
  ui_story_5089_50891201_49_dialog_content = "¡Urgh!",
  ui_story_5089_50891201_50_dialog_content = "Parece que te has vuelto más fuerte desde nuestro último encuentro en el mar.",
  ui_story_5089_50891201_51_dialog_content = "A diferencia de ti, no todos nos aferramos a nuestras pertenencias y nos negamos a seguir adelante.",
  ui_story_5089_50891201_52_dialog_content = "Je, qué palabras tan mordaces.",
  ui_story_5089_50891201_53_dialog_content = "¡Salgan, todos ustedes!",
  ui_story_5089_50891201_54_dialog_content = "¡Tengo curiosidad por ver si puedes o no sobrevivir contra mis llamadas \"pertenencias\"!",
  ui_story_5089_50891201_55_dialog_content = "!",
  ui_story_5089_50891201_56_dialog_content = "(Dantang ya está en su límite. No podrá seguir a este ritmo.)",
  ui_story_5089_50891201_57_dialog_content = "(La montaña aún no se ha derrumbado, pero puede suceder en cualquier segundo... ¿Qué deberíamos hacer?)",
  ui_story_5089_50891201_58_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5089_50891201_59_dialog_content = "<color=#e8d9bb>Un rápido rayo corta a través de la densa noche.</color>",
  ui_story_5089_50891201_60_dialog_content = "Jiu!",
  ui_story_5089_50891201_61_dialog_content = "¡Eras muy lento!",
  ui_story_5089_50891201_62_dialog_content = "Por favor, sea razonable, Su Alteza. Vine aquí tan rápido como pude.",
  ui_story_5089_50891201_63_dialog_content = "Pero incluso así, todavía te debo una disculpa.",
  ui_story_5089_50891201_64_dialog_content = "Perdóname por llegar tan tarde.",
  ui_story_5089_50891201_65_dialog_content = "Disculpa aceptada.",
  ui_story_5089_50891201_66_dialog_content = "Hmph, otra molestia más.",
  ui_story_5089_50891201_67_dialog_content = "No importa. Dudo que incluso los tres de ustedes puedan resistir el asalto de un taller entero lleno de bestias de relojería!",
  ui_story_5089_50891201_68_dialog_content = "¡¡¡Rooooooooooooooooooooooooooooooooooooo!!!",
  ui_story_5089_50891201_69_dialog_content = "Puedo manejar esto solo.",
  ui_story_5089_50891201_70_dialog_content = "Si deseas acercarte a la Princesa Dantang y PlayerName, ¡primero tendrás que pasar por mí!",
  ui_story_5089_50891201_71_dialog_content = "(La batalla que se desarrolló ante nosotros solo podría describirse como \"deslumbrante\".)",
  ui_story_5089_50891201_72_dialog_content = "(A pesar de enfrentarse a un ejército de bestias de relojería y rocas que caen sin cesar, Jiu nunca se movió ni un centímetro.)",
  ui_story_5089_50891201_73_dialog_content = "(Armas, ramas, hojas, piedras e incluso los restos de bestias de relojería derribadas...)",
  ui_story_5089_50891201_74_dialog_content = "(Cualquier objeto a la vista de Jiu tenía el potencial de convertirse en un arma poderosa. Era imparable siempre que tuviera algo en sus manos.)",
  ui_story_5089_50891201_75_dialog_content = "Tan rápido como el legendario arquero que derribó los Nueve Soles, y tan majestuoso como los emperadores en lo alto de sus dragones voladores.",
  ui_story_5089_50891201_76_dialog_content = "Descendiendo sobre el campo de batalla como una tormenta en formación, ella parte un mar de soldados como un brillante rayo de relámpago.",
  ui_story_5089_50891201_77_dialog_content = "¿Finalmente has descubierto tu verdadera espada, Jiu?",
  ui_story_5089_50891201_78_dialog_content = "Crujir—",
  ui_story_5089_50891201_79_dialog_content = "No... ¡Esto no puede ser! ¿Cómo puede un simple mortal comandar tal poder?!",
  ui_story_5089_50891201_80_dialog_content = "¡Aún no he terminado—!",
  ui_story_5089_50891201_81_dialog_content = "<color=#e8d9bb>Pero Jiu aparece instantáneamente detrás de ella antes de que pueda invocar más bestias de relojería.</color>",
  ui_story_5089_50891201_82_dialog_content = "No te muevas.",
  ui_story_5089_50891201_83_dialog_content = "!",
  ui_story_5089_50891201_84_dialog_content = "Mmm, ¿crees que esto se acabó solo porque me has capturado?",
  ui_story_5089_50891201_85_dialog_content = "Mientras los Fate Riders logren recuperar mi aguijón todopoderoso, ¡continuará causando estragos en el campo de batalla!",
  ui_story_5089_50891201_86_dialog_content = "¡Y además, incluso con tu fuerza sobrenatural, nunca podrías esperar prevenir que esta montaña se derrumbe!",
  ui_story_5089_50891201_87_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5089_50891201_88_dialog_content = "<color=#e8d9bb>Bajo una enorme presión, las capas de roca debajo de la montaña comienzan a emitir sonidos ominosos. De repente, enormes rocas comienzan a desprenderse y a caer al suelo.</color>",
  ui_story_5089_50891201_89_dialog_content = "Dantang! Jiu! ¡No es seguro aquí! ¡Tenemos que irnos ahora mismo!",
  ui_story_5089_50891201_90_dialog_content = "Eso parece ser nuestra única opción. A estas alturas, los guardias reales deberían haber evacuado a los civiles.",
  ui_story_5089_50891201_91_dialog_content = "Discutiremos las cosas una vez que lleguemos a un lugar seguro.",
  ui_story_5089_50891201_92_dialog_content = "... ¿Jiu? ¿Por qué no te estás retirando?",
  ui_story_5089_50891201_93_dialog_content = "Puedo detenerlo.",
  ui_story_5089_50891201_94_dialog_content = "¿Qué?",
  ui_story_5089_50891201_95_dialog_content = "Mi maestro una vez dijo que la técnica de Thundering Edge es capaz de dividir montañas y separar mares.",
  ui_story_5089_50891201_96_dialog_content = "Pero pensé que dijiste que tu maestro nunca te enseñó ese movimiento?",
  ui_story_5089_50891201_97_dialog_content = "Afirmó que no tenía forma de enseñármelo, sí. Al principio, pensé que simplemente estaba poniendo excusas.",
  ui_story_5089_50891201_98_dialog_content = "Pero ahora estoy empezando a ver que él tenía razón todo el tiempo.",
  ui_story_5089_50891201_99_dialog_content = "El Filo Atronador no puede ser enseñado porque no es una técnica de espada real en absoluto.",
  ui_story_5089_50891201_100_dialog_content = "Más bien, es el corazón de la espada de uno.",
  ui_story_5089_50891201_101_dialog_content = "Incluso si ese es el caso, no tienes una espada ahora mismo—",
  ui_story_5089_50891201_102_dialog_content = "¡Amigos! ¡Realmente necesito ayuda ahora mismo!",
  ui_story_5089_50891201_103_dialog_content = "Ay querido, madre mía, ¿cómo se supone que debo esquivar todas estas rocas—",
  ui_story_5089_50891201_104_dialog_content = "¡Tianxian! ¡Este no es el momento para jugar juegos!",
  ui_story_5089_50891201_105_dialog_content = "Estoy en medio de serias adivinaciones ahora mismo—¡Ah! Supongo que no vamos por ese camino.",
  ui_story_5089_50891201_106_dialog_content = "¡Señorita Jiu, tengo tu espada justo aquí! ¡Atrápala!",
  ui_story_5089_50891201_107_dialog_content = "¡No en mi reloj!",
  ui_story_5089_50891201_108_dialog_content = "!",
  ui_story_5089_50891201_109_dialog_content = "<color=#e8d9bb>Mientras la espada de Jiu vuela por el aire, varios cangrejos de fuego se lanzan inmediatamente sobre Dantang.</color>",
  ui_story_5089_50891201_110_dialog_content = "<color=#e8d9bb>Jiu tropieza y su espada cae en las garras de un cangrejo de fuego. En el siguiente momento, se dirige hacia un área de escombros extremadamente densa.</color>",
  ui_story_5089_50891201_111_dialog_content = "<color=#e8d9bb>Casi al instante, el cangrejo de fuego es aplastado bajo las rocas que caen, atrapando la espada de Jiu junto con él.</color>",
  ui_story_5089_50891201_112_dialog_content = "... ¡Iré a buscarlo!",
  ui_story_5089_50891201_113_dialog_content = "¡PlayerName! / ¡PlayerName!",
  ui_story_5089_50891201_114_dialog_content = "¡Potencia de fuerza!",
  ui_story_5089_50891201_115_dialog_content = "(¡Mientras pueda predecir con precisión dónde caerán las piedras, puedo lograrlo!)",
  ui_story_5089_50891201_116_dialog_content = "¡Entendido!",
  ui_story_5089_50891201_117_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5089_50891201_118_dialog_content = "<color=#e8d9bb>La tierra tiembla violentamente mientras la montaña, que ha estado tambaleándose durante mucho tiempo, finalmente se derrumba por completo!</color>",
  ui_story_5089_50891201_119_dialog_content = "(¡No es bueno, no puedo esquivar tantas rocas a la vez—!)",
  ui_story_5089_50891201_120_dialog_content = "<color=#e8d9bb>Un destello de luz dorada.</color>",
  ui_story_5089_50891201_121_dialog_content = "Las rocas... ¿Están todas siendo desviadas?",
  ui_story_5089_50891201_122_dialog_content = "<color=#e8d9bb>Una barrera dorada y familiar en forma de loto cuelga en el cielo, bloqueando la cascada de rocas que caen.</color>",
  ui_story_5089_50891201_123_dialog_content = "¿Eh? Algo se siente cálido en mi bolsillo... Espera... ¿No es esta la hoja que Chen'ni me dio?",
  ui_story_5089_50891201_124_dialog_content = "<color=#e8d9bb>Esta no era una hoja ordinaria...</color>",
  ui_story_5089_50891201_125_dialog_content = "<color=#e8d9bb>Pero una escama de dragón iridiscente.</color>",
  ui_story_5089_50891201_126_dialog_content = "... Gracias, Chen'ni.",
  ui_story_5089_50891201_127_dialog_content = "¡Me aseguraré de comprarte muchos bocadillos la próxima vez que nos encontremos!",
  ui_story_5089_50891201_128_dialog_content = "¡Aviso, Jiu—!",
  ui_story_5089_50891201_129_dialog_content = "Gracias.",
  ui_story_5089_50891201_130_dialog_content = "<color=#e8d9bb>La montaña continúa su descenso cataclísmico, como si amenazara con destrozar todo el planeta bajo su inmenso peso.</color>",
  ui_story_5089_50891201_131_dialog_content = "<color=#e8d9bb>De pie en medio de la tierra retumbante y los escombros cayendo, Jiu cierra los ojos y bloquea el mundo a su alrededor.</color>",
  ui_story_5089_50891201_132_dialog_content = "Maestro, parece que finalmente entiendo el significado de una espada.",
  ui_story_5089_50891201_133_dialog_content = "\"El universo sigue cincuenta leyes, pero el Cielo guarda cuarenta y nueve secretos, dejando un solo camino para la humanidad.\"",
  ui_story_5089_50891201_134_dialog_content = "Incluso los cielos caprichosos nos dejan un camino, ¿entonces por qué insistes en restringirte de esta manera?",
  ui_story_5089_50891201_135_dialog_content = "No importa. Si realmente necesitas un límite de tiempo, entonces...",
  ui_story_5089_50891201_136_dialog_content = "Tus órdenes no terminarán hasta el día en que puedas blandir tu espada sin hacerlo por gratitud o venganza. ¿Qué te parece eso?",
  ui_story_5089_50891201_137_dialog_content = "Tengo una pregunta para ti, señorita Jiu.",
  ui_story_5089_50891201_139_dialog_content = "Por favor, perdóname, Lady Xuan Ji. Fui demasiado tonto para entender tu pregunta en ese momento.",
  ui_story_5089_50891201_140_dialog_content = "Pero afortunadamente, tengo a muchas personas maravillosas a mi lado que me guiarán cuando esté perdido.",
  ui_story_5089_50891201_141_dialog_content = "Así que ahora, permíteme darte mi respuesta.",
  ui_story_5089_50891201_142_dialog_content = "La mayor diferencia entre nosotros y los Eclipsites es que nuestros instintos u órdenes no nos controlan completamente.",
  ui_story_5089_50891201_143_dialog_content = "Si ese fuera el caso, estaríamos carentes de significado sin ellos.",
  ui_story_5089_50891201_144_dialog_content = "Incluso si nos perdemos, caemos en la oscuridad o nos encerramos en una jaula de necedad, siempre podemos encontrar personas de bondad y calidez sin límites.",
  ui_story_5089_50891201_145_dialog_content = "Almas gentiles que nos guiarán fuera de las sombras opresivas—",
  ui_story_5089_50891201_146_dialog_content = "¡Y hacia el cálido resplandor del sol!",
  ui_story_5089_50891201_147_dialog_content = "<color=#e8d9bb>Jiu de repente abre sus ojos y blande su espada con una velocidad casi imperceptible.</color>",
  ui_story_5089_50891201_148_dialog_content = "<color=#e8d9bb>La montaña se desintegra inmediatamente después mientras el cielo y la tierra resuenan al unísono.</color>",
  ui_story_5089_50891201_149_dialog_content = "<color=#e8d9bb>Una espada que encarna la ferocidad máxima, pero lleva una ligereza extrema.</color>",
  ui_story_5089_50891201_150_dialog_content = "Ya no empuño mi espada por gratitud o venganza.",
  ui_story_5089_50891201_151_dialog_content = "<color=#e8d9bb>Más bien, lo maneja como un regalo para los muchos amigos que le han mostrado bondad.</color>",
  ui_story_5089_50891201_152_dialog_content = "<color=#e8d9bb>La onda de choque de su ataque final barre desde la piedrita más pequeña hasta la montaña más alta, aplastando todo lo que toca hasta convertirlo en polvo.</color>",
  ui_story_5089_50891201_153_dialog_content = "Increíble...",
  ui_story_5089_50891201_154_dialog_content = "<color=#e8d9bb>Al mirar de nuevo, la inmensa montaña que hace un momento se estaba derrumbando se ha convertido en una nube de polvo.</color>",
  ui_story_5089_50891201_155_dialog_content = "<color=#e8d9bb>La hoja de escarcha divide el aire, dejando truenos a su paso.</color>",
  ui_story_5089_50891201_156_dialog_content = "<color=#e8d9bb>Resonando a través de las cimas de montañas distantes.</color>",
  ui_story_5089_50891201_157_dialog_content = "Hermana Xuan Ji... Ese ataque de hace un momento no volverá a suceder, ¿verdad?",
  ui_story_5089_50891201_158_dialog_content = "Probablemente no.",
  ui_story_5089_50891201_159_dialog_content = "Aun así, nunca esperé que su espada poseyera un poder tan formidable.",
  ui_story_5089_50891201_160_dialog_content = "Incluso desde esta distancia, el Stinger fue completamente partido por la mitad... ¿Hmm?",
  ui_story_5089_50891201_161_dialog_content = "Hermana... ¿Es esa la Llama Zhuyin?!",
  ui_story_5089_50891201_162_dialog_content = "Como siempre digo, un artesano debe ser meticuloso en todo lo que hace.",
  ui_story_5089_50891201_163_dialog_content = "Aunque debo decir, esta es la primera vez que veo a alguien cortar una llama por la mitad.",
  ui_story_5089_50891201_164_dialog_content = "¡Este no es el momento para bromear, Hermana Xuan Ji!",
  ui_story_5089_50891201_165_dialog_content = "La Llama Zhuyin es el artefacto más preciado de nuestra secta, ¡pero míralo ahora! ¡Ha sido cortado por la mitad!",
  ui_story_5089_50891201_166_dialog_content = "Sí, y dos mitades perfectamente simétricas, nada menos.",
  ui_story_5089_50891201_167_dialog_content = "La señorita Jiu realmente nos ha hecho un gran favor.",
  ui_story_5089_50891201_168_dialog_content = "¿¡De qué diablos estás hablando?! ¿Cómo se supone que vamos a explicar esto al gremio?!",
  ui_story_5089_50891201_169_dialog_content = "No te preocupes, me encargaré de todo.",
  ui_story_5089_50891201_170_dialog_content = "Ahora ve e informa a los demás abajo. La bestia mecánica de aquí ha sido tratada, así que haz que ellos ayuden con el resto de los esfuerzos.",
  ui_story_5089_50891201_171_dialog_content = "Después de todo, deberíamos ser nosotros los responsables de limpiar después de nuestros propios traidores.",
  ui_story_5089_50891201_172_dialog_content = "Entendido.",
  ui_story_5089_50891201_173_dialog_content = "Ngh.",
  ui_story_5089_50891201_174_dialog_content = "¿Estás bien, Jiu?",
  ui_story_5089_50891201_175_dialog_content = "Estoy bien, solo me siento un poco agotado...",
  ui_story_5089_50891201_176_dialog_content = "Espera un minuto... ¡Estás completamente cubierto de sangre! ¿Has estado luchando en esta condición todo el tiempo?!",
  ui_story_5089_50891201_177_dialog_content = "¡Rápido, llama a un médico!",
  ui_story_5089_50891201_178_dialog_content = "Aprecio tu preocupación, PlayerName, pero aún tengo algo que debo hacer.",
  ui_story_5089_50891201_179_dialog_content = "¿Qué podrías tener que hacer después de todo esto?!",
  ui_story_5089_50891201_180_dialog_content = "¡No te quedes ahí parado, Dantang! ¡Dile algo a ella!",
  ui_story_5089_50891201_181_dialog_content = "Déjala en paz, PlayerName.",
  ui_story_5089_50891201_182_dialog_content = "Es hora de que ella deje todo en paz de una vez por todas.",
  ui_story_5089_50891201_183_dialog_content = "Pero, ¿qué podría ser ella... Ah, ya veo!",
  ui_story_5089_50891201_184_dialog_content = "Tienes razón, es hora de terminar con esto.",
  ui_story_5089_50891201_185_dialog_content = "Así que has venido.",
  ui_story_5089_50891201_186_dialog_content = "Es correcto.",
  ui_story_5089_50891201_187_dialog_content = "Guardias, tráeme una espada.",
  ui_story_5089_50891201_188_dialog_content = "¡Pero Su Alteza, todavía está gravemente herido! ¡No deberías moverte en este momento!",
  ui_story_5089_50891201_189_dialog_content = "Dije tráeme una espada.",
  ui_story_5089_50891201_190_dialog_content = "Al menos, le debo esto a ella.",
  ui_story_5089_50891201_191_dialog_content = "<color=#e8d9bb>Jiu saca su máscara y se la pone una vez más.</color>",
  ui_story_5089_50891201_192_dialog_content = "Arreglemos esto.",
  ui_story_5089_50891202_1_dialog_content = "<color=#e8d9bb>Sonido metálico-</color>",
  ui_story_5089_50891202_2_dialog_content = "<color=#e8d9bb>En un campo vacío, las dos figuras chocan. Después de un breve intercambio, la espada del falso rey es golpeada de sus manos y lanzada al aire.</color>",
  ui_story_5089_50891202_3_dialog_content = "Tos... Tos, tos...",
  ui_story_5089_50891202_4_dialog_content = "¡Por favor, Su Alteza! ¡Basta de esta pelea!",
  ui_story_5089_50891202_5_dialog_content = "El resultado es claro.",
  ui_story_5089_50891202_6_dialog_content = "Me has superado.",
  ui_story_5089_50891202_7_dialog_content = "...",
  ui_story_5089_50891202_8_dialog_content = "<color=#e8d9bb>Grieta.</color>",
  ui_story_5089_50891202_9_dialog_content = "<color=#e8d9bb>La máscara de Jiu es cortada en dos por el ataque del falso rey, y cae al suelo.</color>",
  ui_story_5089_50891202_10_dialog_content = "Con esto, nuestros rencores están ahora resueltos.",
  ui_story_5089_50891202_11_dialog_content = "De acuerdo.",
  ui_story_5089_50891202_12_dialog_content = "Ahora ve.",
  ui_story_5089_50891202_13_dialog_content = "<color=#e8d9bb>Jiu envaina su espada, hace una leve reverencia a Dantang en la distancia, luego se da la vuelta y se va.</color>",
  ui_story_5089_50891202_14_dialog_content = "<color=#e8d9bb>No mira atrás ni una sola vez.</color>",
  ui_story_5089_50891300_1_dialog_content = "<color=#e8d9bb>Palacio Real del Reino Ji</color>",
  ui_story_5089_50891300_2_dialog_content = "¡Padre! ¡Padre! ¡Oigo que mi prometido me ha enviado regalos!",
  ui_story_5089_50891300_3_dialog_content = "De hecho, hijo mío.",
  ui_story_5089_50891300_4_dialog_content = "¡Déjame ver! ¡Déjame ver!",
  ui_story_5089_50891300_5_dialog_content = "Aquí, una fortuna en oro.",
  ui_story_5089_50891300_6_dialog_content = "¿Eh? ¿Pero no son estos los regalos que le ofrecí antes de que se fuera?",
  ui_story_5089_50891300_7_dialog_content = "¿No le gusta el oro? Debería haber sabido que mi amado héroe no se preocuparía por baratijas insignificantes como estas.",
  ui_story_5089_50891300_8_dialog_content = "¡Tendré que pensar más en mis regalos de ahora en adelante!",
  ui_story_5089_50891300_9_dialog_content = "Ese chico...",
  ui_story_5089_50891300_10_dialog_content = "Ese hombre joven utilizó el regalo de oro del príncipe heredero para intercambiar por la comida que previamente compramos del Reino Ye. Sus intenciones parecen ser bastante claras.",
  ui_story_5089_50891300_11_dialog_content = "¿Cómo debemos proceder, Su Alteza?",
  ui_story_5089_50891300_12_dialog_content = "PlayerName es un amigo del Reino Ji, alguien por cuyo honor puedo responder personalmente. Todavía tengo que recompensarlo por salvar a Haojin, también.",
  ui_story_5089_50891300_13_dialog_content = "Si desea involucrarse en estos asuntos, respetaré su decisión.",
  ui_story_5089_50891300_14_dialog_content = "Sin embargo, no seré tan generoso si Ye Kingdom busca conflicto con nosotros de nuevo en el futuro.",
  ui_story_5089_50891300_15_dialog_content = "Si mi señor.",
  ui_story_5089_50891300_16_dialog_content = "<color=#e8d9bb>Fwoosh</color>",
  ui_story_5089_50891300_17_dialog_content = "<color=#e8d9bb>En el bullicioso muelle, otro gran barco iza sus velas y parte.</color>",
  ui_story_5089_50891300_18_dialog_content = "Entonces, ¿Jiu nunca vuelve después de eso?",
  ui_story_5089_50891300_19_dialog_content = "Sí. Dado que voluntariamente le concedí libertad, es natural que respete su elección.",
  ui_story_5089_50891300_20_dialog_content = "Incluso si ella nunca regresa, siempre recordaré lo afortunado que fui de tener una amiga tan cercana.",
  ui_story_5089_50891300_21_dialog_content = "Pero y tú, PlayerName? ¿Qué harás a continuación?",
  ui_story_5089_50891300_22_dialog_content = "¿Eh? Estamos en un barco rumbo al Reino de Ji ahora mismo, ¿no es así?",
  ui_story_5089_50891300_23_dialog_content = "Eres el que dijo que los Fate Riders son nuestro enemigo común. Nuestro próximo objetivo es convencer a los Reinos de Ji y Ye para que dejen de lado sus diferencias por el momento.",
  ui_story_5089_50891300_24_dialog_content = "También necesito devolver todo este oro al príncipe heredero. Nunca tuve la oportunidad de agradecer a Houfeng... quiero decir, al Rey de Ye... Por ayudarme a cubrir la diferencia.",
  ui_story_5089_50891300_25_dialog_content = "Hablando de eso, ¿estás seguro de que está bien dejarlo seguir sirviendo como rey?",
  ui_story_5089_50891300_26_dialog_content = "Desafortunadamente, no tenemos otra opción.",
  ui_story_5089_50891300_27_dialog_content = "Mi verdadero tío está mentalmente incapacitado para gobernar, y mi hermana mayor aún es demasiado joven para asumir las responsabilidades del trono. Tal como están las cosas, el Reino Ye no puede permitirse ni la más mínima perturbación.",
  ui_story_5089_50891300_28_dialog_content = "Aunque el Maestro Houfeng es algo arrogante, realmente tiene los mejores intereses del Reino Ye en su corazón.",
  ui_story_5089_50891300_29_dialog_content = "Además, con la Ministra Armilla y el Gremio de Artesanos ejerciendo mayor autoridad que antes, no podrá actuar con impunidad por el momento.",
  ui_story_5089_50891300_30_dialog_content = "Pero ese no era el punto de mi pregunta. Me refería más a tus planes futuros.",
  ui_story_5089_50891300_31_dialog_content = "Bueno, ahora que he estado en Haojin y la Ciudad de Jingliang, quiero ver más de Longzhou.",
  ui_story_5089_50891300_32_dialog_content = "Pero después de estar lejos de Astra durante tanto tiempo, ¿quizás debería hacer un viaje de regreso primero? Preferiría no hacer que Vice y Carleen se preocupen más de lo necesario.",
  ui_story_5089_50891300_33_dialog_content = "¿Qué opinas, Dantang?",
  ui_story_5089_50891300_34_dialog_content = "¿Seguro que bromeas?",
  ui_story_5089_50891300_35_dialog_content = "No eres ni un pájaro en una jaula ni una bestia en un corral. No es mi lugar dictar tu futuro.",
  ui_story_5089_50891300_36_dialog_content = "Entonces, si no soy uno u otro, ¿qué soy exactamente en tus ojos, Dantang?",
  ui_story_5089_50891300_37_dialog_content = "Si tuviera que decir...",
  ui_story_5089_50891300_38_dialog_content = "<color=#e8d9bb>Bajo el sol de la mañana, ella ríe mientras mira hacia arriba, sus ojos serios rebosan de una luz radiante.</color>",
  ui_story_5089_50891300_39_dialog_content = "Eres el Peng a mi Kun.",
  ui_story_5089_50891300_40_dialog_content = "Un gran y majestuoso pájaro que eventualmente volará a través de los nueve cielos.",
  ui_story_5089_50891300_41_dialog_content = "Eso es un poco demasiado, ¿no crees?",
  ui_story_5089_50891300_42_dialog_content = "Para nada.",
  ui_story_5089_50891300_43_dialog_content = "¡Oye, cuidado allí! ¡Alguien está persiguiendo nuestro barco!",
  ui_story_5089_50891300_44_dialog_content = "¿Has estado mucho tiempo bajo el sol? ¿Cómo podría alguien posiblemente... Espera, ¡tienes razón! La Doncella Dragón está arriba; ¡realmente hay alguien corriendo sobre el agua!",
  ui_story_5089_50891300_45_dialog_content = "¿De qué están gritando ustedes dos—¡Guau!",
  ui_story_5089_50891300_46_dialog_content = "¿Ese es Jiu?!",
  ui_story_5089_50891300_47_dialog_content = "<color=#e8d9bb>El barco ha navegado lejos de la costa, sin embargo, una figura camina sobre el agua, corriendo hacia él a una velocidad increíble.</color>",
  ui_story_5089_50891300_48_dialog_content = "<color=#e8d9bb>Mientras se acerca al barco, hace un salto audaz y aterriza con gracia en la cubierta.</color>",
  ui_story_5089_50891300_49_dialog_content = "<color=#e8d9bb>De pie ante nosotros, fresca como la brisa del océano, no es otra que Jiu misma.</color>",
  ui_story_5089_50891300_50_dialog_content = "Su Alteza, ¿no cree que fue imprudente de su parte partir hacia otro reino sin su leal guardia?",
  ui_story_5089_50891300_51_dialog_content = "¿Entonces has decidido?",
  ui_story_5089_50891300_52_dialog_content = "Si has elegido seguirme, que se sepa que no toleraré el mismo error dos veces, Jiu.",
  ui_story_5089_50891300_53_dialog_content = "Mi mente está decidida, Su Alteza.",
  ui_story_5089_50891300_54_dialog_content = "En mi honor, no te defraudaré.",
  ui_story_5089_50891300_55_dialog_content = "Bueno. Ahora vámonos.",
  ui_story_5089_50891300_56_dialog_content = "Los Fate Riders aún son una amenaza para todo el Imperio Zhao. Una vez que concluyamos nuestros asuntos en el Reino Ji, viajaremos a los otros reinos vasallos para continuar nuestra investigación.",
  ui_story_5089_50891300_57_dialog_content = "Pero con el imperio en tal peligro, ¿no sería mejor enviar a otros a los reinos vasallos en tu lugar?",
  ui_story_5089_50891300_58_dialog_content = "Viajar a través de la tierra en todas las direcciones concebibles es una oportunidad que se les brinda a muy pocas personas.",
  ui_story_5089_50891300_59_dialog_content = "Siempre he aspirado a viajar así. ¿Cómo podría dejar que una pequeña crisis me impida alcanzar mi sueño de toda la vida?",
  ui_story_5089_50891300_60_dialog_content = "Además, las aves y los peces son libres de recorrer el mundo.",
  ui_story_5089_50891300_61_dialog_content = "Si no me atrevo a explorar cada rincón del mundo, ¿cómo puedo esperar encontrar alguna vez un compañero tan extraordinario como ellos para volar a mi lado?",
  ui_story_5089_50891300_62_dialog_content = "Todavía tenemos un largo viaje por delante.",
  ui_story_5089_50891300_63_dialog_content = "<color=#e8d9bb>En una casa de té en algún lugar</color>",
  ui_story_5089_50891300_64_dialog_content = "... Y así, la Princesa Zhuohua y el Enviado de Astra partieron en sus respectivos viajes.",
  ui_story_5089_50891300_65_dialog_content = "Los vientos cambiantes y las nubes rodantes sobre ellos finalmente habían disminuido, al menos por el momento.",
  ui_story_5089_50891300_66_dialog_content = "En cuanto a mí, esta es la oportunidad perfecta para pedir unas cuantas monedas de repuesto a cambio de mi maravilloso cuento. Después de todo, ¡mis pobres pajaritos también tienen que comer!",
  ui_story_5089_50891300_67_dialog_content = "¿Qué es eso? ¿Crees que estoy inventando todo? ¡Vaya, qué grave malentendido!",
  ui_story_5089_50891300_68_dialog_content = "¡Cada palabra de lo que acabo de decir es cierta, y este océano es prueba de ello!",
  ui_story_5089_50891300_69_dialog_content = "Grabado sobre las olas del océano, un barco lleno de begonias brillantes navega hacia adelante.",
  ui_story_5089_50891300_70_dialog_content = "En la víspera del Festival de Primavera, se lleva a cabo una danza entre peces y dragones, y el poder de la tormenta calma el mar.",
  ui_story_5089_50891300_71_dialog_content = "Una espada atronadora se convierte en una cuchilla de pura escarcha, y golpea a los demonios hasta convertirlos en polvo.",
  ui_story_5089_50891300_72_dialog_content = "El pájaro enjaulado se libera, agitando los cielos con sus alas mientras encuentra alegría en la vastedad del mundo.",
  ui_story_5089_50891300_73_dialog_content = "Así, el Cuento de la Begonia a la Deriva llega a su fin.",
  ui_story_5089_50891300_74_dialog_content = "Naturalmente, el viaje del héroe está lejos de terminar. Si te gustaría escuchar el resto de él—",
  ui_story_5089_50891300_75_dialog_content = "<color=#e8d9bb>¡Clac!</color>",
  ui_story_5089_50891300_76_dialog_content = "<color=#e8d9bb>Con un clic del mazo de madera, el libro que se había volteado hasta el final se cierra lentamente, la luz de la vela se desvanece y cae el telón.</color>",
  ui_story_5089_50891300_77_dialog_content = "¿Qué sigue... Bueno, tal vez estemos en extremos opuestos del mar, nos volveremos a encontrar siempre y cuando el destino lo permita.",
  ui_story_5089_50891400_1_dialog_content = "¿Has tomado tu decisión?",
  ui_story_5089_50891400_2_dialog_content = "Avanzar significa despedirse de todos los que conoces ahora.",
  ui_story_5089_50891400_3_dialog_content = "Todas las conexiones que has trabajado tanto para construir se desvanecerán.",
  ui_story_5089_50891400_4_dialog_content = "Pero incluso así, todavía viajarías hasta los confines del mundo por ella, ¿no es así?",
  ui_story_5089_50891400_5_option_content = "Sí.",
  ui_story_5089_50891400_6_option_content = "Sí, he decidido.",
  ui_story_5089_50891400_7_dialog_content = "...",
  ui_story_5089_50891400_8_dialog_content = "Tus viajes en Longzhou parecen haberte hecho más decidido.",
  ui_story_5089_50891400_9_dialog_content = "Entonces, digamos nuestros adiós.",
  ui_story_5089_50891400_10_dialog_content = "Al final de lo último, con todos mis amigos...",
  ui_story_5089_50891400_11_dialog_content = "¿Un último viaje alrededor de Astra, verdad?",
  ui_story_5089_50891400_12_dialog_content = "¡Justo como al principio, saldremos con estilo!",
  ui_story_5089_50891400_13_dialog_content = "¿Viniste todo este camino solo para decir adiós?",
  ui_story_5089_50891400_14_dialog_content = "Oh, soy bueno en esto, ya sabes. Pero vas a volver algún día, ¿verdad?",
  ui_story_5089_50891400_15_option_content = "Yo tampoco estoy seguro.",
  ui_story_5089_50891400_16_option_content = "Mmm...",
  ui_story_5089_50891400_17_dialog_content = "Suspiro, ven aquí.",
  ui_story_5089_50891400_18_dialog_content = "Aquí. Cuando los chicos se abrazan así, no tienen que decir nada más.",
  ui_story_5089_50891400_19_dialog_content = "Sé que tienes tus razones, y te apoyo.",
  ui_story_5089_50891400_20_dialog_content = "Y... Gracias. Siempre has sido de gran ayuda para nosotros, y para mí.",
  ui_story_5089_50891400_21_dialog_content = "Si alguna vez vuelves, recuerda avisarnos.",
  ui_story_5089_50891400_22_dialog_content = "Y si las cosas no salen bien, no olvides que siempre tendrás un lugar aquí.",
  ui_story_5089_50891400_23_dialog_content = "Gracias, definitivamente lo recordaré.",
  ui_story_5089_50891400_24_dialog_content = "Argh, aquí voy, poniéndome todo lloroso... Esto es tu culpa.",
  ui_story_5089_50891400_25_dialog_content = "Ahora ve a despedirte de Eve y los demás.",
  ui_story_5089_50891400_26_dialog_content = "Adiós, Sinsa.",
  ui_story_5089_50891400_27_dialog_content = "... Adiós, PlayerName.",
  ui_story_5089_50891400_28_dialog_content = "¿Qué? ¿Así como así... y te vas y nunca vuelves?!",
  ui_story_5089_50891400_29_dialog_content = "Ah, eso no es necesariamente el caso, pero no estoy del todo seguro de cuándo volveré...",
  ui_story_5089_50891400_30_dialog_content = "O-Oh, Eve, no llores. Si Sinsa ve esto, ¡estaré en grandes problemas!",
  ui_story_5089_50891400_31_dialog_content = "Pero...",
  ui_story_5089_50891400_32_dialog_content = "¡Sé que nos volveremos a encontrar algún día!",
  ui_story_5089_50891400_33_dialog_content = "Y cuando finalmente encuentre mi camino de regreso aquí...",
  ui_story_5089_50891400_34_dialog_content = "¡Tendré montones de nuevas historias para compartir contigo, historias que nunca podrías ver aquí en Astra!",
  ui_story_5089_50891400_35_dialog_content = "¿Lo prometes?",
  ui_story_5089_50891400_36_dialog_content = "¡Claro!",
  ui_story_5089_50891400_37_dialog_content = "¿Promesa de meñique?",
  ui_story_5089_50891400_38_dialog_content = "¡Absolutamente!",
  ui_story_5089_50891400_39_dialog_content = "¡Bien! Vamos, te llevaré a los demás para que puedas despedirte de ellos.",
  ui_story_5089_50891400_40_dialog_content = "Te extrañamos todo el tiempo, ¿sabes?",
  ui_story_5089_50891400_41_dialog_content = "¡Oh, y recuerdas a esa dama que nos presentaste antes? ¡Todavía no la has visto por aquí!",
  ui_story_5089_50891400_42_dialog_content = "¡Y también está la señorita Attar! Ella...",
  ui_story_5089_50891400_43_dialog_content = "¿Eve?",
  ui_story_5089_50891400_44_dialog_content = "Lo siento. Sé que prometí que no lloraría más.",
  ui_story_5089_50891400_45_dialog_content = "Pero... De repente recordé todo lo que hemos pasado juntos...",
  ui_story_5089_50891400_46_dialog_content = "Sé lo que quieres decir. Ha pasado un tiempo, ¿eh?",
  ui_story_5089_50891400_47_dialog_content = "Antes de que nos diéramos cuenta, hicimos muchos nuevos amigos. Todos ellos también han crecido de muchas maneras.",
  ui_story_5089_50891400_48_dialog_content = "Este lugar siempre estará cerca y será querido para mi corazón.",
  ui_story_5089_50891400_49_dialog_content = "Justo como la olla caliente en Longzhou.",
  ui_story_5089_50891400_50_dialog_content = "Por eso creo que estarás bien, Eve.",
  ui_story_5089_50891400_51_dialog_content = "Porque todavía tendrás a todos a tu lado.",
  ui_story_5089_50891400_52_dialog_content = "A-Bien.",
  ui_story_5089_50891400_54_dialog_content = "Vamos, vamos a decir adiós.",
  ui_story_5089_50891400_55_dialog_content = "Me han contado sobre el asunto.",
  ui_story_5089_50891400_56_dialog_content = "Dado que implica a Vice, no te detendré.",
  ui_story_5089_50891400_57_dialog_content = "También he aprobado la solicitud de Vice de tiempo libre. Si necesitas algo más, no dudes en decírmelo.",
  ui_story_5089_50891400_58_dialog_content = "Está bien, esto es más que suficiente. ¡Gracias a ti y a Reinhardt por toda su ayuda!",
  ui_story_5089_50891400_59_dialog_content = "Nuestro viaje nos llevará profundamente a un territorio desconocido.",
  ui_story_5089_50891400_60_dialog_content = "No es algo que se pueda resolver simplemente encontrando más personas.",
  ui_story_5089_50891400_61_dialog_content = "Entiendo, pero aún me gustaría echar una mano si es posible.",
  ui_story_5089_50891400_62_dialog_content = "Las cosas serán un poco solitarias sin ti, estoy seguro.",
  ui_story_5089_50891400_63_dialog_content = "Sé que Barton lo sentirá cuando esté en casa sin hacer nada.",
  ui_story_5089_50891400_64_dialog_content = "¿Por qué no dejar que Gronru lo saque a jugar más? No es saludable para él quedarse en casa cuando no hay batallas que luchar.",
  ui_story_5089_50891400_65_dialog_content = "Je, solo estoy bromeando.",
  ui_story_5089_50891400_66_dialog_content = "Su antiguo comandante lo está observando de cerca ahora, así que tendrá mucho que hacer.",
  ui_story_5089_50891400_67_dialog_content = "Comandante Hiiro contando chistes... No puedo creer que viví para ver este día.",
  ui_story_5089_50891400_68_dialog_content = "Hmm. Tal vez es solo el tipo de cambio que provocas en otras personas.",
  ui_story_5089_50891400_69_dialog_content = "Has influenciado enormemente al Gran Mariscal, y yo no soy la excepción.",
  ui_story_5089_50891400_70_dialog_content = "...",
  ui_story_5089_50891400_71_dialog_content = "Cuídate.",
  ui_story_5089_50891400_72_dialog_content = "¡Lo haré!",
  ui_story_5089_50891400_73_dialog_content = "¡Ey! ¡Aqui!",
  ui_story_5089_50891400_74_dialog_content = "¡Aquí, aquí, PlayerName!",
  ui_story_5089_50891400_75_dialog_content = "Estoy aquí para decir adiós.",
  ui_story_5089_50891400_76_dialog_content = "¿El Coloso siempre ha despegado tan rápido?",
  ui_story_5089_50891400_77_dialog_content = "Oye—PlayerName!",
  ui_story_5089_50891400_78_dialog_content = "Cuídate mucho en tu viaje, ¿me oyes? Recuerda comer tres comidas completas al día, ¡y no llegues tarde a ninguna!",
  ui_story_5089_50891400_79_dialog_content = "¡Y más te vale traer a Vice de vuelta a casa sano y salvo también!",
  ui_story_5089_50891400_80_dialog_content = "Lo haré—¡Solo espera!",
  ui_story_5089_50891400_81_dialog_content = "¡Prometo que la traeré de vuelta segura!",
  ui_story_5089_50891400_82_dialog_content = "Ah, mocoso... Piensa que puede simplemente volar con uno de los mejores soldados de Illumina cuando quiera...",
  ui_story_5089_50891400_83_dialog_content = "¿No vas a decir adiós?",
  ui_story_5089_50891400_84_dialog_content = "No.",
  ui_story_5089_50891400_85_dialog_content = "Es un pájaro libre. No quiero agregarle cargas innecesarias.",
  ui_story_5089_50891400_86_dialog_content = "Lo que sucede a continuación es para que PlayerName decida. Después de todo, es su historia.",
  ui_story_5089_50891400_87_dialog_content = "Como su amigo, todo lo que puedo hacer es ofrecerle mis mejores deseos mientras despega.",
  ui_story_5089_50891400_88_dialog_content = "... Vamos. Tenemos muchas decisiones que tomar por nosotros mismos, ¿verdad?",
  ui_story_5089_50891400_89_dialog_content = "¿Despedida...?",
  ui_story_5089_50891400_90_dialog_content = "...",
  ui_story_5089_50891400_91_dialog_content = "Pero no hay nadie aquí en este momento... Lady Victoria, Paloma, Pasolo... Ninguno de ellos.",
  ui_story_5089_50891400_92_dialog_content = "Sí, pero todavía estás aquí, ¿verdad?",
  ui_story_5089_50891400_93_dialog_content = "Al menos, puedo verte una última vez antes de irme.",
  ui_story_5089_50891400_94_dialog_content = "Y eso es todo lo que podría pedir.",
  ui_story_5089_50891400_95_dialog_content = "Se sentiría como si faltara algo si no tuviéramos la oportunidad de despedirnos el uno del otro.",
  ui_story_5089_50891400_96_dialog_content = "¡¿?!",
  ui_story_5089_50891400_97_dialog_content = "Aunque es una pena que no pueda ver a Paloma...",
  ui_story_5089_50891400_98_dialog_content = "Quizás Victoria me ayude a entregar el mensaje, ella siempre lo sabe todo, ¿verdad?",
  ui_story_5089_50891400_99_dialog_content = "Y si eso no funciona—",
  ui_story_5089_50891400_100_dialog_content = "¡Oye—! ¡Maestro Ermitaño—!",
  ui_story_5089_50891400_101_dialog_content = "¡Por favor asegúrate de que Victoria y los demás reciban mi mensaje—!",
  ui_story_5089_50891400_102_dialog_content = "... ¿Con quién estás hablando?",
  ui_story_5089_50891400_103_dialog_content = "Jejeje... Alguien que entiende.",
  ui_story_5089_50891400_104_dialog_content = "...",
  ui_story_5089_50891400_105_dialog_content = "Yo...",
  ui_story_5089_50891400_106_dialog_content = "Espero que regreses sano y salvo algún día.",
  ui_story_5089_50891400_107_dialog_content = "¡Claro que sí!",
  ui_story_5089_50891400_108_dialog_content = "¡Adiós!",
  ui_story_5089_50891400_109_dialog_content = "Adiós.",
  ui_story_5089_50891400_110_dialog_content = "... Ahí. Esa debería ser la última.",
  ui_story_5089_50891400_111_dialog_content = "Esos son todos los suministros para tu viaje desde el Gremio Umbraton y... los Lovegators.",
  ui_story_5089_50891400_112_dialog_content = "No esperaba conseguir tantas cosas gratis solo por venir a Umbraton...",
  ui_story_5089_50891400_113_dialog_content = "Me da un poco de vergüenza aceptarlo.",
  ui_story_5089_50891400_114_dialog_content = "Siempre has sido un amigo de Umbraton, y también para nosotros.",
  ui_story_5089_50891400_115_dialog_content = "Considéralo una muestra de esa amistad.",
  ui_story_5089_50891400_116_dialog_content = "¡Guau! ¡T-Tú me asustaste!",
  ui_story_5089_50891400_117_dialog_content = "¡Jajaja! No olvides, el lugar al que vas está mucho más allá de la mirada vigilante de las sombras de Umbraton.",
  ui_story_5089_50891400_118_dialog_content = "Ten cuidado en todo lo que haces.",
  ui_story_5089_50891400_119_dialog_content = "Lo haré.",
  ui_story_5089_50891400_120_dialog_content = "... Te dejo el resto a ti, Bethel.",
  ui_story_5089_50891400_121_dialog_content = "...",
  ui_story_5089_50891400_122_dialog_content = "Luke, Smokey, Genevieve y Naroxel todos te están esperando en la parte de atrás.",
  ui_story_5089_50891400_123_dialog_content = "Como una de las celebridades más famosas de Astra, todos quieren despedirse en persona.",
  ui_story_5089_50891400_124_dialog_content = "Entiendo...",
  ui_story_5089_50891400_125_dialog_content = "Supongo que eso significa que debería ofrecerles una despedida adecuada.",
  ui_story_5089_50891400_126_dialog_content = "Y tú también, Bethel.",
  ui_story_5089_50891400_127_dialog_content = "¡...!",
  ui_story_5089_50891400_128_dialog_content = "... ¿De verdad te irás por tanto tiempo?",
  ui_story_5089_50891400_129_dialog_content = "No puedo decirlo con seguridad. De hecho, ni siquiera sé si podré volver después.",
  ui_story_5089_50891400_130_dialog_content = "Pero sé que nunca olvidaré a ninguna de las grandes personas que conocí aquí.",
  ui_story_5089_50891400_131_dialog_content = "Entonces, si existe incluso una posibilidad de que pueda regresar, haré todo lo que pueda para que suceda.",
  ui_story_5089_50891400_132_dialog_content = "PlayerName...",
  ui_story_5089_50891400_133_dialog_content = "Por favor, cuídate.",
  ui_story_5089_50891400_134_dialog_content = "Y si me encuentro con alguna novela interesante en el camino, me aseguraré de traerlas de vuelta para ti también.",
  ui_story_5089_50891400_135_dialog_content = "¡Cuando llegue ese día, podemos pasar un rato leyendo en el café con todos!",
  ui_story_5089_50891400_136_dialog_content = "Pero por ahora...",
  ui_story_5089_50891400_137_dialog_content = "Adiós, Bethel.",
  ui_story_5089_50891400_138_dialog_content = "Lo encontré. Está por allí.",
  ui_story_5089_50891400_139_dialog_content = "¡PlayerName!",
  ui_story_5089_50891400_140_dialog_content = "¡Adiós!",
  ui_story_5089_50891400_141_dialog_content = "Ah...",
  ui_story_5089_50891400_142_dialog_content = "Adiós—",
  ui_story_5089_50891400_143_dialog_content = "Espero que siempre tengas música y esperanza para guiar tu camino....",
  ui_story_5089_50891400_144_dialog_content = "... Adiós.",
  ui_story_5089_50891400_145_dialog_content = "¿Eh? ¿Quieres venir también?",
  ui_story_5089_50891400_146_dialog_content = "No es que quiera ir contigo, per se...",
  ui_story_5089_50891400_147_dialog_content = "Pero explorar una tierra desconocida de fantasía suena como un momento interesante.",
  ui_story_5089_50891400_148_dialog_content = "Incluso a Antony le emociona la perspectiva, entonces ¿no es normal que esté un poco interesado?",
  ui_story_5089_50891400_149_dialog_content = "Deberías decir lo que tienes en mente, o podrías arrepentirte más tarde.",
  ui_story_5089_50891400_150_dialog_content = "...",
  ui_story_5089_50891400_151_dialog_content = "Como el Phospherus de Astra, permitirte embarcarte en un viaje tan peligroso es preocupante, por decir lo menos.",
  ui_story_5089_50891400_152_dialog_content = "Oh? ¿Entonces qué tal esto?",
  ui_story_5089_50891400_153_dialog_content = "¡Voy a buscar a cuatro luchadores más, y todos nosotros estaremos a tu mando!",
  ui_story_5089_50891400_154_dialog_content = "Tendremos cubierto cada elemento, y nada se interpondrá en nuestro camino...",
  ui_story_5089_50891400_155_dialog_content = "Aun así, he visto tu futuro.",
  ui_story_5089_50891400_156_dialog_content = "Y en ese lugar distante, aún posees un resplandor infinito.",
  ui_story_5089_50891400_157_dialog_content = "Tal vez ahí es donde realmente se encuentra tu batalla.",
  ui_story_5089_50891400_158_dialog_content = "Un lugar lleno de fantasía y realidad, donde lucharás por el mejoramiento de todos.",
  ui_story_5089_50891400_159_dialog_content = "Ese es tu propio camino.",
  ui_story_5089_50891400_160_dialog_content = "Y aunque nuestros corazones están llenos de preocupación por ti, todo lo que podemos hacer es ofrecerte nuestras bendiciones.",
  ui_story_5089_50891400_161_dialog_content = "Gracias. Tus buenos deseos me tranquilizan más de lo que sabes.",
  ui_story_5089_50891400_162_dialog_content = "¿Eh? ¿Así que no habrá más oportunidades para que subamos de nivel juntos? Realmente esperaba que pudiéramos tener más aventuras y derribar a algunos Espectros más.",
  ui_story_5089_50891400_163_dialog_content = "Honestamente, es tan aburrido por aquí.",
  ui_story_5089_50891400_164_dialog_content = "¿Estás disfrutando de tu tiempo aquí, eh, Freya?",
  ui_story_5089_50891400_165_dialog_content = "Supongo que es una forma de decirlo...",
  ui_story_5089_50891400_166_dialog_content = "Visité mi antiguo pueblo natal, me aseguré de que el \"tesoro\" aún estuviera seguro y me compré ropa nueva...",
  ui_story_5089_50891400_167_dialog_content = "Es como si el destino mismo me hubiera tocado el hombro.",
  ui_story_5089_50891400_168_dialog_content = "¡Pero eso no es suficiente para satisfacerme, tú sabes!",
  ui_story_5089_50891400_169_dialog_content = "¡Y sólo tenías que ir y aparecer con una nueva y emocionante aventura, solo para decirnos que no podemos ir contigo!",
  ui_story_5089_50891400_170_dialog_content = "Mis puños están tan ansiosos por pelear que duele...",
  ui_story_5089_50891400_171_dialog_content = "¿Qué tal si lanzamos un par de golpes antes de que te vayas, Navegador?",
  ui_story_5089_50891400_172_dialog_content = "Después de todo, mi sueño es—",
  ui_story_5089_50891400_173_dialog_content = "Adiós, Freya.",
  ui_story_5089_50891400_174_dialog_content = "...",
  ui_story_5089_50891400_175_dialog_content = "Viéndote sonreír tan feliz y sinceramente así...",
  ui_story_5089_50891400_176_dialog_content = "Realmente también tranquiliza mi corazón.",
  ui_story_5089_50891400_177_dialog_content = "... Asegúrate de darles una despedida adecuada, ¿de acuerdo?",
  ui_story_5089_50891400_178_dialog_content = "Lo haré.",
  ui_story_5089_50891400_179_dialog_content = "Adiós, Queen Bethlehem.",
  ui_story_5089_50891400_180_dialog_content = "Adiós.",
  ui_story_5089_50891400_181_dialog_content = "Los que deseas ver están fuera del palacio.",
  ui_story_5089_50891400_182_dialog_content = "Ve a conocerlos, PlayerName.",
  ui_story_5089_50891400_183_dialog_content = "Adiós, Zarya.",
  ui_story_5089_50891400_184_dialog_content = "Todavía quiero ir.",
  ui_story_5089_50891400_185_dialog_content = "¿Ah?",
  ui_story_5089_50891400_186_dialog_content = "N-Nada.",
  ui_story_5089_50891400_187_dialog_content = "Adiós...",
  ui_story_5089_50891400_188_dialog_content = "Vaya. Aquí, permíteme compartir contigo algo de mi sabiduría de anciano.",
  ui_story_5089_50891400_189_dialog_content = "¡Oye!",
  ui_story_5089_50891400_190_dialog_content = "Esta es una oportunidad rara, ¿sabes? Solo puedes jugar la carta de la joven alrededor del Queen y el Dios de la Montaña.",
  ui_story_5089_50891400_191_dialog_content = "¡Oye!",
  ui_story_5089_50891400_192_dialog_content = "... Así que esta es la parada final.",
  ui_story_5089_50891400_193_dialog_content = "PlayerName... Será mejor que vuelvas.",
  ui_story_5089_50891400_194_dialog_content = "Haré lo mejor que pueda, Leyn. ¿Me ayudarías a despedirme de los demás?",
  ui_story_5089_50891400_195_dialog_content = "Bueno, parece que es hora de dejar que los personajes principales tomen el escenario.",
  ui_story_5089_50891400_196_dialog_content = "Vamos, todos.",
  ui_story_5089_50891400_197_dialog_content = "...",
  ui_story_5089_50891400_198_dialog_content = "...",
  ui_story_5089_50891400_199_dialog_content = "¿Qué pasa? ¿No viniste a decir adiós?",
  ui_story_5089_50891400_200_dialog_content = "Lo hice, pero por alguna razón, no parece que pueda encontrar las palabras correctas para decir...",
  ui_story_5089_50891400_201_dialog_content = "¡Entonces déjame hablar a mí!",
  ui_story_5089_50891400_202_dialog_content = "¿Eh? ¿Maya?",
  ui_story_5089_50891400_203_dialog_content = "Espera un minuto... ¿¡Aquiles?! T-Tú no eres Maya!",
  ui_story_5089_50891400_204_dialog_content = "Está hablando desde detrás de mí—",
  ui_story_5089_50891400_205_dialog_content = "¡Vine tan pronto como supe que te ibas, PlayerName!",
  ui_story_5089_50891400_206_dialog_content = "Pero luego me perdí... ¡Afortunadamente, este grandullón tuvo la amabilidad de traerme aquí!",
  ui_story_5089_50891400_207_dialog_content = "Eso explica por qué no pude encontrarte antes...",
  ui_story_5089_50891400_208_dialog_content = "Si Jeno y Elvis supieran que estás corriendo así, estarían enfermos de preocupación.",
  ui_story_5089_50891400_209_dialog_content = "Ejem.",
  ui_story_5089_50891400_210_dialog_content = "Q-Quiero decir Elvis estaría triste.",
  ui_story_5089_50891400_211_dialog_content = "¡Eso es Laird Elvis para ti, señor!",
  ui_story_5089_50891400_212_dialog_content = "Tos, tos.",
  ui_story_5089_50891400_213_dialog_content = "Así que, ¿has tomado tu decisión entonces?",
  ui_story_5089_50891400_214_dialog_content = "Porque una vez que te vayas, no podremos ayudarte.",
  ui_story_5089_50891400_215_dialog_content = "Lo sé, pero no siempre puedo confiar en todos.",
  ui_story_5089_50891400_216_dialog_content = "...",
  ui_story_5089_50891400_217_dialog_content = "A todos se les ha dado la oportunidad de un nuevo futuro...",
  ui_story_5089_50891400_218_dialog_content = "Espero que puedas pasar el resto de tus días exactamente de la manera que quieres pasarlos.",
  ui_story_5089_50891400_219_dialog_content = "Ya veo... ¿Y qué pasa si algunos de nosotros queremos pasar esos días a tu lado?",
  ui_story_5089_50891400_220_dialog_content = "¿Cómo?",
  ui_story_5089_50891400_221_dialog_content = "Si nos confías el derecho a elegir, entonces debes valorar cada una de nuestras opiniones.",
  ui_story_5089_50891400_222_dialog_content = "Algunos de nosotros podemos estar reacios a dejarte.",
  ui_story_5089_50891400_223_dialog_content = "Algunos de nosotros puede que no queramos dejar ir las aventuras que hemos compartido contigo.",
  ui_story_5089_50891400_224_dialog_content = "Aquellos de nosotros que nos sentimos así, podríamos querer seguir luchando a tu lado.",
  ui_story_5089_50891400_225_dialog_content = "Y puede que seamos suficientes para llenar cada habitación a bordo de tu Coloso.",
  ui_story_5089_50891400_226_dialog_content = "¿De verdad crees eso?",
  ui_story_5089_50891400_227_dialog_content = "¡Entonces yo también quiero ir!",
  ui_story_5089_50891400_228_dialog_content = "¡Y si no hay suficiente espacio para mí, puedo hacer que mi antepasado me lleve!",
  ui_story_5089_50891400_229_dialog_content = "¿Pero qué pasa con el acuario?",
  ui_story_5089_50891400_230_dialog_content = "... ¡Oh, no!!!",
  ui_story_5089_50891400_231_dialog_content = "Estaba tan preocupado por PlayerName y su viaje que ¡totalmente lo olvidé!",
  ui_story_5089_50891400_232_dialog_content = "Oh...",
  ui_story_5089_50891400_233_dialog_content = "Realmente no tienes que forzarte, Maya.",
  ui_story_5089_50891400_234_dialog_content = "Esto no es algo que se deba decidir en un corto período de tiempo.",
  ui_story_5089_50891400_235_dialog_content = "No tienes que apresurar tu decisión. No cambiará la forma en que pienso de ti si decides no ir.",
  ui_story_5089_50891400_236_dialog_content = "¿En serio?",
  ui_story_5089_50891400_237_dialog_content = "En serio.",
  ui_story_5089_50891400_238_dialog_content = "Entonces... Te estaré esperando de vuelta en el acuario.",
  ui_story_5089_50891400_239_dialog_content = "Muy bien, es un trato.",
  ui_story_5089_50891400_240_dialog_content = "¡Genial! ¡Volveré y le diré a Jeno y Elvis de inmediato!",
  ui_story_5089_50891400_241_dialog_content = "¡EJEM—!",
  ui_story_5089_50891400_242_dialog_content = "Parece que estás empezando a entender ahora.",
  ui_story_5089_50891400_243_dialog_content = "Decir \"adiós\" significa que tenemos que seguir nuestros caminos separados por un tiempo.",
  ui_story_5089_50891400_244_dialog_content = "Pero ese tiempo no necesariamente tiene que durar para siempre.",
  ui_story_5089_50891400_245_dialog_content = "Y dado que esperas volver algún día, no hay necesidad de que tus \"adioses\" pesen tanto en tu corazón.",
  ui_story_5089_50891400_246_dialog_content = "Tampoco deberías forzarte a decir esas palabras.",
  ui_story_5089_50891400_247_dialog_content = "Después de todo, tu historia está lejos de terminar.",
  ui_story_5089_50891400_248_dialog_content = "Entonces haz tus elecciones y guía tu historia hacia el final perfecto en tu corazón.",
  ui_story_5089_50891400_249_dialog_content = "Aquiles...",
  ui_story_5089_50891400_250_dialog_content = "Adiós, PlayerName.",
  ui_story_5089_50891400_251_dialog_content = "May el último Caelestite vuela más alto en el cielo que nunca antes.",
  ui_story_5089_50891400_252_dialog_content = "...",
  ui_story_5089_50891400_253_dialog_content = "...",
  ui_story_5089_50891400_254_dialog_content = "Carleen, yo...",
  ui_story_5089_50891400_255_dialog_content = "Soroz está aquí.",
  ui_story_5089_50891400_256_dialog_content = "Lo que significa que es hora de partir, ¿verdad?",
  ui_story_5089_50891400_257_dialog_content = "Sí.",
  ui_story_5089_50891400_258_dialog_content = "... Es justo como cuando nos conocimos por primera vez.",
  ui_story_5089_50891400_259_dialog_content = "Tú, Soroz, Vice y yo, todos en Lumopolis...",
  ui_story_5089_50891400_260_dialog_content = "...",
  ui_story_5089_50891400_261_dialog_content = "Buenob—",
  ui_story_5089_50891400_262_dialog_content = "Ven con nosotros, Carleen.",
  ui_story_5089_50891400_263_dialog_content = "¿Justo como todo comenzó?",
  ui_story_5089_50891400_264_dialog_content = "Exactamente así.",
  ui_story_5089_50891400_265_dialog_content = "...",
  ui_story_5089_50891400_266_dialog_content = "Entonces vamos, PlayerName!",
  ui_story_5089_50891400_267_dialog_content = "¿Por qué has tardado tanto, PlayerName?",
  ui_story_5089_50891400_268_dialog_content = "¡Estoy empezando a marearme de recoger toda tu holgazanería!",
  ui_story_5089_50891400_269_dialog_content = "Vice, yo...",
  ui_story_5089_50891400_270_dialog_content = "Sabía que vendrías, Carleen.",
  ui_story_5089_50891400_271_dialog_content = "Simplemente no esperaba que tomara tanto tiempo.",
  ui_story_5089_50891400_272_dialog_content = "Bueno, no es agradable arrastrar a las personas sin una explicación adecuada...",
  ui_story_5089_50891400_273_dialog_content = "¿Te refieres a lo que me hiciste?",
  ui_story_5089_50891400_274_dialog_content = "Lo juro, actúas como si no nos conociéramos ya.",
  ui_story_5089_50891400_275_dialog_content = "Vas a herir los sentimientos de la gente si sigues actuando así.",
  ui_story_5089_50891400_276_dialog_content = "Suspiro...",
  ui_story_5089_50891400_277_dialog_content = "¿Hay algo más con lo que necesites ayuda?",
  ui_story_5089_50891400_278_dialog_content = "No, estamos casi listos. Todo lo que queda es establecer nuestro destino.",
  ui_story_5089_50891400_279_dialog_content = "Nuestro destino... ¿Te refieres a la \"tierra de fantasía\" que descubrimos anteriormente?",
  ui_story_5089_50891400_280_dialog_content = "Así es. Nos dirigimos directamente hacia esa grieta, la que donde los fragmentos de memoria de Vice volaron. Ha estado llamándome.",
  ui_story_5089_50891400_281_dialog_content = "Y después de haber hecho que Migard, Victoria, la santa, y algunas otras partes lo investiguen, hemos confirmado casi por completo que hay un mundo completamente diferente en el otro lado.",
  ui_story_5089_50891400_282_dialog_content = "Me han dicho que este otro mundo está prácticamente desbordado de N-materia.",
  ui_story_5089_50891400_283_dialog_content = "Eso es correcto, lo que significa que debe ser un mundo extremadamente realista. La materia X que compone los mundos de fantasía es prácticamente indetectable.",
  ui_story_5089_50891400_284_dialog_content = "Debería ser un lugar bastante seguro, pero aún está envuelto en misterio.",
  ui_story_5089_50891400_285_dialog_content = "Por eso no quiero permitir que otras personas vengan conmigo.",
  ui_story_5089_50891400_286_dialog_content = "Pero... Mis amigos... No son solo \"otras personas.\"",
  ui_story_5089_50891400_287_dialog_content = "Oye, eso me recuerda. ¿Por qué seguimos llamándolo \"tierra de fantasía\"?",
  ui_story_5089_50891400_288_dialog_content = "Bueno... Al final del día, así es como Bethlehem lo describió—",
  ui_story_5089_50891400_289_dialog_content = "Cuando se compara con nuestro mundo, es posible que el otro mundo sea el mundo real...",
  ui_story_5089_50891400_290_dialog_content = "Y sin embargo, comparte un vínculo fascinante e inseparable con Astra.",
  ui_story_5089_50891400_291_dialog_content = "Esta es finalmente la razón por la cual los recuerdos de Vice fluyeron hacia él. La verdad que buscas también se encuentra en ese mundo, Celestita.",
  ui_story_5089_50891400_292_dialog_content = "Quizás, en esa realidad, existe una fantasía correspondiente.",
  ui_story_5089_50891400_293_dialog_content = "Esto implica que incluso en el mundo \"real\", las personas aún pueden conjurar hermosas \"fantasías\" de la nada.",
  ui_story_5089_50891400_294_dialog_content = "Su anhelo por lo imaginario finalmente condujo a la conexión de nuestros dos mundos.",
  ui_story_5089_50891400_295_dialog_content = "... Pero no vamos allí para terminar esas fantasías.",
  ui_story_5089_50891400_296_dialog_content = "No vamos a aceptar su mundo como la única realidad, tampoco.",
  ui_story_5089_50891400_297_dialog_content = "Al final, simplemente nos embarcamos en un nuevo viaje hacia lo desconocido, persiguiendo los hermosos sueños que también anhelamos.",
  ui_story_5089_50891400_298_dialog_content = "Incluso si solo podemos lograr eso en el mundo real, realmente creo que lo haremos realidad algún día.",
  ui_story_5089_50891400_299_dialog_content = "¡Y cuando llegue ese momento, todos volveremos a Astra!",
  ui_story_5089_50891400_300_dialog_content = "Para ser honesto, tampoco entiendo realmente esta forma de pensar.",
  ui_story_5089_50891400_301_dialog_content = "Simplemente estoy feliz de unirme a todos en otra aventura más.",
  ui_story_5089_50891400_302_dialog_content = "Yo también.",
  ui_story_5089_50891400_303_dialog_content = "Puede que no hable mucho, pero por favor recuerda incluirme también.",
  ui_story_5089_50891400_304_dialog_content = "¿Cómo podríamos olvidarlo?",
  ui_story_5089_50891400_305_dialog_content = "¡Especialmente después de lo difícil que fue encontrarte de nuevo!",
  ui_story_5089_50891400_306_dialog_content = "Entonces, por favor establece las coordenadas para nuestro nuevo destino.",
  ui_story_5089_50891400_307_dialog_content = "Vice.",
  ui_story_5089_50891400_308_dialog_content = "¡Sí! ¿Quieres unirte a nosotros esta vez, Carleen?",
  ui_story_5089_50891400_309_dialog_content = "Pero no puedo jugar...",
  ui_story_5089_50891400_310_dialog_content = "Oh, eso no importa. Solo queda un poco de esta fantasía final, después de todo.",
  ui_story_5089_50891400_311_dialog_content = "¡Ella tiene razón! Vice y yo podemos guiarte a través de esto siempre que pongas tu corazón en ello.",
  ui_story_5089_50891400_312_dialog_content = "... Entendido.",
  ui_story_5089_50891400_313_dialog_content = "Está bien.",
  ui_story_5089_50891400_314_dialog_content = "¡Vamos!",
  ui_story_5089_50891400_315_dialog_content = "Adiós, Astra.",
  ui_story_5089_50891400_316_dialog_content = "Adiós a todos los que viajaron a través de este hermoso sueño conmigo.",
  ui_story_5089_50891400_317_dialog_content = "¡Hasta la próxima!",
  ui_story_5089_50891400_318_dialog_content = "EL FIN",
  ui_story_5089_50891400_319_dialog_content = "Gracias por jugar."
}
return config
